INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.1.a', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 1', 'Struktur organisasi serta wewenang representasi pemilik/dewan pengawas dijelaskan di dalam aturan internal rumah sakit (Hospital Bylaws) yang ditetapkan oleh pemilik rumah sakit.', 'Representasi pemilik/dewan pengawas memiliki tugas pokok dan fungsi secara khusus dalam pengolaan rumah sakit yang diatur dalam peraturan internal rumah sakit atau Hospital Bylaws. Sedangkan struktur organisasi pemilik terpisah dengan struktur organisasi rumah sakit sesuai dengan bentuk badan hukum pemilik, serta untuk rumah sakit milik pemerintah pusat (K/L) dan rumah sakit milik pemerintah daerah sesuai dengan ketentuan peraturan perundang- undangan. Pemilik rumah sakit tidak diperbolehkan menjadi pimpinan rumah sakit. Pemilik rumah sakit mengembangkan sebuah proses untuk melakukan komunikasi dan kerja sama dengan pimpinan Rumah Sakit dalam rangka mencapai misi dan perencanaan rumah sakit. Representasi pemilik/dewan pengawas ditetapkan oleh Pemilik rumah sakit, sesuai dengan bentuk badan hukum kepemilikan rumah sakit. Sebagai representasi dari pemilik, secara umum dewan pengawas melakukan pengawasan kualitas pelayanan kesehatan yang diberikan rumah sakit dengan memastikan standar pelayanan dipatuhi, mengawasi dan terlibat dalam perencanaan dan pengembangan strategis rumah sakit, menyediakan pelaporan dan akuntabilitas kepada pemangku kepentingan terkait, memastikan kepatuhan rumah sakit terhadap peraturan perundang-undangan, serta menjamin rumah sakit memperhatikan hak dan keselamatan pasien Dalam melaksanakan fungsi Dewan Pengawas bertugas: a. menentukan arah kebijakan Rumah Sakit; b. menyetujui dan mengawasi pelaksanaan rencana strategis; c. menilai dan menyetujui pelaksanaan rencana anggaran; d. mengawasi pelaksanaan kendali mutu dan kendali biaya dalam penyelenggaraan pelayanan; e. mengawasi dan menjaga hak dan kewajiban pasien; f. mengawasi dan menjaga hak dan kewajiban Rumah Sakit; dan g. mengawasi kepatuhan penerapan etika Rumah Sakit, etika profesi, dan peraturan perundang-undangan; Berdasarkan hal tersebut, Hospital Bylaws/peraturan internal rumah sakit yang telah disusun dan akan ditetapkan oleh Direktur/kepala rumah sakit harus memdapatkan persetujuan dari representasi pemilik/dewan pengawas, yang selanjutnya pemberlakuannya dilakukan oleh Pemilik Penyusunan Hospital Bylaws/peraturan internal rumah sakit dilakukan sesuai dengan ketentuan peraturan perundang- undangan. Dalam rangka peningkatan mutu dan keselamatan pasien, representasi pemilik/dewan pengawas harus menyetujui program PMKP rumah sakit dan melakukan pengkajian laporan hasil pelaksanaan program setiap 3 (tiga) bulan sekali, untuk program manajemen resiko setiap 6 (enam) bulan serta memberikan umpan balik perbaikan yang harus dilaksanakan dan hasilnya di evaluasi kembali pada pertemuan berikutnya secara tertulis. Struktur organisasi rumah sakit, disusun dan ditetapkan sesuai dengan ketentuan peraturan perundangan dan sangat bergantung pada kemampuan dan kebutuhan pelayanan rumah sakit.', 1, 'Representasi pemilik/Dewan Pengawas dipilih dan ditetapkan Pemilik/Dewan Pengawas oleh Pemilik. oleh pemilik.', 'Penetapan Representasi', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
