INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.7.a', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 7', 'Pimpinan rumah sakit membuat keputusan tentang pengadaan dan pembelian. Penggunaan sumber daya manusia dan sumber daya lainnya harus berdasarkan pertimbangan mutu dan dampaknya pada keselamatan.', 'Pimpinan rumah sakit akan mengutamakan mutu dan keselamatan pasien daripada biaya pada saat akan mengambil keputusan terkait pembelian dan keputusan terhadap sumber daya lainnya seperti pengurangan atau pemindahan staf keperawatan. Misalnya pada saat diputuskan untuk membeli pompa infus baru, maka informasi tingkat kegagalan dan insiden keselamatan pasien terkait alat yang akan dibeli, preferensi dari staf, catatan terkait adanya masalah dengan alarm dari pompa infus, pemeliharaan alat, pelatihan yang diperlukan dan hal lain terkait mutu dan keselamatan pasien di pakai sebagai dasar untuk membuat keputusan pembelian. Pimpinan rumah sakit mengembangkan proses untuk mengumpulkan data dan informasi untuk pembelian ataupun keputusan mengenai sumber daya untuk memastikan bahwa keputusannya sudah berdasarkan pertimbangan mutu dan keselamatan. Data terkait keputusan mengenai sumber daya adalah memahami kebutuhan dan rekomendasi peralatan medis, perbekalan dan obat-obatan yang dibutuhkan untuk pelayanan. Rekomendasi dapat diperoleh dari pemerintah, organisasi profesional nasional dan internasional serta sumber berwenang lainnya. Investasi untuk teknologi informasi kesehatan (TIK) merupakan sumber daya yang penting bagi rumah sakit. TIK meliputi berbagai teknologi yang mencakup metode pendokumentasian dan penyebaran informasi pasien, termasuk rekam medis elektronik. Selain itu, TIK juga meliputi metode untuk menyimpan dan menganalisis data, konfirmasi antar praktisi kesehatan agar dapat mengkoordinasikan pelayanan lebih baik, serta untuk menerima informasi yang dapat membantu menegakkan diagnosis dan memberikan pelayanan yang aman bagi pasien. Implementasi sumber daya TIK membutuhkan arahan, dukungan, dan pengawasan dari pimpinan rumah sakit. Ketika keputusan mengenai pengadaan sumber daya dibuat oleh pihak ketiga misalnya Kementerian Kesehatan, maka pimpinan rumah sakit menginformasikan kepada Kementerian Kesehatan pengalaman dan preferensi sumber daya tersebut sebagai dasar untuk membuat Keputusan.', 30, 'Pimpinan rumah sakit menggunakan data dan informasi mutu serta dampak informasi mutu serta dampak terhadap keselamatan dalam terhadap keselamatan untuk menyusun kajian pembelian membuat keputusan pembelian dan penggunaan alat baru dan penggunaan peralatan baru. umah sakit. Staf terkait', 'Bukti penggunaan data dan Pimpinan Rumah Sakit', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
