INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.8.a', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 8', 'Komite Medik, Komite Keperawatan dan Komite Tenaga Kesehatan Lain menerapkan pengorganisasisannya sesuai peraturan perundang-undangan untuk mendukung tanggung jawab serta wewenang mereka', 'Struktur organisasi Komite Medik, Komite Keperawatan, dan Komite Tenaga Kesehatan Lain ditetapkan oleh Direktur sesuai peraturan perundang-undangan yang berlaku. Dalam menjalankan fungsinya, Komite Medik, Komite Keperawatan dan Komite Tenaga Kesehatan Lain mempunyai tanggung jawab kepada pasien dan kepada rumah sakit yaitu: a) Mendukung komunikasi yang efektif antar tenaga profesional; b) Menyusun kebijakan, pedoman, prosedur serta protokol, tata hubungan kerja, alur klinis, dan dokumen lain yang mengatur layanan klinis; c) Menyusun kode etik profesi; dan d) Memantau mutu pelayanan pasien lainnya.', 40, 'Terdapat struktur organisasi Komite Medik, Komite Medik, Komite Keperawatan, Keperawatan, dan Komite Komite Tenaga Kesehatan lain Tenaga Kesehatan Lain yang oleh Direktur sesuai peraturan ditetapkan Direktur sesuai perundangan yang berlaku. peraturan perundang- undangan yang berlaku.', 'Penetapan tentang Komite', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
