INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.8.c', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 8', 'Komite Medik, Komite Keperawatan dan Komite Tenaga Kesehatan Lain menerapkan pengorganisasisannya sesuai peraturan perundang-undangan untuk mendukung tanggung jawab serta wewenang mereka', 'Struktur organisasi Komite Medik, Komite Keperawatan, dan Komite Tenaga Kesehatan Lain ditetapkan oleh Direktur sesuai peraturan perundang-undangan yang berlaku. Dalam menjalankan fungsinya, Komite Medik, Komite Keperawatan dan Komite Tenaga Kesehatan Lain mempunyai tanggung jawab kepada pasien dan kepada rumah sakit yaitu: a) Mendukung komunikasi yang efektif antar tenaga profesional; b) Menyusun kebijakan, pedoman, prosedur serta protokol, tata hubungan kerja, alur klinis, dan dokumen lain yang mengatur layanan klinis; c) Menyusun kode etik profesi; dan d) Memantau mutu pelayanan pasien lainnya.', 42, 'Untuk melaksanakan tanggung jawabnya Komite Medik, Komite Komite Keperawatan, Komite Keperawatan, dan Komite Tenaga Kesehatan Lain, yang Tenaga Kesehatan Lain ditetapkan oleh Direktur setiap menyusun Program kerja setiap tahunnya. tahun dan ditetapkan oleh Direktur h. Akuntabilitas Kepala Unit Klinis/Non Klinis', 'Program kerja Komite Medik,', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.9.a', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 9', 'Unit layanan di rumah sakit dipimpin oleh kepala unit yang ditetapkan oleh Direktur sesuai dengan kompetensinya untuk mengarahkan kegiatan di unitnya', 'Kinerja yang baik di unit layanan membutuhkan kepemimpinan yang kompeten dalam melaksanakan tanggung jawabnya yang dituangkan dalam urain tugas. Setiap kepala unit merencanakan dan melaporkan kebutuhan staf dan sumber daya misalnya ruangan, peralatan dan sumber daya lainnya kepada pimpinan rumah sakit untuk memenuhi pelayanan sesuai kebutuhan pasien. Meskipun para kepala unit layanan telah membuat rencana kebutuhan sumber daya manusia dan sumber daya lainnya, namun terkadang terdapat perubahan prioritas di dalam rumah sakit yang mengakibatkan tidak terpenuhinya sumber daya yang dibutuhkan. Oleh karena itu, kepala unit harus memiliki proses untuk merespon kekurangan sumber daya agar memastikan pemberian pelayanan yang aman dan efektif bagi semua pasien. Kepala unit layanan menyusun kriteria berdasarkan pendidikan, keahlian, pengetahuan, dan pengalaman yang diperlukan professional pemberi asuhan (PPA) dalam memberikan pelayanan di unit layanan tersebut. Kepala unit layanan juga bekerja sama dengan Unit SDM dan unit lainnya dalam melakukan proses seleksi staf. Kepala unit layanan memastikan bahwa semua staf dalam unitnya memahami tanggung jawabnya dan mengadakan kegiatan orientasi dan pelatihan bagi staf baru. Kegiatan orientasi mencakup misi rumah sakit, lingkup pelayanan yang diberikan, serta kebijakan dan prosedur yang terkait pelayanan yang diberikan di unit tersebut, misalnya semua staf telah memahami prosedur pencegahan dan pengendalian infeksi rumah sakit dan di unit layanan tersebut. Bila terdapat revisi kebijakan atau prosedur baru, staf akan diberikan pelatihan ulang. Para kepala unit kerja menyusun program kerja di masingmasing unit setiap tahun, menggunakan format yang seragam yang telah ditetapkan rumah sakit. Kepala unit kerja melakukan koordinasi dan integrasi dalam unitnya dan antar unit layanan untuk mencegah duplikasi pelayanan, misalnya koordinasi dan integrasi antara pelayanan medik dan pelayanan keperawatan.', 43, 'Kepala unit kerja diangkat sesuai kualifikasi dalam sesuai dengan persyaratan persyaratan jabatan yang jabatan yang ditetapkan rumah ditetapkan sakit.', 'Penetapan Kepala unit kerja,', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
