INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.10.d', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 10', 'Kepala unit layanan berpartisipasi dalam meningkatkan mutu dan keselamatan pasien dengan melakukan pengukuran indikator mutu rumah sakit yang dapat diterapkan di unitnya dan memantau serta memperbaiki pelayanan pasien di unit layanannya.', 'Kepala unit layanan melibatkan semua stafnya dalam kegiatan pengukuran indikator prioritas rumah sakit yang perbaikan akan berdampak luas/menyeluruh di rumah sakit baik kegiatan klinis maupun non klinis yang khusus untuk unit layanan tersebut. Misalnya indikator prioritas rumah sakit adalah komunikasi saat serah terima yang perbaikannya akan berdampak luas/menyeluruh di semua unit klinis maupun non klinis. Hal yang sama juga dapat dilakukan pada unit non klinis untuk memperbaiki komunikasi serah terima dengan menerapkan proyek otomatisasi untuk memonitor tingkat keakurasian saat pembayaran pasien. Kepala unit klinis memilih indikator mutu yang akan dilakukan pengukuran sesuai dengan pelayanan di unitnya mencakup hal- hal sebagai berikut: a) Pengukuran indikator nasional mutu (INM). b) Pengukuran indikator mutu prioritas rumah sakit (IMP-RS) yang berdampak luas dan menyeluruh di rumah sakit. c) Pengukuran indikator mutu prioritas unit (IMP-unit) untuk mengurangi variasi, meningkatkan keselamatan pada prosedur/tindakan berisiko tinggi dan meningkatkan kepuasan pasien serta efisiensi sumber daya. Pemilihan pengukuran berdasarkan pelayanan dan bisnis proses yang membutuhkan perbaikan di setiap unit layanan. Setiap pengukuran harus ditetapkan target yang diukur dan dianalisis capaian dan dapat dipertahankan dalam waktu 1 (satu) tahun. Jika target telah tercapai dan dapat dipertahankan untuk dalam waktu 1 (satu) tahun maka dapat diganti dengan indikator yang baru. Kepala unit layanan klinis dan non klinis bertanggung jawab memberikan penilaian kinerja staf yang bekerja di unitnya. Karena itu penilaian kinerja staf harus mencakup kepatuhan terhadap prioritas perbaikan mutu di unit yaitu indikator mutu prioritas unit (IMP-unit) sebagai upaya perbaikan di setiap unit untuk meningkatkan mutu dan keselamatan pasien tingkat unit.', 51, 'Kepala unit klinis/non klinis memilih prioritas perbaikan yang dipilih, bila perbaikan telah baru bila perbaikan sebelumnya dapat dipertahankan 1 tahun sudah dapat dipertahankan (lihat PMKP 6) TDD dalam waktu 1 (satu) tahun', 'Bukti IMP Unit baru telah', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.11.a', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 11', 'Kepala unit klinis mengevaluasi kinerja para dokter, perawat dan tenaga kesehatan profesional lainnya menggunakan indikator mutu yang diukur di unitnya', 'Kepala unit klinis bertanggung jawab untuk memastikan bahwa mutu pelayanan yang diberikan oleh stafnya dilakukan secara konsisten dengan melakukan evaluasi kinerja terhadap stafnya. Kepala unit klinis juga terlibat dalam memberikan rekomendasi tentang penunjukan, delineasi kewenangan, evaluasi praktik profesional berkelanjutan (On going Professional Practice Evaluation), serta penugasan kembali dokter/perawat/tenaga kesehatan lain yang bertugas dalam unitnya.', 52, 'Penilaian praktik profesional berkelanjutan (On going profesional berkelanjutan Professional Practice Evaluation) (On going Professional para dokter dalam memberikan Practice Evaluation) para pelayanan untuk meningkatkan dokter. mutu dan keselamatan pasien (lihat KPS 12c). menggunakan indikator mutu yang diukur di unit tersebut.', 'Bukti penilaian praktik', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.11.b', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 11', 'Kepala unit klinis mengevaluasi kinerja para dokter, perawat dan tenaga kesehatan profesional lainnya menggunakan indikator mutu yang diukur di unitnya', 'Kepala unit klinis bertanggung jawab untuk memastikan bahwa mutu pelayanan yang diberikan oleh stafnya dilakukan secara konsisten dengan melakukan evaluasi kinerja terhadap stafnya. Kepala unit klinis juga terlibat dalam memberikan rekomendasi tentang penunjukan, delineasi kewenangan, evaluasi praktik profesional berkelanjutan (On going Professional Practice Evaluation), serta penugasan kembali dokter/perawat/tenaga kesehatan lain yang bertugas dalam unitnya.', 53, 'Penilaian kinerja para perawat dalam memberikan pelayanan perawat untuk meningkatkan mutu dan (lihat KPS 16b) keselamatan pasien menggunakan indikator mutu yang diukur di unit tersebut.', 'Bukti penilaian kinerja', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.11.c', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 11', 'Kepala unit klinis mengevaluasi kinerja para dokter, perawat dan tenaga kesehatan profesional lainnya menggunakan indikator mutu yang diukur di unitnya', 'Kepala unit klinis bertanggung jawab untuk memastikan bahwa mutu pelayanan yang diberikan oleh stafnya dilakukan secara konsisten dengan melakukan evaluasi kinerja terhadap stafnya. Kepala unit klinis juga terlibat dalam memberikan rekomendasi tentang penunjukan, delineasi kewenangan, evaluasi praktik profesional berkelanjutan (On going Professional Practice Evaluation), serta penugasan kembali dokter/perawat/tenaga kesehatan lain yang bertugas dalam unitnya.', 54, 'Penilaian kinerja tenaga kesehatan lainnya memberikan tenaga kesehatan lainnya pelayanan untuk meningkatkan (lihat KPS 19b) mutu dan keselamatan pasien menggunakan indikator mutu yang diukur di unit tersebut i. Etika Rumah Sakit', 'Bukti penilaian kinerja', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.12.a', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 12', 'Pimpinan rumah sakit menetapkan kerangka kerja pengelolaan etik rumah sakit untuk menangani masalah etik rumah sakit meliputi finansial, pemasaran, penerimaan pasien, transfer pasien, pemulangan pasien dan yang lainnya termasuk konflik etik antar profesi serta konflik kepentingan staf yang mungkin b', '', 55, 'Direktur rumah sakit menetapkan Komite Etik rumah Rumah Sakit dilengkapi sakit. uraian tugas.', 'Penetapan Komite Etik', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.12.b', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 12', 'Pimpinan rumah sakit menetapkan kerangka kerja pengelolaan etik rumah sakit untuk menangani masalah etik rumah sakit meliputi finansial, pemasaran, penerimaan pasien, transfer pasien, pemulangan pasien dan yang lainnya termasuk konflik etik antar profesi serta konflik kepentingan staf yang mungkin b', '', 56, 'Komite Etik telah menyusun kode etik rumah sakit yang Rumah Sakit yang mengacu pada Kode Etik Rumah mengacu pada KODERSI. Sakit Indonesia (KODERSI) dan ditetapkan Direktur.', 'Penetapan Kode Etik', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.12.c', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 12', 'Pimpinan rumah sakit menetapkan kerangka kerja pengelolaan etik rumah sakit untuk menangani masalah etik rumah sakit meliputi finansial, pemasaran, penerimaan pasien, transfer pasien, pemulangan pasien dan yang lainnya termasuk konflik etik antar profesi serta konflik kepentingan staf yang mungkin b', '', 57, 'Komite Etik telah menyusun kerangka kerja pelaporan dan kerja pelaporan dan pengelolaan etik rumah sakit pengelolaan etik rumah serta pedoman pengelolaan kode etik rumah sakit meliputi poin (1) sakit meliputi poin 1) 12) sampai dengan (12) dalam dalam maksud dan tujuan. maksud dan tujuan sesuai dengan visi, misi, dan nilai-nilai yang dianut rumah sakit.', 'Regulasi tentang kerangka', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.12.d', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 12', 'Pimpinan rumah sakit menetapkan kerangka kerja pengelolaan etik rumah sakit untuk menangani masalah etik rumah sakit meliputi finansial, pemasaran, penerimaan pasien, transfer pasien, pemulangan pasien dan yang lainnya termasuk konflik etik antar profesi serta konflik kepentingan staf yang mungkin b', '', 58, 'Rumah sakit menyediakan sumber daya serta pelatihan tentang kerangka kerangka pengelolaan etik rumah pengelolaan etik sakit bagi praktisi kesehatan dan rumah sakit bagi staf lainnya dan memberikan praktisi kesehatan dan solusi yang efektif dan tepat staf lainnya waktu untuk masalah etik 2. Bukti penyediaan sumber daya 3. Bukti pelaporan masalah etik Etik Pimpinan Unit Diklat j. Kepemimpinan Untuk Budaya Keselamatan di Rumah Sakit', '1. Bukti pelatihan Ketua/Anggota Komite', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.13.a', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 13', 'Pimpinan rumah sakit menerapkan, memantau dan mengambil tindakan serta mendukung Budaya Keselamatan di seluruh area rumah sakit', 'Budaya keselamatan di rumah sakit merupakan suatu lingkungan kolaboratif di mana para dokter saling menghargai satu sama lain, para pimpinan mendorong kerja sama tim yang efektif dan menciptakan rasa aman secara psikologis serta anggota tim dapat belajar dari insiden keselamatan pasien, para pemberi layanan menyadari bahwa ada keterbatasan manusia yang bekerja dalam suatu sistem yang kompleks dan terdapat suatu proses pembelajaran serta upaya untuk mendorong perbaikan. Budaya keselamatan juga merupakan hasil dari nilai-nilai, sikap, persepsi, kompetensi, dan pola perilaku individu maupun kelompok yang menentukan komitmen terhadap, serta kemampuan mengelola pelayanan kesehatan maupun keselamatan. Keselamatan dan mutu berkembang dalam suatu lingkungan yang membutuhkan kerja sama dan rasa hormat satu sama lain, tanpa memandang jabatannya. Pimpinan rumah sakit menunjukkan komitmennya mendorong terciptanya budaya keselamatan tidak mengintimidasi dan atau mempengaruhi staf dalam memberikan pelayanan kepada pasien. Direktur menetapkan Program Budaya Keselamatan di rumah sakit yang mencakup: a) perilaku memberikan pelayanan yang aman secara konsisten untuk mencegah terjadinya kesalahan pada pelayanan berisiko tinggi. b) perilaku di mana para individu dapat melaporkan kesalahan dan insiden tanpa takut dikenakan sanksi atau teguran dan diperlakukan secara adil (just culture) c) kerja sama tim dan koordinasi untuk menyelesaikan masalah keselamatan pasien. d) komitmen pimpinan rumah sakit dalam mendukung staf seperti waktu kerja para staf, pendidikan, metode yang aman untuk melaporkan masalah dan hal lainnya untuk menyelesaikan masalah keselamatan. e) identifikasi dan mengenali masalah akibat perilaku yang tidak diinginkan (perilaku sembrono). f) evaluasi budaya secara berkala dengan metode seperti kelompok fokus diskusi (FGD), wawancara dengan staf, dan analisis data. g) mendorong kerja sama dan membangun sistem, dalam mengembangkan budaya perilaku yang aman. h) menanggapi perilaku yang tidak diinginkan pada semua staf pada semua jenjang di rumah sakit, termasuk manajemen, staf administrasi, staf klinis dan nonklinis, dokter praktisi mandiri, representasi pemilik dan anggota Dewan pengawas Perilaku yang tidak mendukung budaya keselamatan di antaranya adalah: perilaku yang tidak layak seperti katakata atau bahasa tubuh yang merendahkan atau menyinggung perasaan sesama staf, misalnya mengumpat dan memaki, perilaku yang mengganggu, bentuk tindakan verbal atau nonverbal yang membahayakan atau mengintimidasi staf lain, perilaku yang melecehkan (harassment) terkait dengan ras, agama, dan suku termasuk gender serta pelecehan seksual. Seluruh pemangku kepentingan di rumah sakit bertanggungjawab mewujudkan budaya keselamatan dengan berbagai cara. Saat ini di rumah sakit masih terdapat budaya menyalahkan orang lain ketika terjadi suatu kesalahan (blaming culture), yang akhirnya menghambat budaya keselamatan sehingga pimpinan rumah sakit harus menerapkan perlakuan yang adil (just culture) ketika terjadi kesalahan, dimana ada saatnya staf tidak disalahkan ketika terjadi kesalahan, misalnya pada kondisi: a) komunikasi yang kurang baik antara pasien dan staf. b) perlu pengambilan keputusan secara cepat. c) kekurangan staf dalam pelayanan pasien. Di sisi lain terdapat kesalahan yang dapat diminta pertanggungjawabannya ketika staf dengan sengaja melakukan perilaku yang tidak diinginkan (perilaku sembrono) misalnya: a) tidak mau melakukan kebersihan tangan. b) tidak mau melakukan time-out (jeda) sebelum operasi. c) tidak mau memberi tanda pada lokasi pembedahan. Rumah sakit harus meminta pertanggungjawaban perilaku yang tidak diinginkan (perilaku sembrono) dan tidak mentoleransinya. Pertanggungjawaban dibedakan atas: a) kesalahan manusia (human error) adalah tindakan yang tidak disengaja yaitu melakukan kegiatan tidak sesuai dengan apa yang seharusnya dilakukan. b) perilaku berisiko (risk behaviour) adalah perilaku yang dapat meningkatkan risiko (misalnya, mengambil langkah pada suatu proses layanan tanpa berkonsultasi dengan atasan atau tim kerja lainnya yang dapat menimbulkan risiko). c) perilaku sembrono (reckless behavior) adalah perilaku yang secara sengaja mengabaikan risiko yang substansial dan tidak dapat dibenarkan.', 59, 'Pimpinan rumah sakit menetapkan program budaya keselamatan yang mencakup keselamatan yang mencakup poin a) sampai dengan h) poin a) sampai dengan h) dalam maksud dan tujuan dalam maksud dan tujuan (lihat PMKP 10). serta mendukung penerapannya secara program budaya keselamatan akuntabel dan transparan.', 'Penetapan program budaya Bukti laporan pelaksanaan', 'D,R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.13.b', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 13', 'Pimpinan rumah sakit menerapkan, memantau dan mengambil tindakan serta mendukung Budaya Keselamatan di seluruh area rumah sakit', 'Budaya keselamatan di rumah sakit merupakan suatu lingkungan kolaboratif di mana para dokter saling menghargai satu sama lain, para pimpinan mendorong kerja sama tim yang efektif dan menciptakan rasa aman secara psikologis serta anggota tim dapat belajar dari insiden keselamatan pasien, para pemberi layanan menyadari bahwa ada keterbatasan manusia yang bekerja dalam suatu sistem yang kompleks dan terdapat suatu proses pembelajaran serta upaya untuk mendorong perbaikan. Budaya keselamatan juga merupakan hasil dari nilai-nilai, sikap, persepsi, kompetensi, dan pola perilaku individu maupun kelompok yang menentukan komitmen terhadap, serta kemampuan mengelola pelayanan kesehatan maupun keselamatan. Keselamatan dan mutu berkembang dalam suatu lingkungan yang membutuhkan kerja sama dan rasa hormat satu sama lain, tanpa memandang jabatannya. Pimpinan rumah sakit menunjukkan komitmennya mendorong terciptanya budaya keselamatan tidak mengintimidasi dan atau mempengaruhi staf dalam memberikan pelayanan kepada pasien. Direktur menetapkan Program Budaya Keselamatan di rumah sakit yang mencakup: a) perilaku memberikan pelayanan yang aman secara konsisten untuk mencegah terjadinya kesalahan pada pelayanan berisiko tinggi. b) perilaku di mana para individu dapat melaporkan kesalahan dan insiden tanpa takut dikenakan sanksi atau teguran dan diperlakukan secara adil (just culture) c) kerja sama tim dan koordinasi untuk menyelesaikan masalah keselamatan pasien. d) komitmen pimpinan rumah sakit dalam mendukung staf seperti waktu kerja para staf, pendidikan, metode yang am