INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('TKRS.15.c', 'TKRS', 1, 'Tata Kelola Rumah Sakit', 2, 'TKRS 15', 'Pimpinan rumah sakit bertanggung jawab terhadap mutu dan keamanan dalam program penelitian bersubjek manusia.', 'Penelitian bersubjek manusia merupakan sebuah proses yang kompleks dan signifikan bagi rumah sakit. Direktur menetapkan penanggung jawab penelitian di rumah sakit untuk melakukan pemantauan proses penelitian di rumah sakit (mis. Komite penelitian). Pimpinan rumah sakit harus memiliki komitmen yang diperlukan untuk menjalankan penelitian dan pada saat yang bersamaan melindungi pasien yang telah setuju untuk mengikuti proses pengobatan dan atau diagnostik dalam penelitian. Komitmen pemimpin unit terhadap penelitian dengan subjek manusia tidak terpisah dari komitmen mereka terhadap perawatan pasien-komitmen terintegrasi di semua tingkatan. Dengan demikian, pertimbangan etis, komunikasi yang baik, pemimpin unit dan layanan yang bertanggung jawab, kepatuhan terhadap peraturan, dan sumber daya keuangan dan non- keuangan merupakan komponen dari komitmen ini. Pimpinan rumah sakit mengakui kewajiban untuk melindungi pasien terlepas dari sponsor penelitian.', 69, 'Pimpinan rumah sakit telah mengidentifikasi fasilitas dan anggota tim peneliti sumber daya yang diperlukan berdasarkan untuk melakukan penelitian, kompetensinya. TDD termasuk di dalam nya kompetensi sumber daya yang sumber daya yang akan berpartisipasi di dalam diperlukan untuk penelitian sebagai pimpinan melakukan penelitian dan anggota tim peneliti', 'Penetapan ketua dan Bukti daftar fasilitas dan', 'D,R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
