INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.6.a', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 6', 'Terdapat informasi kepegawaian yang terdokumentasi dalam file kepegawaian setiap staf.', 'File kepegawaian yang terkini berisikan dokumentasi setiap staf rumah sakit yang mengandung informasi sensitif yang harus dijaga kerahasiaannya. File kepegawaian memuat: a) Pendidikan, kualifikasi, keterampilan, dan kompetensi staf. b) Bukti orientasi. c) Uraian tugas staf. d) Riwayat pekerjaan staf. e) Penilaian kinerja staf. f) Salinan sertifikat pelatihan di dalam maupun di luar rumah sakit yang telah diikuti. g) Informasi kesehatan yang dipersyaratkan, seperti vaksinasi/ imunisasi, hasil medical check up. File kepegawaian tersebut distandarisasi dan terus diperbarui sesuai dengan kebijakan rumah sakit.', 17, 'File kepegawaian staf distandardisasi dan dipelihara distandardisasi dan dipelihara serta dijaga kerahasiaannya serta dijaga kerahasiaannya sesuai dengan kebijakan sesuai dengan kebijakan rumah rumah sakit. sakit.', 'File kepegawaian staf', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
