INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.7.d', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 7', 'Semua staf diberikan orientasi mengenai rumah sakit dan unit tempat mereka ditugaskan dan tanggung jawab pekerjaannya pada saat pengangkatan staf.', 'Keputusan pengangkatan staf melalui sejumlah tahapan. Pemahaman terhadap rumah sakit secara keseluruhan dan tanggung jawab klinis maupun non klinis berperan dalam tercapainya misi rumah sakit. Hal ini dapat dicapai melalui orientasi kepada staf. Orientasi umum meliputi informasi tentang rumah sakit, program mutu dan keselamatan pasien, serta program pencegahan dan pengendalian infeksi. Orientasi khusus meliputi tugas dan tanggung jawab dalam melakukan pekerjaannya. Hasil orientasi ini dicatat dalam file kepegawaian. Staf paruh waktu, sukarelawan, dan mahasiswa atau trainee juga diberikan orientasi umum dan orientasi khusu', 22, 'Tenaga kontrak, paruh waktu, mahasiswa atau orientasi khusus untuk tenaga trainee dan sukarelawan kontrak, paruh waktu, telah diberikan orientasi mahasiswa atau trainee dan TDD umum dan orientasi sukarelawan. khusus (jika ada). mahasiswa atau trainee dan sukarelawan. b. Pendidikan dan pelatihan', 'Bukti orientasi umum dan Tenaga kontrak, paruh waktu,', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.8.a', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 8', 'Tiap staf diberikan pendidikan dan pelatihan yang berkelanjutan untuk mendukung atau meningkatkan keterampilan dan pengetahuannya.', 'Rumah sakit mengumpulkan data dari berbagai sumber dalam penyusunan Program pendidikan dan pelatihan untuk memenuhi kebutuhan pasien dan/atau memenuhi persyaratan pendidikan berkelanjutan. Sumber informasi untuk menentukan kebutuhan pendidikan staf mencakup: a) Hasil kegiatan pengukuran data mutu dan keselamatan pasien. b) Hasil analisis laporan insiden keselamatan pasien. c) Hasil survei budaya keselamatan pasien. d) Hasil pemantauan program manajemen fasilitas dan keselamatan. e) Pengenalan teknologi termasuk penambahan peralatan medis baru, keterampilan dan pengetahuan baru yang diperoleh dari penilaian kinerja. f) Prosedur klinis baru. g) Rencana untuk menyediakan layanan baru di masa yang akan datang. h) Kebutuhan dan usulan dari setiap unit. Rumah sakit memiliki suatu proses untuk mengumpulkan dan mengintegrasikan data dari berbagai sumber untuk merencanakan program pendidikan dan pelatihan staf. Selain itu, rumah sakit menentukan staf mana yang diharuskan untuk mendapatkan pendidikan berkelanjutan untuk menjaga kemampuan mereka dan bagaimana pendidikan staf tersebut akan dipantau dan didokumentasikan. Pimpinan rumah sakit meningkatkan dan mempertahankan kinerja staf dengan mendukung program pendidikan dan pelatihan termasuk menyediakan sarana prasarana termasuk peralatan, ruangan, tenaga pengajar, dan waktu. Program pendidikan dan pelatihan dibuat setiap tahun untuk memenuhi kebutuhan pasien dan/atau memenuhi persyaratan pendidikan berkelanjutan misalnya tenaga medis diberikan pelatihan PPI, perkembangan praktik medis, atau peralatan medis baru. Hasil pendidikan dan pelatihan staf didokumentasikan dalam file kepegawaian. Ketersediaan teknologi dan informasi ilmiah yang aktual tersedia untuk mendukung pendidikan dan pelatihan disediakan di satu atau beberapa lokasi yang yang tersebar di rumah sakit. Pelatihan diatur sedemikian rupa agar tidak mengganggu pelayanan pasien. 3) Elemen penilaian KPS 8', 23, 'Rumah sakit telah mengidentifikasi kebutuhan pendidikan staf berdasarkan pendidikan staf berdasarkan sumber berbagai informasi, sumber berbagai informasi, mencakup a) h) dalam maksud mencakup a) – h) dalam dan tujuan maksud dan tujuan.', 'Bukti hasil identifikasi kebutuhan', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
