INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.10.c', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 10', 'Rumah sakit menyelenggarakan proses kredensial yang seragam dan transparan bagi tenaga medis yang diberi izin memberikan asuhan kepada pasien secara mandiri.', '', 39, 'Rumah sakit telah melaksanakan proses pemberian kewenangan klinis kredensial dan pemberian kepada staf medis dari luar kewenangan klinis kepada rumah sakit. TDD dokter praktik mandiri dari luar rumah sakit seperti konsultasi kedokteran jarak jauh (telemedicine), radiologi jarak jauh (teleradiology), dan interpretasi untuk pemeriksaan diagnostik lain: elektrokardiogram (EKG), elektroencefalogram (EEG), elektromiogram (EMG), serta pemeriksaan lain yang serupa.', 'Bukti proses kredensial dan', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.10.d', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 10', 'Rumah sakit menyelenggarakan proses kredensial yang seragam dan transparan bagi tenaga medis yang diberi izin memberikan asuhan kepada pasien secara mandiri.', '', 40, 'Setiap tenaga medis yang memberikan pelayanan di medis sesuai dengan regulasi rumah sakit wajib rumah sakit. menandatangani perjanjian sesuai dengan regulasi rumah sakit.', 'Perjanjian kerja klinis tenaga', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.10.e', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 10', 'Rumah sakit menyelenggarakan proses kredensial yang seragam dan transparan bagi tenaga medis yang diberi izin memberikan asuhan kepada pasien secara mandiri.', '', 41, 'Rumah sakit telah melaksanakan verifikasi ke Lembaga/ Badan/ instansi Lembaga / Badan /Instansi pendidikan atau organisasi pendidikan atau organisasi profesional yang diakui yang profesional yang diakui yang mengeluarkan izin/sertifikat mengeluarkan izin/sertifikat, dan kredensial lain. dan kredensial lain dalam proses kredensial sesuai dengan peraturan perundang- undangan', 'Bukti pelaksanaan verifikasi ke', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.10.f', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 10', 'Rumah sakit menyelenggarakan proses kredensial yang seragam dan transparan bagi tenaga medis yang diberi izin memberikan asuhan kepada pasien secara mandiri.', '', 42, 'Ada bukti dilaksanakan kredensial tambahan ke sumber tenaga medis. yang mengeluarkan apabila tenaga medis yang meminta kewenangan klinis tambahan Komite Medik yang canggih atau ● Staf Tenaga Medis subspesialisasi.', 'Bukti kredensial tambahan ● Sub Komite Kredensial', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.10.1.a', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 10.1', 'Rumah sakit melaksanakan verifikasi terkini terhadap pendidikan, registrasi/izin, pengalaman, dan lainnya dalam proses kredensialing tenaga medis.', 'Penjelasan mengenai istilah dan ekspektasi yang ditemukan dalam standar-standar ini adalah sebagai berikut: a) Kredensial adalah proses evaluasi (memeriksa dokumen dari pelamar), wawancara, dan ketentuan lain sesuai dengan kebutuhan rumah sakit yang dilakukan rumah sakit terhadap seorang tenaga medis untuk menentukan apakah yang bersangkutan layak diberi penugasan klinis dan kewenangan klinis untuk menjalankan asuhan/tindakan medis tertentu di lingkungan rumah sakit tersebut untuk periode tertentu. Dokumen kredensial adalah dokumen yang dikeluarkan oleh badan resmi untuk menunjukkan bukti telah dipenuhinya persyaratan seperti ijazah dari fakultas kedokteran, surat tanda registrasi, izin praktik, fellowship, atau bukti pendidikan dan pelatihan yang telah mendapat pengakuan dari organisasi profesi kedokteran. Dokumen dokumen ini harus diverifikasi ke sumber utama yang mengeluarkan dokumen tersebut atau website verifikasi ijazah Kementerian Pendidikan, Kebudayaan, Riset dan Teknologi. b) Tenaga medis adalah semua dokter dan dokter gigi yang memberikan layanan promotif, preventif, kuratif, rehabilitatif, bedah, atau layanan medis/gigi lain kepada pasien, atau yang memberikan layanan interpretatif terkait pasien seperti patologi, radiologi, laboratorium, serta memiliki surat tanda registrasi (STR) dan surat izin praktik (SIP). c) Verifikasi adalah proses untuk memeriksa validitas dan kelengkapan kredensial dari sumber yang mengeluarkan kredensial. d) Rekredensial adalah proses kredensial ulang setiap 3 (tiga) tahun. e) Dokumen kredensial dan rekredensial meliputi: (1) STR, SIP yang masih berlaku; (2) File pelanggaran etik atau disiplin termasuk infomasi dari sumber luar seperti dari MKEK dan MKDKI; (3) Rekomendasi mampu secara fisik maupun mental memberikan asuhan kepada pasien tanpa supervisi dari profesi dokter yang ditentukan; (4) Bila tenaga medis mengalami gangguan kesehatan, kecacatan tertentu, atau proses penuaan yang menghambat pelaksanaan kerja maka kepada yang bersangkutan dilakukan penugasan klinis ulang; (5) Jika seorang anggota tenaga medis mengajukan kewenangan baru terkait pelatihan spesialisasi canggih atau subspesialisasi maka dokumen kredensial harus segera diverifikasi dari sumber yang mengeluarkan sertifikat tersebut. Keanggotaan tenaga medis mungkin tidak dapat diberikan jika rumah sakit tidak mempunyai teknologi, peralatan medis khusus untuk mendukung kewenangan klinis tertentu. Sebagai contoh, seorang nefrolog melamar untuk memberikan layanan dialisis di rumah sakit bila rumah sakit tidak memiliki pelayanan ini maka kewenangan klinis untuk melakukan haemodialisis tidak dapat diberikan. Pengecualian untuk KPS 10.1 EP 1, hanya untuk survei awal. Pada saat survei akreditasi awal rumah sakit diwajibkan telah menyelesaikan verifikasi untuk tenaga medis baru yang bergabung dalam 12 (dua belas) bulan menjelang survei awal. Selama 12 (dua belas) bulan setelah survei awal, rumah sakit diwajibkan untuk menyelesaikan verifikasi sumber primer untuk seluruh anggota tenaga medis lainnya. Proses ini dicapai dalam kurun waktu 12 (dua belas) bulan setelah survei sesuai dengan rencana yang memprioritaskan verifikasi kredensial bagi tenaga medis aktif yang memberikan pelayanan berisiko tinggi. Catatan: Pengecualian ini hanya untuk verifikasi kredensial saja. Semua kredensial anggota tenaga medis harus dikumpulkan dan ditinjau, dan kewenangan mereka diberikan. f) Pengangkatan/penugasan merupakan proses peninjauan kredensial awal pelamar untuk memutuskan apakah orang tersebut memenuhi syarat untuk memberikan pelayanan yang dibutuhkan pasien rumah sakit dan dapat didukung rumah sakit dengan staf yang kompeten dan dengan kemampuan teknis rumah sakit. Untuk pelamar pertama, informasi yang ditinjau kebanyakan berasal dari sumber luar. Individu atau mekanisme yang berperan pada peninjauan, kriteria yang digunakan untuk membuat keputusan, dan bagaimana keputusan didokumentasikan diidentifikasi dalam kebijakan rumah sakit. Kebijakan rumah sakit mengidentifikasi proses pengangkatan praktisi kesehatan mandiri untuk keperluan gawat darurat atau untuk sementara waktu. Pengangkatan dan identifikasi kewenangan untuk praktisi kesehatan tersebut tidak dibuat sampai setidaknya verifikasi izin telah dilakukan. g) Pengangkatan/penugasan kembali merupakan proses peninjauan dokumen anggota tenaga medis untuk verifikasi: (1) Perpanjangan izin; (2) Bahwa anggota tenaga medis tidak dikenai sanksi disipliner oleh badan perizinan dan sertifikasi; (3) Bahwa berkas berisi dokumentasi yang cukup untuk pencarian kewenangan atau tugas baru/perluasan di rumah sakit; dan (4) Anggota tenaga medis mampu secara fisik dan mental untuk memberikan perawatan dan tata laksana terhadap pasien tanpa supervisi. Informasi untuk peninjauan ini berasal dari sumber internal maupun eksternal. Jika suatu departemen/unit layanan klinis (misalnya, pelayanan subspesialis) tidak memiliki kepala/pimpinan, rumah sakit mempunyai kebijakan untuk mengidentifikasi siapa yang melakukan peninjauan untuk para tenaga profesional di departemen/unit layanan tersebut. Berkas kredensial anggota tenaga medis harus merupakan sumber informasi yang dinamis dan ditinjau secara konstan. Sebagai contoh, ketika anggota tenaga medis mendapatkan sertifikat pencapaian yang berhubungan dengan peningkatan gelar atau pelatihan khusus lanjutan, kredensial yang baru harus segera diverifikasi dari sumber yang mengeluarkan. Demikian pula jika ada badan luar yang melakukan investigasi tentang kejadian sentinel yang berkaitan dengan anggota tenaga medis dan mengeluarkan sanksi, informasi ini harus segera digunakan untuk mengevaluasi ulang kewenangan klinis dari anggota tenaga medis tersebut. Untuk memastikan bahwa berkas tenaga medis lengkap dan terkini, berkas ditinjau sedikitnya setiap 3 (tiga) tahun, dan terdapat catatan pada berkas tentang tindakan yang telah dilakukan atau tidak diperlukannya tindak lanjut sehingga pengangkatan tenaga medis dilanjutkan. Keanggotaan tenaga medis dapat tidak diberikan jika rumah sakit tidak memiliki peralatan medis khusus atau staf untuk mendukung praktik profesi tersebut. Sebagai contoh, ahli nefrologi yang ingin melakukan pelayanan dialisis di rumah sakit, dapat tidak diberikan kewenangan (privilege) bila rumah sakit tidak menyelenggarakan pelayanan dialisis. Akhirnya, jika izin/registrasi pelamar telah diverifikasi dengan sumber yang mengeluarkan, tetapi dokumen lain seperti edukasi dan pelatihan belum diverifikasi, staf tersebut dapat diangkat menjadi anggota tenaga medis dan kewenangan klinis dapat diberikan untuk orang tersebut untuk kurun waktu yang tidak melebihi 90 (sembilan puluh) hari. Pada kondisi di atas, orang-orang tersebut tidak boleh melakukan praktik secara mandiri dan memerlukan supervisi hingga seluruh kredensial telah diverifikasi. Supervisi secara jelas didefinisikan dalam kebijakan rumah sakit, dan berlangsung tidak lebih dari 90 (sembilan puluh) hari.', 43, 'Pengangkatan tenaga medis dibuat berdasar atas kebijakan tenaga medis dalam bentuk rumah sakit dan konsisten SPK. dengan populasi pasien rumah sakit, misi, dan pelayanan yang diberikan untuk memenuhi kebutuhan pasien.', 'Penetapan pengangkatan', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.10.1.b', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 10.1', 'Rumah sakit melaksanakan verifikasi terkini terhadap pendidikan, registrasi/izin, pengalaman, dan lainnya dalam proses kredensialing tenaga medis.', 'Penjelasan mengenai istilah dan ekspektasi yang ditemukan dalam standar-standar ini adalah sebagai berikut: a) Kredensial adalah proses evaluasi (memeriksa dokumen dari pelamar), wawancara, dan ketentuan lain sesuai dengan kebutuhan rumah sakit yang dilakukan rumah sakit terhadap seorang tenaga medis untuk menentukan apakah yang bersangkutan layak diberi penugasan klinis dan kewenangan klinis untuk menjalankan asuhan/tindakan medis tertentu di lingkungan rumah sakit tersebut untuk periode tertentu. Dokumen kredensial adalah dokumen yang dikeluarkan oleh badan resmi untuk menunjukkan bukti telah dipenuhinya persyaratan seperti ijazah dari fakultas kedokteran, surat tanda registrasi, izin praktik, fellowship, atau bukti pendidikan dan pelatihan yang telah mendapat pengakuan dari organisasi profesi kedokteran. Dokumen dokumen ini harus diverifikasi ke sumber utama yang mengeluarkan dokumen tersebut atau website verifikasi ijazah Kementerian Pendidikan, Kebudayaan, Riset dan Teknologi. b) Tenaga medis adalah semua dokter dan dokter gigi yang memberikan layanan promotif, preventif, kuratif, rehabilitatif, bedah, atau layanan medis/gigi lain kepada pasien, atau yang memberikan layanan interpretatif terkait pasien seperti patologi, radiologi, laboratorium, serta memiliki surat tanda registrasi (STR) dan surat izin praktik (SIP). c) Verifikasi adalah proses untuk memeriksa validitas dan kelengkapan kredensial dari sumber yang mengeluarkan kredensial. d) Rekredensial adalah proses kredensial ulang setiap 3 (tiga) tahun. e) Dokumen kredensial dan rekredensial meliputi: (1) STR, SIP yang masih berlaku; (2) File pelanggaran etik atau disiplin termasuk infomasi dari sumber luar seperti dari MKEK dan MKDKI; (3) Rekomendasi mampu secara fisik maupun mental memberikan asuhan kepada pasien tanpa supervisi dari profesi dokter yang ditentukan; (4) Bila tenaga medis mengalami gangguan kesehatan, kecacatan tertentu, atau proses penuaan yang menghambat pelaksanaan kerja maka kepada yang bersangkutan dilakukan penugasan klinis ulang; (5) Jika seorang anggota tenaga medis mengajukan kewenangan baru terkait pelatihan spesialisasi canggih atau subspesialisasi maka dokumen kredensial harus segera diverifikasi dari sumber yang mengeluarkan sertifikat tersebut. Keanggotaan tenaga medis mungkin tidak dapat diberikan jika rumah sakit tidak mempunyai teknologi, peralatan medis khusus untuk mendukung kewenangan klinis tertentu. Sebagai contoh, seorang nefrolog melamar untuk memberikan layanan dialisis di rumah sakit bila rumah sakit tidak memiliki pelayanan ini maka kewenangan klinis untuk melakukan haemodialisis tidak dapat diberikan. Pengecualian untuk KPS 10.1 EP 1, hanya untuk survei awal. Pada saat survei akreditasi awal rumah sakit diwajibkan telah menyelesaikan verifikasi untuk tenaga medis baru yang bergabung dalam 12 (dua belas) bulan menjelang survei awal. Selama 12 (dua belas) bulan setelah survei awal, rumah sakit diwajibkan untuk menyelesaikan verifikasi sumber primer untuk seluruh anggota tenaga medis lainnya. Proses ini dicapai dalam kurun waktu 12 (dua belas) bulan setelah survei sesuai dengan rencana yang memprioritaskan verifikasi kredensial bagi tenaga medis aktif yang memberikan pelayanan berisiko tinggi. Catatan: Pengecualian ini hanya untuk verifikasi kredensial saja. Semua kredensial anggota tenaga medis harus dikumpulkan dan ditinjau, dan kewenangan mereka diberikan. f) Pengangkatan/penugasan merupakan proses peninjauan kredensial awal pelamar untuk memutuskan apakah orang tersebut memenuhi syarat untuk memberikan pelayanan yang dibutuhkan pasien rumah sakit dan dapat didukung rumah sakit dengan staf yang kompeten dan dengan kemampuan teknis rumah sakit. Untuk pelamar pertama, informasi yang ditinjau kebanyakan berasal dari sumber luar. Individu atau mekanisme yang berperan pada peninjauan, kriteria yang digunakan untuk membuat keputusan, dan bagaimana keputusan didokumentasikan diidentifikasi dalam kebijakan rumah sakit. Kebijakan rumah sakit mengidentifikasi proses pengangkatan praktisi kesehatan mandiri untuk keperluan gawat darurat atau untuk sementara waktu. Pengangkatan dan identifikasi kewenangan untuk praktisi kesehatan tersebut tidak dibuat sampai setidaknya verifikasi izin telah dilakukan. g) Pengangkatan/penugasan kembali merupakan proses peninjauan dokumen anggota tenaga medis untuk verifikasi: (1) Perpanjangan izin; (2) Bahwa anggota tenaga medis tidak dikenai sanksi disipliner oleh badan perizinan dan sertifikasi; (3) Bahwa berkas berisi dokumentasi yang cukup untuk pencarian kewenangan atau tugas baru/perluasan di rumah sakit; dan (4) Anggota tenaga medis mampu secara fisik dan mental untuk memberikan perawatan dan tata laksana terhadap pasien tanpa supervisi. Informasi untuk peninjauan ini berasal dari sumber internal maupun eksternal. Jika suatu departemen/unit layanan klinis (misalnya, pelayanan subspesialis) tidak memiliki kepala/pimpinan, rumah sakit mempunyai kebijakan untuk mengidentifikasi siapa yang melakukan peninjauan untuk para tenaga profesional di departemen/unit layanan tersebut. Berkas kredensial anggota tenaga medis harus merupakan sumber informasi yang dinamis dan ditinjau secara konstan. Sebagai contoh, ketika anggota tenaga medis mendapatkan sertifikat pencapaian yang berhubungan dengan peningkatan gelar atau pelatihan khusus lanjutan, kredensial yang baru harus segera diverifikasi dari sumber yang mengeluarkan. Demikian pula jika ada badan luar yang melakukan investigasi tentang kejadian sentinel yang berkaitan dengan anggota tenaga medis dan mengeluarkan sanksi, informasi ini harus segera digunakan untuk mengevaluasi ulang kewenangan klinis dari anggota tenaga medis tersebut. Untuk memastikan bahwa berkas tenaga medis lengkap dan terkini, berkas ditinjau sedikitnya setiap 3 (tiga) tahun, dan terdapat catatan pada berkas tentang tindakan yang telah dilakukan atau tidak diperlukannya tindak lanjut sehingga pengangkatan tenaga medis dilanjutkan. Keanggotaan tenaga medis dapat tidak diberikan jika rumah sakit tidak memiliki peralatan medis khusus atau staf untuk mendukung praktik profesi tersebut. Sebagai contoh, ahli nefrologi yang ingin melakukan pelayanan dialisis di rumah sakit, dapat tidak diberikan kewenangan (privilege) bila rumah sakit tidak menyelenggarakan pelayanan dialisis. Akhirnya, jika izin/registrasi pelamar telah diverifikasi dengan sumber yang mengeluarkan, tetapi dokumen lain seperti edukasi dan pelatihan belum diverifikasi, staf tersebut dapat diangkat menjadi anggota tenaga medis dan kewenangan klinis dapat diberikan untuk orang tersebut untuk kurun waktu yang tidak melebihi 90 (sembilan puluh) hari. Pada kondisi di atas, orang-orang tersebut tidak boleh melakukan praktik secara mandiri dan memerlukan supervisi hingga seluruh kredensial telah diverifikasi. Supervisi secara jelas didefinisikan dalam kebijakan rumah sakit, dan berlangsung tidak lebih dari 90 (sembilan puluh) hari.', 44, 'Pengangkatan tidak dilakukan sampai setidaknya izin/surat a) Verifikasi STR dan SIP. tanda registrasi sudah b) SPK dan RKK tenaga diverifikasi dari sumber utama medis dengan TDD yang mengeluarkan surat kewenangan dibawah tersebut dan tenaga medis supervisi maksimal 90 dapat memberikan pelayanan hari. kepada pasien di bawah supervisi sampai semua kredensial yang disyaratkan undang-undang dan peraturan sudah diverifikasi dari sumbernya.', 'Bukti:', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
