INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.14.d', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 14', 'Rumah sakit mempunyai proses yang efektif untuk melakukan kredensial tenaga perawat dengan mengumpulkan, verifikasi pendidikan, registrasi, izin, kewenangan, pelatihan, dan pengalamannya.', 'Rumah sakit perlu memastikan untuk mempunyai tenaga perawat yang kompeten sesuai dengan misi, sumber daya, dan kebutuhan pasien. Tenaga perawat bertanggung jawab untuk memberikan asuhan keperawatan pasien secara langsung. Sebagai tambahan, asuhan keperawatan memberikan kontribusi terhadap outcome pasien secara keseluruhan. Rumah sakit harus memastikan bahwa perawat yang kompeten untuk memberikan asuhan keperawatan dan harus spesifik terhadap jenis asuhan keperawatan sesuai dengan peraturan perundang-undangan. Rumah sakit memastikan bahwa setiap perawat yang kompeten untuk memberikan asuhan keperawatan, baik mandiri, kolaborasi, delegasi, serta mandat kepada pasien secara aman dan efektif dengan cara: a) Memahami peraturan dan perundang-undangan terkait perawat dan praktik keperawatan; b) Melakukan kredensial terhadap semua bukti pendidikan, pelatihan, pengalaman, informasi yang ada pada setiap perawat, sekurang-kurangnya meliputi: (1) Bukti pendidikan, registrasi, izin, kewenangan, pelatihan, serta pengalaman terbaru dan diverifikasi dari sumber aslinya; (2) Bukti kompetensi terbaru melalui informasi dari sumber lain di tempat perawat pernah bekerja sebelumnya; dan (3) Surat rekomendasi dan/atau informasi lain yang mungkin diperlukan rumah sakit, antara lain riwayat kesehatan dan sebagainya. c) Rumah sakit perlu melakukan setiap upaya untuk memverifikasi informasi penting dari berbagai sumber utama dengan jalan mengecek ke website resmi institusi pendidikan pelatihan melalui email dan surat tercatat. Pemenuhan standar mensyaratkan verifikasi sumber utama dilaksanakan untuk perawat yang akan dan sedang bekerja. Bila verifikasi tidak mungkin dilakukan seperti hilang karena bencana atau sekolahnya tutup maka hal ini didapatkan dari sumber resmi lain.', 66, 'Terdapat bukti dokumen kredensial yang dipelihara file kepegawaian setiap tenaga pada setiap tenaga perawat. keperawatan.', 'Bukti berkas kredensial ada pada', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
