INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.17.a', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 17', 'Rumah sakit mempunyai proses yang efektif untuk melakukan kredensial tenaga kesehatan lain dengan mengumpulkan dan melakukan verifikasi pendidikan, registrasi, izin, kewenangan, pelatihan, dan pengalamannya.', 'Rumah sakit perlu memastikan bahwa tenaga kesehatan lainnya kompeten sesuai dengan misi, sumber daya, dan kebutuhan pasien. Profesional Pemberi Asuhan (PPA) yang bertanggungjawab memberikan asuhan pasien secara langsung termasuk bidan, nutrisionis, apoteker, fisioterapis, teknisi transfusi darah, penata anestesi, dan lainnya. sedangkan staf klinis adalah adalah staf yang menempuh pendidikan profesi maupun vokasi yang tidak memberikan pelayanan secara langsung kepada pasien. Rumah sakit memastikan bahwa PPA dan staf klinis lainnya berkompeten dalam memberikan asuhan aman dan efektif kepada pasien sesuai dengan peraturan perundang- undangan dengan: (a) Memahami peraturan dan perundang-undangan terkait tenaga kesehatan lainnya. (b) Mengumpulkan semua kredensial yang ada untuk setiap profesional pemberi asuhan (PPA) lainnya dan staf klinis lainnya sekurang-kurangnya meliputi: (1) Bukti pendidikan, registrasi, izin, kewenangan, pelatihan, dan pengalaman terbaru serta diverifikasi dari sumber asli/website verifikasi ijazah Kementerian Pendidikan, Kebudayaan, Riset dan Teknologi; (2) Bukti kompetensi terbaru melalui informasi dari sumber lain di tempat tenaga kesehatan lainnya pernah bekerja sebelumnya; dan (3) Surat rekomendasi dan/atau informasi lain yang mungkin diperlukan rumah sakit, antara lain riwayat kesehatan dan sebagainya. (c) Melakukan setiap upaya memverifikasi informasi penting dari berbagai sumber dengan jalan mengecek ke website resmi dari institusi pendidikan pelatihan melalui email dan surat tercatat. Pemenuhan standar mensyaratkan verifikasi sumber aslinya dilaksanakan untuk tenaga kesehatan lainnya yang akan dan sedang bekerja. Bila verifikasi tidak mungkin dilakukan seperti hilangnya dokumen karena bencana atau sekolahnya tutup maka hal ini dapat diperoleh dari sumber resmi lain. File kredensial setiap tenaga kesehatan lainnya harus tersedia dan dipelihara serta diperbaharui secara berkala sesuai dengan ketentuan peraturan perundang- undangan.', 74, 'Rumah sakit telah menetapkan dan menerapkan proses yang efektif terhadap tenaga kredensial yang efektif terhadap kesehatan lainnya meliputi a) – tenaga Kesehatan lainnya c) dalam maksud dan tujuan. meliputi poin a) – c) dalam maksud dan tujuan. kredensial tenaga kesehatan lainnya sesuai regulasi.', 'Penetapan proses kredensial Bukti penerapan proses', 'D,R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
