INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.18.a', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 18', 'Rumah sakit melakukan identifikasi tanggung jawab pekerjaan dan memberikan penugasan klinis berdasar atas hasil kredensial tenaga kesehatan lainnya sesuai dengan peraturan perundang-undangan.', 'Rumah sakit mempekerjakan atau dapat mengizinkan tenaga kesehatan lainnya untuk memberikan asuhan dan pelayanan kepada pasien atau berpartisipasi dalam proses asuhan pasien. Bila Tenaga kesehatan lainnya tersebut yang diizinkan bekerja atau berpraktik di rumah sakit maka rumah sakit bertanggungjawab untuk melakukan proses kredensialing.', 78, 'Rumah sakit telah menetapkan rincian dan staf klinis lainnya kewenangan klinis profesional berdasarkan atas hasil pemberi asuhan (PPA) lainnya kredensial. dan staf klinis lainnya berdasar atas hasil kredensial tenaga Kesehatan lainnya.', 'Penetapan RKK PPA lainnya', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.18.b', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 18', 'Rumah sakit melakukan identifikasi tanggung jawab pekerjaan dan memberikan penugasan klinis berdasar atas hasil kredensial tenaga kesehatan lainnya sesuai dengan peraturan perundang-undangan.', 'Rumah sakit mempekerjakan atau dapat mengizinkan tenaga kesehatan lainnya untuk memberikan asuhan dan pelayanan kepada pasien atau berpartisipasi dalam proses asuhan pasien. Bila Tenaga kesehatan lainnya tersebut yang diizinkan bekerja atau berpraktik di rumah sakit maka rumah sakit bertanggungjawab untuk melakukan proses kredensialing.', 79, 'Rumah sakit telah menetapkan surat penugasan kesehatan lainnya sesuai klinis kepada tenaga dengan peraturan perundang- Kesehatan lainnya sesuai undangan. dengan peraturan perundang- undangan.', 'Penetapan SPK tenaga', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.19.a', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 19', 'Rumah sakit telah melakukan penilaian kinerja tenaga Kesehatan lainnya termasuk perannya dalam kegiatan peningkatan mutu dan keselamatan pasien serta program manajemen risiko rumah sakit.', 'Peran klinis tenaga Kesehatan lainnya sangat penting dalam pelayanan pasien sehingga mengharuskan mereka berperan secara proaktif dalam program peningkatan mutu dan keselamatan pasien serta program manajemen risiko rumah sakit. Rumah sakit melakukan penilaian kinerja tenaga Kesehatan lainnya secara periodik menggunakan format dan metode sesuai ketentuan yang ditetapkan rumah sakit. Bila ada temuan dalam kegiatan peningkatan mutu, laporan insiden keselamatan pasien atau manajemen risiko maka Pimpinan rumah sakit dan kepala unit akan mempertimbangkan secara adil (just culture) dengan melihat laporan mutu atau hasil root cause analysis (RCA) sejauh mana peran tenaga Kesehatan lainnya yang terkait kejadian tersebut. Hasil kajian, tindakan yang diambil, dan setiap dampak atas tanggung jawab pekerjaan didokumentasikan dalam file kredensial tenaga Kesehatan lainnya tersebut atau file lainnya.', 80, 'Rumah sakit telah melakukan penilaian kinerja tenaga tenaga kesehatan lainnya. Kesehatan lainnya secara periodik menggunakan format kesehatan lainnya secara dan metode sesuai ketentuan periodik. yang ditetapkan rumah sakit.', 'Penetapan penilaian kinerja Bukti penilaian kinerja tenaga', 'D,R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.19.b', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 19', 'Rumah sakit telah melakukan penilaian kinerja tenaga Kesehatan lainnya termasuk perannya dalam kegiatan peningkatan mutu dan keselamatan pasien serta program manajemen risiko rumah sakit.', 'Peran klinis tenaga Kesehatan lainnya sangat penting dalam pelayanan pasien sehingga mengharuskan mereka berperan secara proaktif dalam program peningkatan mutu dan keselamatan pasien serta program manajemen risiko rumah sakit. Rumah sakit melakukan penilaian kinerja tenaga Kesehatan lainnya secara periodik menggunakan format dan metode sesuai ketentuan yang ditetapkan rumah sakit. Bila ada temuan dalam kegiatan peningkatan mutu, laporan insiden keselamatan pasien atau manajemen risiko maka Pimpinan rumah sakit dan kepala unit akan mempertimbangkan secara adil (just culture) dengan melihat laporan mutu atau hasil root cause analysis (RCA) sejauh mana peran tenaga Kesehatan lainnya yang terkait kejadian tersebut. Hasil kajian, tindakan yang diambil, dan setiap dampak atas tanggung jawab pekerjaan didokumentasikan dalam file kredensial tenaga Kesehatan lainnya tersebut atau file lainnya.', 81, 'Penilain kinerja tenaga Kesehatan lainnya meliputi pemenuhan kesehatan lainnya berupa: uraian tugasnya dan perannya a) Pemenuhan uraian dalam pencapaian target tugasnya. indikator mutu yang diukur di b) Perannya dalam unit tempatnya bekerja. pencapaian target indikator mutu yang diukur di unit tempatnya bekerja. (lihat TKRS dan 11 c).', 'Bukti penilaian kinerja tenaga', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KPS.19.c', 'KPS', 2, 'Kualifikasi dan Pendidikan Staf', 2, 'KPS 19', 'Rumah sakit telah melakukan penilaian kinerja tenaga Kesehatan lainnya termasuk perannya dalam kegiatan peningkatan mutu dan keselamatan pasien serta program manajemen risiko rumah sakit.', 'Peran klinis tenaga Kesehatan lainnya sangat penting dalam pelayanan pasien sehingga mengharuskan mereka berperan secara proaktif dalam program peningkatan mutu dan keselamatan pasien serta program manajemen risiko rumah sakit. Rumah sakit melakukan penilaian kinerja tenaga Kesehatan lainnya secara periodik menggunakan format dan metode sesuai ketentuan yang ditetapkan rumah sakit. Bila ada temuan dalam kegiatan peningkatan mutu, laporan insiden keselamatan pasien atau manajemen risiko maka Pimpinan rumah sakit dan kepala unit akan mempertimbangkan secara adil (just culture) dengan melihat laporan mutu atau hasil root cause analysis (RCA) sejauh mana peran tenaga Kesehatan lainnya yang terkait kejadian tersebut. Hasil kajian, tindakan yang diambil, dan setiap dampak atas tanggung jawab pekerjaan didokumentasikan dalam file kredensial tenaga Kesehatan lainnya tersebut atau file lainnya.', 82, 'Pimpinan rumah sakit dan kepala unit telah berlaku adil (just keselamatan pasien yang culture) ketika ada temuan dalam dilakukan tenaga kegiatan peningkatan mutu, kesehatan lainnya. TDD laporan insiden keselamatan 2. Bukti proses tindak lanjut pasien atau manajemen risiko. secara adil (just culture) ketika ada laporan tersebut.', '1. Bukti laporan insiden', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tu