INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('MFK.8.1.e', 'MFK', 3, 'Manajemen Fasilitas dan Keselamatan', 2, 'MFK 8.1', 'Dilakukan pemeriksaan, pemeliharaan, dan perbaikan sistem utilitas.', 'Rumah sakit harus mempunyai daftar inventaris lengkap sistem utilitas dan menentukan komponen yang berdampak pada bantuan hidup, pengendalian infeksi, pendukung lingkungan, dan komunikasi. Proses menajemen utilitas menetapkan pemeliharaan utilitas untuk memastikan utilitas pokok/penting seperti air, listrik, sampah, ventilasi, gas medik, lift agar dijaga, diperiksa berkala, dipelihara, dan diperbaiki.', 45, 'Sistem utilitas dan komponen kritikalnya diperbaiki bila dan komponen kritikalnya bila diperlukan. diperlukan. utilitas.', 'Bukti perbaikan sistem utilitas Staf Penanggung Jawab sistem', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('MFK.8.2.a', 'MFK', 3, 'Manajemen Fasilitas dan Keselamatan', 2, 'MFK 8.2', 'Sistem utilitas rumah sakit menjamin tersedianya air bersih dan listrik sepanjang waktu serta menyediakan sumber cadangan/alternatif persediaan air dan tenaga listrik jika terjadi terputusnya sistem, kontaminasi, atau kegagalan.', 'Pelayanan pasien dilakukan selama 24 jam terus menerus, setiap hari dalam seminggu di rumah sakit. Rumah sakit harus melindungi pasien dan staf dalam keadaan darurat seperti jika terjadi kegagalan sistem, pemutusan, dan kontaminasi. Sistem tenaga listrik darurat dibutuhkan oleh semua rumah sakit yang ingin memberikan asuhan kepada pasien tanpa putus dalam keadaan darurat. Sistem darurat ini memberikan cukup tenaga listrik untuk mempertahankan fungsi yang esensial dalam keadaan darurat dan juga menurunkan risiko terkait terjadi kegagalan. Tenaga listrik cadangan dan darurat harus dites sesuai dengan rencana yang dapat membuktikan beban tenaga listrik memang seperti yang dibutuhkan. Perbaikan dilakukan jika dibutuhkan seperti menambah kapasitas listrik di area dengan peralatan baru. Mutu air dapat berubah mendadak karena banyak sebab, tetapi sebagian besar karena terjadi di luar rumah sakit seperti ada kebocoran di jalur suplai ke rumah sakit. Jika terjadi suplai air ke rumah sakit terputus maka persediaan air bersih darurat harus tersedia segera. Untuk mempersiapkan diri terhadap keadaan darurat seperti ini, rumah sakit agar mempunyai proses meliputi: a) Mengidentifikasi peralatan, sistem, serta area yang memiliki risiko paling tinggi terhadap pasien dan staf (sebagai contoh, rumah sakit mengidentifikasi area yang membutuhkan penerangan, pendinginan (lemari es), bantuan hidup/ventilator, serta air bersih untuk membersihkan dan sterilisasi alat); b) Menyediakan air bersih dan listrik 24 jam setiap hari dan 7 (tujuh) hari seminggu; c) Menguji ketersediaan serta kehandalan sumber tenaga listrik dan air bersih darurat/pengganti/back-up; d) Mendokumentasikan hasil-hasil pengujian; e) Memastikan bahwa pengujian sumber cadangan/alternatif air bersih dan listrik dilakukan setidaknya setiap 6 (enam) bulan atau lebih sering jika dipersyaratkan oleh peraturan perundang-undangan di daerah, rekomendasi produsen, atau kondisi sumber listrik dan air. Kondisi sumber listrik dan air yang mungkin dapat meningkatkan frekuensi pengujian mencakup: (1) Perbaikan sistem air bersih yang terjadi berulang- ulang. (2) Sumber air bersih sering terkontaminasi. (3) Jaringan listrik yang tidak dapat diandalkan. (4) Pemadaman listrik yang tidak terduga dan berulang- ulang. Rumah sakit melakukan pengkajian risiko dan meminimalisasi risiko kegagalan sistem utilitas di area-area berisiko terutama area pelayanan pasien. Rumah sakit merencanakan tenaga listrik cadangan darurat (dengan menyiapkan genset) dan penyediaan sumber air bersih darurat untuk area-area yang membutuhkan. Untuk memastikan kapasitas beban yang dapat dicapai oleh unit genset apakah benar-benar mampu mencapai beban tertinggi maka pada waktu pembelian unit genset, dilakukan test loading dengan menggunakan alat yang bernama dummy load. Selain itu, rumah sakit melaksanakan uji coba sumber listrik cadangan/alternatif sekurangnya 6 (enam) bulan sekali atau lebih sering bila diharuskan oleh peraturan perundang- undangan atau oleh kondisi sumber listrik. Jika sistem listrik darurat membutuhkan sumber bahan bakar maka jumlah tempat penyimpanan bahan bakar perlu dipertimbangkan. Rumah sakit dapat menentukan jumlah bahan bakar yang disimpan, kecuali ada ketentuan lain dari pihak berwenang.', 46, 'Rumah Sakit mempunyai proses sistem utilitas terhadap terhadap keadaan darurat yang keadaan darurat yang meliputi meliputi a) e) dalam maksud poin a)-e) pada maksud dan dan tujuan. tujuan.', 'Penetapan proses sistem utilitas', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
