INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PMKP.2.a', 'PMKP', 4, 'Peningkatan Mutu dan Keselamatan Pasien', 2, 'PMKP 2', 'Komite/Tim mutu mendukung proses pemilihan indikator dan melaksanakan koordinasi serta integrasi kegiatan pengukuran data indikator mutu dan keselamatan pasien di rumah sakit.', 'Pemilihan indikator mutu prioritas rumah sakit adalah tanggung jawab pimpinan dengan mempertimbangkan prioritas untuk pengukuran yang berdampak luas/menyeluruh di rumah sakit. Sedangkan kepala unit memilih indikator mutu prioritas di unit kerjanya. Semua unit klinis dan non klinis memilih indikator terkait dengan prioritasnya. Di rumah sakit yang besar harus diantisipasi jika ada indikator yang sama yang diukur di lebih dari satu unit. Misalnya, Unit farmasi dan Komite PPI memilih prioritas pengukurannya adalah penurunan angka penggunaan antibiotik di rumah sakit. Program mutu dan keselamatan pasien berperan penting dalam membantu unit melakukan pengukuran indikator yang ditetapkan. Komite/Tim mutu juga bertugas untuk mengintegrasikan semua kegiatan pengukuran di rumah sakit, termasuk pengukuran budaya keselamatan dan sistem pelaporan insiden keselamatan pasien. Integrasi semua pengukuran ini akan menghasilkan solusi dan perbaikan yang terintegrasi. 3) Elemen penilaian PMKP 2', 5, 'Komite/Tim Penyelenggara Mutu terlibat dalam pemilihan indikator mutu prioritas baik indikator mutu prioritas baik ditingkat rumah sakit maupun ditingkat rumah sakit maupun tingkat unit layanan. tingkat unit layanan Pimpinan RS Kepala unit kerja', 'Bukti rapat tentang pemilihan Komite / Tim Mutu', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
