INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PMKP.2.c', 'PMKP', 4, 'Peningkatan Mutu dan Keselamatan Pasien', 2, 'PMKP 2', 'Komite/Tim mutu mendukung proses pemilihan indikator dan melaksanakan koordinasi serta integrasi kegiatan pengukuran data indikator mutu dan keselamatan pasien di rumah sakit.', 'Pemilihan indikator mutu prioritas rumah sakit adalah tanggung jawab pimpinan dengan mempertimbangkan prioritas untuk pengukuran yang berdampak luas/menyeluruh di rumah sakit. Sedangkan kepala unit memilih indikator mutu prioritas di unit kerjanya. Semua unit klinis dan non klinis memilih indikator terkait dengan prioritasnya. Di rumah sakit yang besar harus diantisipasi jika ada indikator yang sama yang diukur di lebih dari satu unit. Misalnya, Unit farmasi dan Komite PPI memilih prioritas pengukurannya adalah penurunan angka penggunaan antibiotik di rumah sakit. Program mutu dan keselamatan pasien berperan penting dalam membantu unit melakukan pengukuran indikator yang ditetapkan. Komite/Tim mutu juga bertugas untuk mengintegrasikan semua kegiatan pengukuran di rumah sakit, termasuk pengukuran budaya keselamatan dan sistem pelaporan insiden keselamatan pasien. Integrasi semua pengukuran ini akan menghasilkan solusi dan perbaikan yang terintegrasi. 3) Elemen penilaian PMKP 2', 7, 'Komite/Tim Penyelenggara Mutu mengintegrasikan insiden keselamatan laporan insiden keselamatan pasien, pengukuran pasien, pengukuran budaya budaya keselamatan, dan keselamatan, dan lainnya lainnya untuk mendapatkan solusi dan 2. Bukti solusi dan perbaikan terintegrasi perbaikan terintegrasi Pimpinan RS Kepala unit kerja', '1. Bukti integrasi laporan Komite / Tim Mutu', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PMKP.3.a', 'PMKP', 4, 'Peningkatan Mutu dan Keselamatan Pasien', 2, 'PMKP 3', 'Pengumpulan data indikator mutu dilakukan oleh staf pengumpul data yang sudah mendapatkan pelatihan tentang pengukuran data indikator mutu.', 'Pengumpulan data indikator mutu berdasarkan peraturan yang berlaku yaitu pengukuran Indikator nasional mutu (INM) dan prioritas perbaikan tingkat rumah sakit meliputi: a) Indikator nasional mutu (INM) yaitu indikator mutu nasional yang wajib dilakukan pengukuran dan digunakan sebagai informasi mutu secara nasional. b) Indikator mutu prioritas rumah sakit (IMP-RS) (TKRS 5) mencakup: (1) Indikator Sasaran Keselamatan pasien minimal 1 indikator setiap sasaran. (2) Indikator pelayanan klinis prioritas, untuk rumah sakit umum diambil dari 10 penyakit prioritas (tergantung penyelenggaraan pelayanan rumah sakit tersebut) dan untuk rumah sakit khusus disesuaikan dengan pelayanan kekhususannya, minimal 1 indikator. (3) Indikator sesuai tujuan strategis rumah sakit (KPI) minimal 1 indikator. (4) Indikator terkait perbaikan sistem minimal 1 indikator. (5) Indikator terkait manajemen risiko minimal 1 indikator. (6) Indikator terkait Penelitian klinis dan program pendidikan kedokteran minimal 1 indikator (apabila ada) c) Indikator mutu prioritas unit (IMP-Unit) adalah indikator prioritas yang khusus dipilih kepala unit terdiri dari minimal 1 indikator. Indikator mutu terpilih apabila sudah tercapai dan dapat dipertahankan selama 1 (satu) tahun, maka dapat diganti dengan indikator mutu yang baru. Setiap indikator mutu baik indikator mutu prioritas rumah sakit (IMPRS) maupun indikator mutu prioritas unit (IMP-Unit) agar dilengkapi dengan profil indikator sebagai berikut: a) Judul Indikator. b) Dasar pemikiran. c) Dimensi Mutu. d) Tujuan. e) Definisi Operasional. f) Jenis Indikator. g) Satuan pengukuran. h) Numerator (Pembilang). i) Denominator (Penyebut). j) Target Pencapaian. k) Kriteria inklusi dan eksklusi. l) Formula. m) Metode pengumpulan data. n) Sumber data. o) Instrumen pengambilan data. p) Populasi / Sampel (Besar sampel dan cara pengambilan sampel). q) Periode pengumpulan data. r) Periode analisis dan pelaporan data. s) Penyajian data. t) Penanggung jawab. 6) Elemen penilaian PMKP 3', 8, 'Rumah sakit melakukan pengumpulan data mencakup indikator nasional mutu, (poin a-c) dalam maksud dan indikator mutu prioritas RS, tujuan. indikator mutu prioritas unit. Kepala unit kerja Penanggung jawab data unit', 'Bukti pengumpulan data Komite / Tim Mutu', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
