INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PMKP.4.1.a', 'PMKP', 4, 'Peningkatan Mutu dan Keselamatan Pasien', 2, 'PMKP 4.1', 'Staf dengan pengalaman, pengetahuan, dan keterampilan yang bertugas mengumpulkan dan menganalisis data rumah sakit secara sistematis.', 'Analisis data melibatkan staf yang memahami manajemen informasi, mempunyai keterampilan dalam metode-metode pengumpulan data, dan memahami teknik statistik. Hasil analisis data harus dilaporkan kepada Penanggung jawab indikator mutu (PIC) yang bertanggung jawab untuk menindaklanjuti hasil tersebut. Penanggung jawab tersebut bisa memiliki latar belakang klinis, non klinis, atau kombinasi keduanya. Hasil analisis data akan memberikan masukan untuk pengambilan keputusan dan memperbaiki proses klinis dan non klinis secara berkelanjutan. Run charts, diagram kontrol (control charts), histogram, dan diagram Pareto merupakan contoh dari alat-alat statistik yang sangat berguna dalam memahami tren dan variasi dalam pelayanan kesehatan. Tujuan analisis data adalah untuk dapat membandingkan rumah sakit dengan empat cara. Perbandingan tersebut membantu rumah sakit dalam memahami sumber dan penyebab perubahan yang tidak diinginkan dan membantu memfokuskan upaya perbaikan. a) Dengan rumah sakit sendiri dari waktu ke waktu, misalnya dari bulan ke bulan, dari tahun ke tahun. b) Dengan rumah sakit setara, seperti melalui database referensi. c) Dengan standar-standar, seperti yang ditentukan oleh badan akreditasi atau organisasi profesional ataupun standar-standar yang ditentukan oleh peraturan perundang-undangan yang berlaku. d) Dengan praktik-praktik terbaik yang diakui dan menggolongkan praktik tersebut sebagai best practice(praktik terbaik) atau better practice (praktik yang lebih baik) atau practice guidelines (pedoman praktik). 6) Elemen penilaian PMKP 4.1', 17, 'Data dikumpulkan, dianalisis, dan diubah menjadi informasi dianalisis dan diubah menjadi untuk mengidentifikasi peluang- informasi untuk mengidentifikasi peluang untuk perbaikan peluang-peluang untuk perbaikan (Lihat juga PMKP 4 EP a dan EP b) Kepala unit kerja Penanggung jawab data unit', 'Bukti pengumpulan data, Komite / Tim Mutu', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PMKP.4.1.b', 'PMKP', 4, 'Peningkatan Mutu dan Keselamatan Pasien', 2, 'PMKP 4.1', 'Staf dengan pengalaman, pengetahuan, dan keterampilan yang bertugas mengumpulkan dan menganalisis data rumah sakit secara sistematis.', 'Analisis data melibatkan staf yang memahami manajemen informasi, mempunyai keterampilan dalam metode-metode pengumpulan data, dan memahami teknik statistik. Hasil analisis data harus dilaporkan kepada Penanggung jawab indikator mutu (PIC) yang bertanggung jawab untuk menindaklanjuti hasil tersebut. Penanggung jawab tersebut bisa memiliki latar belakang klinis, non klinis, atau kombinasi keduanya. Hasil analisis data akan memberikan masukan untuk pengambilan keputusan dan memperbaiki proses klinis dan non klinis secara berkelanjutan. Run charts, diagram kontrol (control charts), histogram, dan diagram Pareto merupakan contoh dari alat-alat statistik yang sangat berguna dalam memahami tren dan variasi dalam pelayanan kesehatan. Tujuan analisis data adalah untuk dapat membandingkan rumah sakit dengan empat cara. Perbandingan tersebut membantu rumah sakit dalam memahami sumber dan penyebab perubahan yang tidak diinginkan dan membantu memfokuskan upaya perbaikan. a) Dengan rumah sakit sendiri dari waktu ke waktu, misalnya dari bulan ke bulan, dari tahun ke tahun. b) Dengan rumah sakit setara, seperti melalui database referensi. c) Dengan standar-standar, seperti yang ditentukan oleh badan akreditasi atau organisasi profesional ataupun standar-standar yang ditentukan oleh peraturan perundang-undangan yang berlaku. d) Dengan praktik-praktik terbaik yang diakui dan menggolongkan praktik tersebut sebagai best practice(praktik terbaik) atau better practice (praktik yang lebih baik) atau practice guidelines (pedoman praktik). 6) Elemen penilaian PMKP 4.1', 18, 'Staf yang kompeten melakukan proses pengukuran bagi staf yang melakukan menggunakan alat dan teknik proses pengukuran statistik Kepala unit kerja Penanggung jawab data unit Pengumpul data Validator', 'Bukti sertifikat pelatihan PMKP Komite/Tim Mutu', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
