INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PMKP.6.d', 'PMKP', 4, 'Peningkatan Mutu dan Keselamatan Pasien', 2, 'PMKP 6', 'Rumah sakit mencapai perbaikan mutu dan dipertahankan', 'Hasil analisa data digunakan untuk mengidentifkasi potensi perbaikan atau untuk mengurangi atau mencegah kejadian yang merugikan. Khususnya, perbaikan yang direncanakan untuk prioritas perbaikan tingkat rumah sakit yang sudah ditetapkan Direktur rumah sakit. Rencana perbaikan perlu dilakukan uji coba dan selama masa uji dan dilakukan evaluasi hasilnya untuk membuktikan bahwa perbaikan sudah sesuai dengan yang diharapkan. Proses uji perbaikan ini dapat menggunakan metode-metode perbaikan yang sudah teruji misalnya PDCA Plan-Do-Chek-Action (PDCA) atau Plan-Do-Study- Action (PDSA) atau metode lain. Hal ini untuk memastikan bahwa terdapat perbaikan berkelanjutan untuk meningkatkan mutu dan keselamatan pasien. Perubahan yang efektif teesebut di standarisasi dengan membuat regulasi di rumah sakit misalnya kebijakan, SPO, dan lain-lainnya, dan harus di sosialisasikan kepada semua staf. Perbaikan-perbaikan yang dicapai dan dipertahankan oleh rumah sakit didokumentasikan sebagai bagian dari pengelolaan peningkatan mutu dan keselamatan pasien di rumah sakit. 3) Elemen penilaian PMKP 6', 25, 'Keberhasilan telah didokumentasikan dan dalam laporan Triwulan. dijadikan laporan PMKP. Pimpinan RS Kepala unit kerja', 'Bukti keberhasilan tercantum Komite / Tim Mutu', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PMKP.7.a', 'PMKP', 4, 'Peningkatan Mutu dan Keselamatan Pasien', 2, 'PMKP 7', 'Dilakukan evaluasi proses pelaksanaan standar pelayanan kedokteran di rumah sakit untuk menunjang pengukuran mutu pelayanan klinis prioritas', 'Penerapan standar pelayanan kedokteran di rumah sakit berdasarkan panduan praktik klinis (PPK) dievaluasi menggunakan alur klinik/clinical pathway (CP). Terkait dengan pengukuran prioritas perbaikan pelayanan klinis yang ditetapkan Direktur, maka Direktur bersama-sama dengan pimpinan medis, ketua Komite medik dan Kelompok staf medis terkait menetapkan paling sedikit 5 (lima) evaluasi pelayanan prioritas standar pelayanan kedokteran. Evaluasi pelayanan prioritas standard pelayanan kedokteran dilakukan sampai terjadi pengurangan variasi dari data awal ke target yang ditentukan ketentuan rumah sakit. Tujuan pemantauan pelaksanaan evaluasi perbaikan pelayanan klinis berupa standar pelayanan kedokteran sebagai berikut: a) Mendorong tercapainya standardisasi proses asuhan klinik. b) Mengurangi risiko dalam proses asuhan, terutama yang berkaitan asuhan kritis. c) Memanfaatkan sumber daya yang tersedia dengan efisien dalam memberikan asuhan klinik tepat waktu dan efektif. d) Memanfaatkan indikator prioritas sebagai indikator dalam penilaian kepatuhan penerapan alur klinis di area yang akan diperbaiki di tingkat rumah sakit. e) Secara konsisten menggunakan praktik berbasis bukti (evidence based practices) dalam memberikan asuhan bermutu tinggi. Evaluasi prioritas standar pelayanan kedokteran tersebut dipergunakan untuk mengukur keberhasilan dan efisensi peningkatan mutu pelayanan klinis prioritas rumah sakit. Evaluasi perbaikan pelayanan klinis berupa standar pelayanan kedokteran dapat dilakukan melalui audit medis dan atau audit klinis serta dapat menggunakan indikator mutu. Tujuan evaluasi adalah untuk menilai efektivitas penerapan standar pelayanan kedokteran di rumah sakit sehingga standar pelayanan kedokteran di rumah sakit dapat mengurangi a variasi dari proses dan hasil serta berdampak terhadap efisiensi (kendali biaya). Misalnya: a) Dalam PPK disebutkan bahwa tata laksana stroke non- hemoragik harus dilakukan secara multidisiplin dan dengan pemeriksaan serta intervensi dari hari ke hari dengan urutan tertentu. Karakteristik penyakit stroke non- hemoragik sesuai untuk dibuat alur klinis (clinical pathway/CP); sehingga perlu dibuat CP untuk stroke non- hemoragik b) Dalam PPK disebutkan bahwa pada pasien gagal ginjal kronik perlu dilakukan hemodialisis. Uraian rinci tentang hemodialisis dimuat dalam protokol hemodialisis pada dokumen terpisah c) Dalam PPK disebutkan bahwa pada anak dengan kejang demam kompleks perlu dilakukan pungsi lumbal. Uraian pelaksanaan pungsi lumbal tidak dimuat dalam PPK melainkan dalam prosedur pungsi lumbal dalam dokumen terpisah d) Dalam tata laksana kejang demam diperlukan pemberian diazepam rektal dengan dosis tertentu yang harus diberikan oleh perawat bila dokter tidak ada, ini diatur dalam “Standing Order “. 6) Elemen penilaian PMKP 7', 26, 'Rumah sakit melakukan evaluasi clinical pathway sesuai yang clinical pathway (minimal tercantum dalam maksud dan clinical pathway) tujuan. Bukti clinical pathway berdasarkan pada PPK yang ditetapkan Direktur rumah sakit KSM terkait Komite/Tim Mutu', 'Bukti pelaksanaan evaluasi Komite Medik', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
