INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PMKP.8.a', 'PMKP', 4, 'Peningkatan Mutu dan Keselamatan Pasien', 2, 'PMKP 8', 'Rumah sakit mengembangkan Sistem pelaporan dan pembelajaran keselamatan pasien di rumah sakit (SP2KP-RS).', 'Sistem pelaporan dan pembelajaran keselamatan pasien di rumah sakit (SP2KP-RS) tersebut meliputi defenisi kejadian sentinel, kejadian yang tidak diharapkan (KTD), kejadian tidak cedera (KTC), dan kejadian nyaris cedera (KNC atau near-miss) dan Kondisi potensial cedera signifikan (KPCS), mekanisme pelaporan insiden keselamatan pasien baik internal maupun eksternal, grading matriks risiko serta investigasi dan analisa insiden berdasarkan hasil grading tersebut. Rumah sakit berpartisipasi untuk melaporkan insiden keselamatan pasien yang telah dilakukan investigasidan Analisa serta dilakukan pembelajaran ke KNKP sesuai peraturan perundang-undangan yang berlaku. Insiden keselamatanpasien merupakan suatu kejadianyang tidak disengaja ketika memberikan asuhan kepada pasien (care management problem/CMP) atau kondisi yang berhubungan dengan lingkungan di rumah sakit termasuk infrastruktur, sarana prasarana (service delivery problem (SDP), yang dapat berpotensi atau telah menyebabkan bahaya bagi pasien. Kejadian keselamatan pasien dapat namun tidak selalu merupakan hasil dari kecacatan pada sistem atau rancangan proses, kerusakan sistem, kegagalan alat, atau kesalahan manusia. Definisi kejadian yang tidak diharapkan (KTD), kejadian tidak cedera (KTC), kejadian nyaris cedera (KNC), dan kondisi potensial cedera signifikan (KPCS), yang didefinisikan sebagai berikut: a) Bunuh diri oleh pasien yang sedang dirawat, ditatalaksana, menerima pelayanan di unit yang selalu memiliki staf sepanjang hari atau dalam waktu 72 jam setelah pemulangan pasien, termasuk dari Unit Gawat Darurat (UGD) rumah sakit; b) Kematian bayi cukup bulan yang tidak diantisipasi; c) Bayi dipulangkan kepada orang tua yang salah; d) Penculikan pasien yang sedang menerima perawatan, tata laksana, dan pelayanan; e) Kaburnya pasien (atau pulang tanpa izin) dari unit perawatan yang selalu dijaga oleh staf sepanjang hari (termasuk UGD), yang menyebabkan kematian, cedera permanen, atau cedera sementara derajat berat bagi pasien tersebut; f) Reaksi transfusi hemolitik yang melibatkan pemberian darah atau produk darah dengan inkompatibilitas golongan darah mayor (ABO, Rh, kelompok darah lainnya); g) Pemerkosaan, kekerasan (yang menyebabkan kematian, cedera permanen, atau cedera sementara derajat berat) atau pembunuhan pasien yang sedang menerima perawatan, tata laksana, dan layanan ketika berada dalam lingkungan rumah sakit; h) Pemerkosaan, kekerasan (yang menyebabkan kematian, cedera permanen, atau cedera sementara derajat berat) atau pembunuhan anggota staf, praktisi mandiri berizin, pengunjung, atau vendor ketika berada dalam lingkungan rumah sakit i) Tindakan invasif, termasuk operasi yang dilakukan pada pasien yang salah, pada sisi yang salah, atau menggunakan prosedur yang salah (secara tidak sengaja); j) Tertinggalnya benda asing dalam tubuh pasien secara tidak sengaja setelah suatu tindakan invasif, termasuk operasi; k) Hiperbilirubinemia neonatal berat (bilirubin >30 mg/dL); l) Fluoroskopi berkepanjangan dengan dosis kumulatif >1.500 rad pada satu medan tunggal atau pemberian radioterapi ke area tubuh yang salah atau pemberian radioterapi >25% melebihi dosis radioterapi yang direncanakan; m) Kebakaran, lidah api, atau asap, uap panas, atau pijaran yang tidak diantisipasi selama satu episode perawatan pasien; n) Semua kematian ibu intrapartum (terkait dengan proses persalinan); atau o) Morbiditas ibu derajat berat (terutama tidak berhubungan dengan perjalanan alamiah penyakit pasien atau kondisi lain yang mendasari) terjadi pada pasien dan menyebabkan cedera permanen atau cedera sementara derajat berat. Definisi kejadian sentinel meliputi poin a) hingga o) di atas dan dapat meliputi kejadian-kejadian lainnya seperti yang disyaratkan dalam peraturan atau dianggap sesuai oleh rumah sakit untuk ditambahkan ke dalam daftar kejadian sentinel. Komite/ Tim Penyelenggara Mutu segera membentuk tim investigator segera setelah menerima laporan kejadian sentinel. Semua kejadian yang memenuhi definisi tersebut dianalisis akar masalahnya secara komprehensif (RCA) dengan waktu tidak melebihi 45 (empat puluh lima) hari. Tidak semua kesalahan menyebabkan kejadian sentinel, dan tidak semua kejadian sentinel terjadi akibat adanya suatu kesalahan. Mengidentifikasi suatu insiden sebagai kejadian sentinel tidak mengindikasikan adanya tanggungan hukum.', 29, 'Direktur menetapkan Sistem pelaporan dan pembelajaran Pelaporan dan Pembelajaran keselamatan pasien rumah sakit Keselamatan Pasien Rumah (SP2KP RS) termasuk didalamnya Sakit (SP2KP RS) sesuai definisi, jenis insiden peraturan perundangan keselamatan pasien meliputi kejadian sentinel (poin a–o) dalam bagian maksud dan tujuan), KTD, KNC, KTC dan KPCS, mekanisme pelaporan dan analisanya serta pembelajarannya,', 'Penetapan Pedoman Sistem', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PMKP.8.b', 'PMKP', 4, 'Peningkatan Mutu dan Keselamatan Pasien', 2, 'PMKP 8', 'Rumah sakit mengembangkan Sistem pelaporan dan pembelajaran keselamatan pasien di rumah sakit (SP2KP-RS).', 'Sistem pelaporan dan pembelajaran keselamatan pasien di rumah sakit (SP2KP-RS) tersebut meliputi defenisi kejadian sentinel, kejadian yang tidak diharapkan (KTD), kejadian tidak cedera (KTC), dan kejadian nyaris cedera (KNC atau near-miss) dan Kondisi potensial cedera signifikan (KPCS), mekanisme pelaporan insiden keselamatan pasien baik internal maupun eksternal, grading matriks risiko serta investigasi dan analisa insiden berdasarkan hasil grading tersebut. Rumah sakit berpartisipasi untuk melaporkan insiden keselamatan pasien yang telah dilakukan investigasidan Analisa serta dilakukan pembelajaran ke KNKP sesuai peraturan perundang-undangan yang berlaku. Insiden keselamatanpasien merupakan suatu kejadianyang tidak disengaja ketika memberikan asuhan kepada pasien (care management problem/CMP) atau kondisi yang berhubungan dengan lingkungan di rumah sakit termasuk infrastruktur, sarana prasarana (service delivery problem (SDP), yang dapat berpotensi atau telah menyebabkan bahaya bagi pasien. Kejadian keselamatan pasien dapat namun tidak selalu merupakan hasil dari kecacatan pada sistem atau rancangan proses, kerusakan sistem, kegagalan alat, atau kesalahan manusia. Definisi kejadian yang tidak diharapkan (KTD), kejadian tidak cedera (KTC), kejadian nyaris cedera (KNC), dan kondisi potensial cedera signifikan (KPCS), yang didefinisikan sebagai berikut: a) Bunuh diri oleh pasien yang sedang dirawat, ditatalaksana, menerima pelayanan di unit yang selalu memiliki staf sepanjang hari atau dalam waktu 72 jam setelah pemulangan pasien, termasuk dari Unit Gawat Darurat (UGD) rumah sakit; b) Kematian bayi cukup bulan yang tidak diantisipasi; c) Bayi dipulangkan kepada orang tua yang salah; d) Penculikan pasien yang sedang menerima perawatan, tata laksana, dan pelayanan; e) Kaburnya pasien (atau pulang tanpa izin) dari unit perawatan yang selalu dijaga oleh staf sepanjang hari (termasuk UGD), yang menyebabkan kematian, cedera permanen, atau cedera sementara derajat berat bagi pasien tersebut; f) Reaksi transfusi hemolitik yang melibatkan pemberian darah atau produk darah dengan inkompatibilitas golongan darah mayor (ABO, Rh, kelompok darah lainnya); g) Pemerkosaan, kekerasan (yang menyebabkan kematian, cedera permanen, atau cedera sementara derajat berat) atau pembunuhan pasien yang sedang menerima perawatan, tata laksana, dan layanan ketika berada dalam lingkungan rumah sakit; h) Pemerkosaan, kekerasan (yang menyebabkan kematian, cedera permanen, atau cedera sementara derajat berat) atau pembunuhan anggota staf, praktisi mandiri berizin, pengunjung, atau vendor ketika berada dalam lingkungan rumah sakit i) Tindakan invasif, termasuk operasi yang dilakukan pada pasien yang salah, pada sisi yang salah, atau menggunakan prosedur yang salah (secara tidak sengaja); j) Tertinggalnya benda asing dalam tubuh pasien secara tidak sengaja setelah suatu tindakan invasif, termasuk operasi; k) Hiperbilirubinemia neonatal berat (bilirubin >30 mg/dL); l) Fluoroskopi berkepanjangan dengan dosis kumulatif >1.500 rad pada satu medan tunggal atau pemberian radioterapi ke area tubuh yang salah atau pemberian radioterapi >25% melebihi dosis radioterapi yang direncanakan; m) Kebakaran, lidah api, atau asap, uap panas, atau pijaran yang tidak diantisipasi selama satu episode perawatan pasien; n) Semua kematian ibu intrapartum (terkait dengan proses persalinan); atau o) Morbiditas ibu derajat berat (terutama tidak berhubungan dengan perjalanan alamiah penyakit pasien atau kondisi lain yang mendasari) terjadi pada pasien dan menyebabkan cedera permanen atau cedera sementara derajat berat. Definisi kejadian sentinel meliputi poin a) hingga o) di atas dan dapat meliputi kejadian-kejadian lainnya seperti yang disyaratkan dalam peraturan atau dianggap sesuai oleh rumah sakit untuk ditambahkan ke dalam daftar kejadian sentinel. Komite/ Tim Penyelenggara Mutu segera membentuk tim investigator segera setelah menerima laporan kejadian sentinel. Semua kejadian yang memenuhi definisi tersebut dianalisis akar masalahnya secara komprehensif (RCA) dengan waktu tidak melebihi 45 (empat puluh lima) hari. Tidak semua kesalahan menyebabkan kejadian sentinel, dan tidak semua kejadian sentinel terjadi akibat adanya suatu kesalahan. Mengidentifikasi suatu insiden sebagai kejadian sentinel tidak mengindikasikan adanya tanggungan hukum.', 30, 'Komite/Tim Penyelenggara Mutu membentuk tim investigator tim investigator adhic yang sesegera mungkin untuk bertugas untuk melakukan melakukan investigasi investigasi TDD komprehensif/analisa akar komprehensif/analisis akar masalah (root cause analysis) masalah pada kejadian pada semua kejadian sentinel sentinel. dalam kurun waktu tidak melebihi 45 (empat puluh lima) hari.', 'Komite /Tim Mutu membentuk', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
