INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PMKP.10.a', 'PMKP', 4, 'Peningkatan Mutu dan Keselamatan Pasien', 2, 'PMKP 10', 'Rumah sakit melakukan pengukuran dan evaluasi budaya keselamatan pasien.', 'Pengukuran budaya keselamatan pasien perlu dilakukan oleh rumah sakit dengan melakukan survei budaya keselamatan pasien setiap tahun. Budaya keselamatan pasien juga dikenal sebagai budaya yang aman, yakni sebuah budaya organisasi yang mendorong setiap individu anggota staf (klinis atau administratif) melaporkan hal-hal yang menghawatirkan tentang keselamatan atau mutu pelayanan tanpa imbal jasa dari rumah sakit. Direktur rumah sakit melakukan evaluasi rutin terhadap hasil survei budaya keselamatan pasien dengan melakukan analisa dan tindak lanjutnya. 9) Elemen penilaian PMKP 10', 37, 'Rumah sakit telah melaksanakan pengukuran keselamatan pasien berupa hasil budaya keselamatan pasien survei budaya keselamatan pasien dengan survei budaya yang dilakukan setiap tahun dan keselamatan pasien setiap evaluasi secara periodik. tahun menggunakan metode Lihat TKRS 13 yang telah terbukti.', 'Bukti pengukuran budaya Komite/Tim Mutu', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
