INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PMKP.11.a', 'PMKP', 4, 'Peningkatan Mutu dan Keselamatan Pasien', 2, 'PMKP 11', 'Komite/ Tim Penyelenggara Mutu memandu penerapan program manajemen risiko di rumah sakit.', 'Komite/ Tim Penyelenggara Mutu membuat Daftar risiko tingkat rumah sakit berdasarkan daftar risiko yang dibuat tiap unit setiap tahun. Berdasarkan daftar risiko tersebut ditentukan prioritas risiko yang dimasukkan dalam profil risiko rumah sakit. Profil risiko tersebut akan menjadi bahan dalam penyusunan Program manajemen risiko rumah sakit dan menjadi prioritas untuk dilakukan penanganan dan pemantauannya. Direktur rumah sakit juga berperan dalam memilih selera risiko yaitu tingkat risiko yang bersedia diambil rumah sakit dalam upayanya mewujudkan tujuan dan sasaran yang dikehendakinya. Ada beberapa metode untuk melakukan analisis risiko secara proaktif yaitu failure mode effect analysis (analisis modus kegagalan dan dampaknya /FMEA/ AMKD), analisis kerentanan terhadap bahaya/hazard vulnerability analysis (HVA) dan infection control risk assessment (pengkajian risiko pengendalian infeksi/ICRA). Rumah sakit mengintegrasikan hasil analisa metode-metode tersebut dalam program manajemen risiko rumah sakit. Pimpinan rumah sakit akan mendesain ulang proses berisiko tinggi yang telah di analisa secara proaktif dengan melakukan tindakan untuk mengurangi risiko dalam proses tersebut. Proses analisa risiko proaktif ini dilaksanakan minimal sekali dalam setahun dan didokumentasikan pelaksanaannya. 3) Elemen penilaian PMKP 11', 39, 'Komite/Tim Penyelenggara Mutu memandu penerapan melaksanakan supervisi untuk program manajemen risiko yang memandu penerapan program di tetapkan oleh Direktur manajemen risiko. Kepala Unit kerja', 'Bukti Komite/Tim Mutu RS Komite/Tim Mutu RS', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
