INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('MRMIK.1.a', 'MRMIK', 5, 'Manajemen Rekam Medis dan Informasi Kesehatan', 2, 'MRMIK 1', 'Rumah sakit menetapkan proses manajemen informasi untuk memenuhi kebutuhan informasi internal maupun eksternal.', 'Informasi yang diperoleh selama masa perawatan pasien dalam rekam medis elektronik harus dapat dikelola dengan aman dan efektif oleh rumah sakit berdasarkan prinsip keamanan data dan informasi. Kemampuan memperoleh dan menyediakan informasi tersebut memerlukan perencanaan yang efektif. Perencanaan ini melibatkan masukan dari berbagai sumber yang membutuhkan data dan informasi, termasuk: a) Profesional Pemberi Asuhan (PPA) yang memberikan pelayanan kepada pasien b) Pimpinan rumah sakit dan para kepala departemen/unit layanan c) Staf, unit pelayanan, dan badan/individu di luar rumah sakit yang membutuhkan atau memerlukan data atau informasi tentang operasional dan proses perawatan rumah sakit. Dalam menyusun perencanaan, ditentukan prioritas kebutuhan informasi dari sumber-sumber strategi manajemen informasi rumah sakit sesuai dengan ukuran rumah sakit, kompleksitas pelayanan, ketersediaan staf terlatih, dan sumber daya manusia serta teknikal lainnya. Perencanaan yang komprehensif meliputi seluruh unit kerja dan pelayanan yang ada di rumah sakit. Rumah sakit melakukan pemantauan dan evaluasi secara berkala sesuai ketentuan rumah sakit terhadap perencanaan tersebut. Selanjutnya, rumah sakit melakukan upaya perbaikan berdasarkan hasil pemantauan dan evaluasi berkala yang telah dilakukan. Apabila rumah sakit menyelenggarakan program penelitian dan atau pendidikan kesehatan maka pengelolaan terdapat data dan informasi yang mendukung asuhan pasien, pendidikan, serta riset telah tersedia tepat waktu dari sumber data terkini.', 1, 'Rumah sakit menetapkan regulasi pengelolaan informasi Pengelolaan Sistem Informasi untuk memenuhi kebutuhan Rumah Sakit meliputi poin a) – informasi sesuai poin a) – g) g) yang terdapat dalam yang terdapat dalam gambaran gambaran umum umum.', 'Penetapan Kebijakan', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('MRMIK.1.b', 'MRMIK', 5, 'Manajemen Rekam Medis dan Informasi Kesehatan', 2, 'MRMIK 1', 'Rumah sakit menetapkan proses manajemen informasi untuk memenuhi kebutuhan informasi internal maupun eksternal.', 'Informasi yang diperoleh selama masa perawatan pasien dalam rekam medis elektronik harus dapat dikelola dengan aman dan efektif oleh rumah sakit berdasarkan prinsip keamanan data dan informasi. Kemampuan memperoleh dan menyediakan informasi tersebut memerlukan perencanaan yang efektif. Perencanaan ini melibatkan masukan dari berbagai sumber yang membutuhkan data dan informasi, termasuk: a) Profesional Pemberi Asuhan (PPA) yang memberikan pelayanan kepada pasien b) Pimpinan rumah sakit dan para kepala departemen/unit layanan c) Staf, unit pelayanan, dan badan/individu di luar rumah sakit yang membutuhkan atau memerlukan data atau informasi tentang operasional dan proses perawatan rumah sakit. Dalam menyusun perencanaan, ditentukan prioritas kebutuhan informasi dari sumber-sumber strategi manajemen informasi rumah sakit sesuai dengan ukuran rumah sakit, kompleksitas pelayanan, ketersediaan staf terlatih, dan sumber daya manusia serta teknikal lainnya. Perencanaan yang komprehensif meliputi seluruh unit kerja dan pelayanan yang ada di rumah sakit. Rumah sakit melakukan pemantauan dan evaluasi secara berkala sesuai ketentuan rumah sakit terhadap perencanaan tersebut. Selanjutnya, rumah sakit melakukan upaya perbaikan berdasarkan hasil pemantauan dan evaluasi berkala yang telah dilakukan. Apabila rumah sakit menyelenggarakan program penelitian dan atau pendidikan kesehatan maka pengelolaan terdapat data dan informasi yang mendukung asuhan pasien, pendidikan, serta riset telah tersedia tepat waktu dari sumber data terkini.', 2, 'Terdapat bukti rumah sakit telah menerapkan proses pengelolaan informasi dalam pengelolaan informasi untuk bentuk Sistem Informasi memenuhi kebutuhan PPA, Rumah Sakit untuk memenuhi pimpinan rumah sakit, kepala kebutuhan PPA, pimpinan departemen/unit layanan dan rumah sakit, kepala badan/individu dari luar departemen/unit layanan dan rumah sakit. badan/individu dari luar rumah sakit. informasi dalam bentuk Sistem Informasi Rumah Sakit', 'Bukti penerapan proses Penerapan proses pengelolaan', 'D,O', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
