INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('MRMIK.8.d', 'MRMIK', 5, 'Manajemen Rekam Medis dan Informasi Kesehatan', 2, 'MRMIK 8', 'Setiap catatan (entry) pada rekam medis pasien mencantumkan identitas Profesional Pemberi Asuhan (PPA) yang menulis dan kapan catatan tersebut ditulis di dalam rekam medis.', 'Rumah sakit memastikan bahwa setiap catatan dalam rekam medis dapat diidentifikasi dengan tepat, dimana setiap pengisian rekam medis ditulis tanggal, jam, serta identitas Profesional Pemberi Asuhan (PPA) berupa nama jelas dan tanda tangan/paraf. Rumah sakit menetapkan proses pembenaran/koreksi terhadap kesalahan penulisan catatan dalam rekam medis. Selanjutnya dilakukan pemantauan dan evaluasi terhadap penulisan identitas, tanggal dan waktu penulisan catatan pada rekam medis pasien serta koreksi penulisan catatan dalam rekam medis.', 32, 'Telah dilakukan pemantauan dan evaluasi evaluasi (reviu) rekam medis terhadap penulisan pasien terhadap penulisan identitas, tanggal dan waktu identitas, tanggal, waktu penulisan catatan pada penulisan serta koreksi rekam medis pasien serta penulisan koreksi penulisan catatan 2. Bukti rencana tindak-lanjut dalam rekam medis, dan hasil evaluasi (reviu) sebagai hasil evaluasi yang ada telah dasar upaya perbaikan di digunakan sebagai dasar rumah sakit. upaya perbaikan di rumah sakit.', '1. Bukti pemantauan dan Komite/Tim Rekam Medis', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('MRMIK.9.a', 'MRMIK', 5, 'Manajemen Rekam Medis dan Informasi Kesehatan', 2, 'MRMIK 9', 'Rumah sakit menggunakan kode diagnosis, kode prosedur, penggunaan simbol dan singkatan baku yang seragam dan terstandar.', 'Penggunaan kode, simbol, dan singkatan yang terstandar berguna untuk mencegah terjadinya kesalahan komunikasi dan kesalahan pemberian asuhan kepada pasien. Penggunaan singkatan yang baku dan seragam menunjukkan bahwa singkatan, kode, simbol yang digunakan mempunyai satu arti/makna yang digunakan dan berlaku di semua lingkungan rumah sakit. Rumah sakit menyusun dan menetapkan daftar atau penggunaan kode, simbol dan singkatan yang digunakan dan tidak boleh digunakan di rumah sakit. Penggunaan kode, simbol, dan singkatan baku yang seragam harus konsisten dengan standar praktik profesional. Prinsip penggunaan kode di rekam medis utamanya menggunakan ICD-10 untuk kode Penyakit dan dan ICD-9 CM untuk kode Tindakan. Penggunaan kode di rekam medis sesuai dengan standar yang ditetapkan rumah sakit serta dilakukan evaluasi terkait penggunaan kode tersebut.', 33, 'Penggunaan kode diagnosis, kode prosedur, singkatan dan kode prosedur, singkatan dan simbol sesuai dengan ketetapan simbol dalam rekam medis. rumah sakit. diagnosis, kode prosedur, singkatan dan simbol dalam rekam medis.', 'Penetapan kode diagnosis, Bukti penggunaan kode', 'O,R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('MRMIK.9.b', 'MRMIK', 5, 'Manajemen Rekam Medis dan Informasi Kesehatan', 2, 'MRMIK 9', 'Rumah sakit menggunakan kode diagnosis, kode prosedur, penggunaan simbol dan singkatan baku yang seragam dan terstandar.', 'Penggunaan kode, simbol, dan singkatan yang terstandar berguna untuk mencegah terjadinya kesalahan komunikasi dan kesalahan pemberian asuhan kepada pasien. Penggunaan singkatan yang baku dan seragam menunjukkan bahwa singkatan, kode, simbol yang digunakan mempunyai satu arti/makna yang digunakan dan berlaku di semua lingkungan rumah sakit. Rumah sakit menyusun dan menetapkan daftar atau penggunaan kode, simbol dan singkatan yang digunakan dan tidak boleh digunakan di rumah sakit. Penggunaan kode, simbol, dan singkatan baku yang seragam harus konsisten dengan standar praktik profesional. Prinsip penggunaan kode di rekam medis utamanya menggunakan ICD-10 untuk kode Penyakit dan dan ICD-9 CM untuk kode Tindakan. Penggunaan kode di rekam medis sesuai dengan standar yang ditetapkan rumah sakit serta dilakukan evaluasi terkait penggunaan kode tersebut.', 34, 'Dilakukan evaluasi secara berkala penggunaan kode kode diagnosis, kode diagnosis, kode prosedur, prosedur, singkatan dan singkatan dan simbol yang simbol yang berlaku di berlaku di rumah sakit dan rumah sakit. hasilnya digunakan sebagai 2. Bukti perbaikan sesuai upaya tindak lanjut untuk hasil evaluasi. perbaikan.', '1. Bukti evaluasi penggunaan', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('MRMIK.10.a', 'MRMIK', 5, 'Manajemen Rekam Medis dan Informasi Kesehatan', 2, 'MRMIK 10', 'Rumah sakit menjamin keamanan, kerahasiaan dan kepemilikan rekam medis serta privasi pasien.', 'Rekam medis adalah pusat informasi yang digunakan untuk tujuan klinis, penelitian, bukti hukum, administrasi, dan keuangan, sehingga harus dibatasi aksesibilitasnya. Pimpinan rumah sakit bertanggung jawab atas kehilangan, kerusakan pemalsuan dan/atau penggunaan oleh orang atau badan yang tidak berhak terhadap rekam medis. Rekam medis adalah alat komunikasi yang mendukung pengambilan keputusan klinis, koordinasi pelayanan, evaluasi mutu dan ketepatan perawatan, penelitian, perlindungan hukum, pendidikan, dan akreditasi serta proses manajemen. Dengan demikian, setiap pengisian rekam medis harus dapat dijamin otentifikasinya. Menjaga kerahasiaan yang dimaksud termasuk adalah memastikan bahwa hanya individu yang berwenang yang memiliki akses ke informasi tersebut. Selain keamanan dan kerahasian maka dibutuhkan privasi sebagai hak “untuk menjadi diri sendiri atau hak otonomi”, hak untuk “menyimpan informasi tentang diri mereka sendiri dari yang diungkapkan kepada orang lain; hak untuk diketahui diri sendiri, maupun gangguan dari pihak yang tidak berkepentingan kecuali yang dimungkinkan atas perintah peraturan perundang-undangan.', 35, 'Rumah sakit menentukan otoritas pengisian rekam pengisian rekam medis medis termasuk isi dan termasuk isi dan format rekam format rekam medis. medis.', 'Penetapan penentuan otoritas', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
