VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('MRMIK.11.a', 'MRMIK', 5, 'Manajemen Rekam Medis dan Informasi Kesehatan', 2, 'MRMIK 11', 'Rumah sakit mengatur lama penyimpanan rekam medis, data, dan informasi pasien.', 'Rumah sakit menentukan jangka waktu penyimpanan rekam medis, data, dan informasi lainnya terkait pasien sesuai dengan peraturan perundang- undangan untuk mendukung asuhan pasien, manajemen, dokumentasi yang sah secara hukum, serta pendidikan dan penelitian. Rumah sakit bertanggungjawab terhadap keamanan dan kerahasiaan data rekam medis selama proses penyimpanan sampai dengan pemusnahan. Penentuan jangka waktu penyimpanan rekam medis ditentukan atas dasar nilai manfaat setiap rekam medis yang konsisten dengan kerahasiaan dan keabsahan informasi. Bila jangka waktu penyimpanan sudah habis maka rekam medis, serta data dan informasi yang terkait pasien dimusnahkan dengan prosedur yang tidak membahayakan keamanan dan kerahasiaan sesuai dengan peraturan perundang-undangan. Rumah sakit menetapkan dokumen, data dan/atau informasi tertentu terkait pasien yang memiliki nilai guna untuk disimpan abadi (permanen).', 38, 'Rumah sakit memiliki regulasi jangka waktu penyimpanan penyimpanan berkas rekam berkas rekam medis medis elektronik, data dan (kertas/elektronik), serta data informasi lainnya terkait dan informasi lainnya terkait pasien sesuai peraturan dengan pasien dan prosedur perundangan-undangan. pemusnahannya sesuai 2. Penetapan prosedur dengan peraturan pemusnahan rekam medis perundangan (kertas/elektronik) sesuai dengan peraturan perundangan.', '1. Penetapan jangka waktu', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
