INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('MRMIK.11.c', 'MRMIK', 5, 'Manajemen Rekam Medis dan Informasi Kesehatan', 2, 'MRMIK 11', 'Rumah sakit mengatur lama penyimpanan rekam medis, data, dan informasi pasien.', 'Rumah sakit menentukan jangka waktu penyimpanan rekam medis, data, dan informasi lainnya terkait pasien sesuai dengan peraturan perundang- undangan untuk mendukung asuhan pasien, manajemen, dokumentasi yang sah secara hukum, serta pendidikan dan penelitian. Rumah sakit bertanggungjawab terhadap keamanan dan kerahasiaan data rekam medis selama proses penyimpanan sampai dengan pemusnahan. Penentuan jangka waktu penyimpanan rekam medis ditentukan atas dasar nilai manfaat setiap rekam medis yang konsisten dengan kerahasiaan dan keabsahan informasi. Bila jangka waktu penyimpanan sudah habis maka rekam medis, serta data dan informasi yang terkait pasien dimusnahkan dengan prosedur yang tidak membahayakan keamanan dan kerahasiaan sesuai dengan peraturan perundang-undangan. Rumah sakit menetapkan dokumen, data dan/atau informasi tertentu terkait pasien yang memiliki nilai guna untuk disimpan abadi (permanen).', 40, 'Dokumen, data dan/atau informasi tertentu terkait tertentu terkait pasien yang pasien yang bernilai guna, bernilai guna, disimpan abadi disimpan abadi (permanen) (permanen) sesuai dengan sesuai dengan ketetapan ketetapan rumah sakit. rumah sakit', 'Bukti data dan/atau informasi', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('MRMIK.12.a', 'MRMIK', 5, 'Manajemen Rekam Medis dan Informasi Kesehatan', 2, 'MRMIK 12', 'Dalam upaya perbaikan kinerja, rumah sakit secara teratur melakukan evaluasi atau pengkajian rekam medis.', 'Setiap rumah sakit sudah menetapkan isi dan format rekam medis pasien dan mempunyai proses untuk melakukan pengkajian terhadap isi dan kelengkapan berkas rekam medis. Proses tersebut merupakan bagian dari kegiatan peningkatan kinerja rumah sakit yang dilaksanakan secara berkala. Pengkajian rekam medis berdasarkan sampel yang mewakili PPA yang memberikan pelayanan dan jenis pelayanan yang diberikan. Proses pengkajian dilakukan oleh komite/tim rekam medis melibatkan tenaga medis, keperawatan, serta PPA lainnya yang relevan dan mempunyai otorisasi untuk mengisi rekam medis pasien. Pengkajian berfokus pada ketepatan waktu, kelengkapan, keterbacaan, keabsahan dan ketentuan lainnya seperti informasi klinis yang ditetapkan rumah sakit. Isi rekam medis yang dipersyaratkan oleh peraturan perundangan dimasukkan dalam proses evaluasi rekam medis. Pengkajian rekam medis di rumah sakit tersebut dilakukan terhadap rekam medis pasien yang sedang dalam perawatan dan pasien yang sudah pulang. Hasil pengkajian dilaporkan secara berkala kepada pimpinan rumah sakit dan selanjutnya dibuat upaya perbaikan.', 41, 'Rumah sakit menetapkan komite/tim rekam medis. medis disertai uraian tugas, tanggung jawab dan wewenang.', 'Penetapan komite/tim rekam', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
