INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('MRMIK.13.1.a', 'MRMIK', 5, 'Manajemen Rekam Medis dan Informasi Kesehatan', 2, 'MRMIK 13.1', 'Rumah sakit mengembangkan, memelihara, dan menguji program untuk mengatasi waktu henti (down time) dari sistem data, baik yang terencana maupun yang tidak terencana.', 'Sistem data adalah bagian yang penting dalam memberikan perawatan/ pelayanan pasien yang aman dan bermutu tinggi. Interupsi dan kegagalan sistem data adalah kejadian yang tidak bisa dihindari. Interupsi ini sering disebut sebagai waktu henti (down time), baik yang terencana maupun tidak terencana. Waktu henti, baik yang direncanakan atau tidak direncanakan, dapat mempengaruhi seluruh sistem atau hanya mempengaruhi satu aplikasi saja. Komunikasi adalah elemen penting dari strategi kesinambungan pelayanan selama waktu henti. Pemberitahuan tentang waktu henti yang direncanakan memungkinkan dilakukannya persiapan yang diperlukan untuk memastikan bahwa operasional dapat berlanjut dengan cara yang aman dan efektif. Rumah sakit memiliki suatu perencanaan untuk mengatasi waktu henti (down time), baik yang terencana maupun tidak terencana dengan melatih staf tentang prosedur alternatif, menguji program pengelolaan gawat darurat yang dimiliki rumah sakit, melakukan pencadangan data terjadwal secara teratur, dan menguji prosedur pemulihan data.', 50, 'Terdapat prosedur yang harus dilakukan jika terjadi waktu henti sistem data (down waktu henti sistem data time) untuk mengatasi masalah (down time) untuk mengatasi pelayanan. masalah pelayanan', 'Penetapan prosedur jika terjadi', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
