INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.1.d', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 1', 'Rumah sakit menetapkan Komite/Tim PPI untuk melakukan pengkajian, perencanaan, pelaksanaan, pemantauan, dan evaluasi kegiatan PPI di rumah sakit serta menyediakan sumber daya untuk mendukung program pencegahan dan pengendalian infeksi.', '', 4, 'Direktur rumah sakit memberikan dukungan memberikan dukungan sumber sumber daya terhadap daya terhadap penyelenggaraan penyelenggaraan kegiatan PPI kegiatan PPI meliputi namun meliputi namun tidak tidak terbatas pada maksud dan terbatas pada maksud dan tujuan. tujuan. penyelenggaraan PPI IPCN', 'Bukti Direktur rumah sakit Kelengkapan fasilitas pendukung Komite/ Tim PPI', 'D,O,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.1.1.a', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 1.1', 'Direktur rumah sakit menetapkan Komite/Tim PPI untuk mengelola dan mengawasi kegiatan PPI disesuaikan dengan jenis pelayanan, kebutuhan, beban kerja, dan/atau klasifikasi rumah sakit sesuai sesuai peraturan perundang undangan. Komite/Tim PPI dipimpin oleh seorang tenaga medis yang mempunyai pengalam', '', 5, 'Rumah sakit menetapkan perawat PPI/IPCN purna purna waktu dan IPCLN sesuai waktu dan IPCLN berdasarkan ketentuan dan peraturan jumlah dan kualifikasi sesuai perundang-undangan ukuran rumah sakit, kompleksitas kegiatan, tingkat risiko, cakupan program dan sesuai dengan peraturan perundang-undangan', 'Penetapan perawat PPI/IPCN', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.1.1.b', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 1.1', 'Direktur rumah sakit menetapkan Komite/Tim PPI untuk mengelola dan mengawasi kegiatan PPI disesuaikan dengan jenis pelayanan, kebutuhan, beban kerja, dan/atau klasifikasi rumah sakit sesuai sesuai peraturan perundang undangan. Komite/Tim PPI dipimpin oleh seorang tenaga medis yang mempunyai pengalam', '', 6, 'Ada bukti perawat PPI/IPCN melaksanakan supervisi pada melaksanakan monitoring, semua kegiatan pencegahan audit dan umpan balik pada dan pengendalian infeksi di semua kegiatan pencegahan rumah sakit. dan pengendalian infeksi di rumah sakit yang meliputi Kewaspadaan Standar, Transmisi dan Penerapan Bundle HAIS. IPCN Kepala Unit/ Ruangan/ Instalasi b. Program PPI', 'Bukti perawat PPI/IPCN telah Komite/Tim PPI', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.2.a', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 2', 'Rumah sakit menyusun dan menerapkan program PPI yang terpadu dan menyeluruh untuk mencegah penularan infeksi terkait pelayanan kesehatan berdasarkan pengkajian risiko secara proaktif setiap tahun', 'Secara prinsip, kejadian HAIs sebenarnya dapat dicegah bila fasilitas pelayanan kesehatan secara konsisten melaksanakan program PPI. Pelaksanaan Pencegahan dan Pengendalian Infeksi di Fasilitas Pelayanan Kesehatan bertujuan untuk melindungi pasien, petugas kesehatan, pengunjung yang menerima pelayanan kesehatan serta masyarakat dalam lingkungannya dengan cara memutus siklus penularan penyakit infeksi melalui kewaspadaan Isolasi terdiri dari kewaspadaan standar dan berdasarkan transmisi. a) Kesebelas kewaspadaan standar tersebut yang harus di terapkan di rumah sakit adalah: (1) Kebersihan tangan (2) Alat Pelindung diri (3) Dekontaminasi peralatan perawatan pasien (4) Pengendalian lingkungan (5) Pengelolaan limbah (6) Penatalaksanaan linen (7) Perlindungan kesehatan petugas (8) Penempatan pasien (9) Kebersihan pernafasan/etika batuk dan bersin (10) Praktik menyuntik yang aman (11) Praktik lumbal pungsi yang aman b) Kewaspadaan Transmisi Kewaspadaan berdasarkan transmisi sebagai tambahan Kewaspadaan Standar yang dilaksanakan sebelum pasien didiagnosis dan setelah terdiagnosis jenis infeksinya. Jenis kewaspadaan berdasarkan transmisi sebagai berikut: (1) Melalui kontak (2) Melalui droplet (3) Melalui udara (Airborne Precautions)', 7, 'Rumah sakit menetapkan kebijakan Program PPI yang terdiri dari kewaspadaan standar dan dari kewaspadaan standar dan kewaspadaan transmisi sesuai kewaspadaan transmisi sesuai maksud dan tujuan. maksud dan tujuan diatas.', 'Penetapan Program PPI yang terdiri', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.2.b', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 2', 'Rumah sakit menyusun dan menerapkan program PPI yang terpadu dan menyeluruh untuk mencegah penularan infeksi terkait pelayanan kesehatan berdasarkan pengkajian risiko secara proaktif setiap tahun', 'Secara prinsip, kejadian HAIs sebenarnya dapat dicegah bila fasilitas pelayanan kesehatan secara konsisten melaksanakan program PPI. Pelaksanaan Pencegahan dan Pengendalian Infeksi di Fasilitas Pelayanan Kesehatan bertujuan untuk melindungi pasien, petugas kesehatan, pengunjung yang menerima pelayanan kesehatan serta masyarakat dalam lingkungannya dengan cara memutus siklus penularan penyakit infeksi melalui kewaspadaan Isolasi terdiri dari kewaspadaan standar dan berdasarkan transmisi. a) Kesebelas kewaspadaan standar tersebut yang harus di terapkan di rumah sakit adalah: (1) Kebersihan tangan (2) Alat Pelindung diri (3) Dekontaminasi peralatan perawatan pasien (4) Pengendalian lingkungan (5) Pengelolaan limbah (6) Penatalaksanaan linen (7) Perlindungan kesehatan petugas (8) Penempatan pasien (9) Kebersihan pernafasan/etika batuk dan bersin (10) Praktik menyuntik yang aman (11) Praktik lumbal pungsi yang aman b) Kewaspadaan Transmisi Kewaspadaan berdasarkan transmisi sebagai tambahan Kewaspadaan Standar yang dilaksanakan sebelum pasien didiagnosis dan setelah terdiagnosis jenis infeksinya. Jenis kewaspadaan berdasarkan transmisi sebagai berikut: (1) Melalui kontak (2) Melalui droplet (3) Melalui udara (Airborne Precautions)', 8, 'Rumah sakit melakukan evaluasi pelaksanaan program PPI. program PPI dan disertai tindak lanjut IPCN c. Pengkajian Risiko', 'Bukti evaluasi pelaksanaan Komite/Tim PPI', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.3.a', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 3', 'Rumah sakit melakukan pengkajian proaktif setiap tahunnya sebagai dasar penyusunan program PPI terpadu untuk mencegah penularan infeksi terkait pelayanan kesehatan.', 'Risiko infeksi dapat berbeda antara rumah sakit, tergantung ukuran rumah sakit, kompleksitas pelayanan dan kegiatan klinisnya, populasi pasien yang dilayani, lokasi geografis, volume pasien, dan jumlah staf yang dimiliki. Rumah sakit secara proaktif setiap tahun melakukan pengkajian risiko pengendalian infeksi (ICRA) terhadap tingkat dan kecenderungan infeksi layanan kesehatan yang akan menjadi prioritas fokus Program PPI dalam upaya pencegahan dan penurunan risiko. Pengkajian risiko tersebut meliputi namun tidak terbatas pada: a) Infeksi-infeksi yang penting secara epidemiologis yang merupakan data surveilans; b) Proses kegiatan di area-area yang berisiko tinggi terjadinya infeksi; c) Pelayanan yang menggunakan peralatan yang berisiko infeksi; d) Prosedur/tindakan-tindakan berisiko tinggi; e) Pelayanan distribusi linen bersih dan kotor; f) Pelayanan sterilisasi alat; g) Kebersihan permukaan dan lingkungan; h) Pengelolaan linen/laundri; i) Pengelolaan sampah; j) Penyediaan makanan; dan k) Pengelolaan kamar jenazah Data surveilans dikumpulkan di rumah sakit secara periodik dan dianalisis setiap triwulan. Data surveilans ini meliputi: a) Saluran pernapasan seperti prosedur dan tindakan terkait intubasi, bantuan ventilasi mekanis, trakeostomi, dan lain- lain; b) Saluran kemih seperti kateter, pembilasan urine, dan lain lain; c) Alat invasif intravaskular, saluran vena verifer, saluran vena sentral, dan lain-lain d) Lokasi operasi, perawatan, pembalutan luka, prosedur aseptik, dan lain-lain; e) Penyakit dan organisme yang penting dari sudut epidemiologik seperti Multidrug Resistant Organism dan infeksi yang virulen; dan f) Timbul nya penyakit infeksi baru atau timbul kembali penyakit infeksi di masyarakat (Emerging and or Re- Emerging Disease). Berdasarkan hasil pengkajian risiko pengendalian infeksi (ICRA), Komite/ Tim PPI menyusun Program PPI rumah sakit setiap tahunnya. Program pencegahan dan pengendalian infeksi harus komprehensif, mencakup risiko infeksi bagi pasien maupun staf yang meliputi: a) Identifikasi dan penanganan: (1) Masalah infeksi yang penting secara epidemiologis seperti data surveilans (2) Infeksi yang dapat memberikan dampak bagi pasien, staf dan pengunjung: b) Strategi lintas unit: kegiatan di area-area yang berisiko tinggi terjadinya infeksi; c) Kebersihan tangan; d) Pengawasan untuk peningkatan penggunaan antimikroba yang aman serta memastikan penyiapan obat yang aman; e) Investigasi wabah penyakit menular; f) Penerapan program vaksinasi untuk staf dan pasien: g) Pelayanan sterilisasi alat dan pelayanan yang menggunakan peralatan yang berisiko infeksi; h) Pembersihan permukaan dan kebersihan lingkungan; i) Pengelolaan linen/laundri; j) Pengelolaan sampah; k) Penyediaan makanan; dan l) Pengelolaan di kamar jenazah. Rumah sakit juga melakukan kaji banding angka kejadian dan tren di rumah sakit lain yang setara. Ilmu pengetahuan terkait pengendalian infeksi melalui pedoman praktik klinik, program pengawasan antibiotik, program PPI dan pembatasan penggunaan peralatan invasif yang tidak diperlukan telah diterapkan untuk menurunkan tingkat infeksi secara signifikan Penanggung jawab program menerapkan intervensi berbasis bukti untuk meminimalkan risiko infeksi. Pemantauan yang berkelanjutan untuk risiko yang teridentifikasi dan intervensi pengurangan risiko dipantau efektivitasnya, termasuk perbaikan yang progresif dan berkelanjutan, serta apakah sasaran program perlu diubah berdasarkan keberhasilan dan tantangan yang muncul dari data pemantauan.', 9, 'Rumah sakit secara proaktif telah melaksanakan pengendalian infeksi (ICRA) pengkajian risiko setiap tahunnya meliputi poin a) pengendalian infeksi (ICRA) – k) pada maksud dan tujuan. setiap tahunnya terhadap 2. Bukti data tersebut digunakan untuk membuat dan tingkat dan kecenderungan menentukan prioritas/ fokus infeksi layanan kesehatan pada Program PPI sesuai poin a) – k) pada maksud dan tujuan dan IPCN selanjutnya menggunakan data tersebut untuk membuat dan menentukan prioritas/ fokus pada Program PPI', '1. Bukti pengkajian risiko Komite/Tim PPI', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.3.b', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 3', 'Rumah sakit melakukan pengkajian proaktif setiap tahunnya sebagai dasar penyusunan program PPI terpadu untuk mencegah penularan infeksi terkait pelayanan kesehatan.', 'Risiko infeksi dapat berbeda antara rumah sakit, tergantung ukuran rumah sakit, kompleksitas pelayanan dan kegiatan klinisnya, populasi pasien yang dilayani, lokasi geografis, volume pasien, dan jumlah staf yang dimiliki. Rumah sakit secara proaktif setiap tahun melakukan pengkajian risiko pengendalian infeksi (ICRA) terhadap tingkat dan kecenderungan infeksi layanan kesehatan yang akan menjadi prioritas fokus Program PPI dalam upaya pencegahan dan penurunan risiko. Pengkajian risiko tersebut meliputi namun tidak terbatas pada: a) Infeksi-infeksi yang penting secara epidemiologis yang merupakan data surveilans; b) Proses kegiatan di area-area yang berisiko tinggi terjadinya infeksi; c) Pelayanan yang menggunakan peralatan yang berisiko infeksi; d) Prosedur/tindakan-tindakan berisiko tinggi; e) Pelayanan distribusi linen bersih dan kotor; f) Pelayanan sterilisasi alat; g) Kebersihan permukaan dan lingkungan; h) Pengelolaan linen/laundri; i) Pengelolaan sampah; j) Penyediaan makanan; dan k) Pengelolaan kamar jenazah Data surveilans dikumpulkan di rumah sakit secara periodik dan dianalisis setiap triwulan. Data surveilans ini meliputi: a) Saluran pernapasan seperti prosedur dan tindakan terkait intubasi, bantuan ventilasi mekanis, trakeostomi, dan lain- lain; b) Saluran kemih seperti kateter, pembilasan urine, dan lain lain; c) Alat invasif intravaskular, saluran vena verifer, saluran vena sentral, dan lain-lain d) Lokasi operasi, perawatan, pembalutan luka, prosedur aseptik, dan lain-lain; e) Penyakit dan organisme yang penting dari sudut epidemiologik seperti Multidrug Resistant Organism dan infeksi yang virulen; dan f) Timbul nya penyakit infeksi baru atau timbul kembali penyakit infeksi di masyarakat (Emerging and or Re- Emerging Disease). Berdasarkan hasil pengkajian risiko pengendalian infeksi (ICRA), Komite/ Tim PPI menyusun Program PPI rumah sakit setiap tahunnya. Program pencegahan dan pengendalian infeksi harus komprehensif, mencakup risiko infeksi bagi pasien maupun staf yang meliputi: a) Identifikasi dan penanganan: (1) Masalah infeksi yang penting secara epidemiologis seperti data surveilans (2) Infeksi yang dapat memberikan dampak bagi pasien, staf dan pengunjung: b) Strategi lintas unit: kegiatan di area-area yang berisiko tinggi terjadinya infeksi; c) Kebersihan tangan; d) Pengawasan untuk peningkatan penggunaan antimikroba yang aman serta memastikan penyiapan obat yang aman; e) Investigasi wabah penyakit menular; f) Penerapan program vaksinasi untuk staf dan pasien: g) Pelayanan sterilisasi alat dan pelayanan yang menggunakan peralatan yang berisiko infeksi; h) Pembersihan permukaan dan kebersihan lingkungan; i) Pengelolaan linen/laundri; j) Pengelolaan sampah; k) Penyediaan makanan; dan l) Pengelolaan di kamar jenazah. Rumah sakit juga melakukan kaji banding angka kejadian dan tren di rumah sakit lain yang setara. Ilmu pengetahuan terkait pengendalian infeksi melalui pedoman praktik klinik, program pengawasan antibiotik, program PPI dan pembatasan penggunaan peralatan invasif yang tidak diperlukan telah diterapkan untuk menurunkan tingkat infeksi secara signifikan Penanggung jawab program menerapkan intervensi berbasis bukti untuk meminimalkan risiko infeksi. Pemantauan yang berkelanjutan untuk risiko yang teridentifikasi dan intervensi pengurangan risiko dipantau efektivitasnya, termasuk perbaikan yang progresif dan berkelanjutan, serta apakah sasaran program perlu diubah berdasarkan keberhasilan dan tantangan yang muncul dari data pemantauan.', 10, 'Rumah sakit telah melaksanakan surveilans secara periodik dan dianalisis data secara periodik dan setiap triwulan yang meliputi a) f) dianalisis triwulan meliputi dalam maksud dan tujuan', 'Bukti pelaksanaan surveilans data', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.3.a', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 3', 'Rumah sakit melakukan pengkajian proaktif setiap tahunnya sebagai dasar penyusunan program PPI terpadu untuk mencegah penularan infeksi terkait pelayanan kesehatan.', 'Risiko infeksi dapat berbeda antara rumah sakit, tergantung ukuran rumah sakit, kompleksitas pelayanan dan kegiatan klinisnya, populasi pasien yang dilayani, lokasi geografis, volume pasien, dan jumlah staf yang dimiliki. Rumah sakit secara proaktif setiap tahun melakukan pengkajian risiko pengendalian infeksi (ICRA) terhadap tingkat dan kecenderungan infeksi layanan kesehatan yang akan menjadi prioritas fokus Program PPI dalam upaya pencegahan dan penurunan risiko. Pengkajian risiko tersebut meliputi namun tidak terbatas pada: a) Infeksi-infeksi yang penting secara epidemiologis yang merupakan data surveilans; b) Proses kegiatan di area-area yang berisiko tinggi terjadinya infeksi; c) Pelayanan yang menggunakan peralatan yang berisiko infeksi; d) Prosedur/tindakan-tindakan berisiko tinggi; e) Pelayanan distribusi linen bersih dan kotor; f) Pelayanan sterilisasi alat; g) Kebersihan permukaan dan lingkungan; h) Pengelolaan linen/laundri; i) Pengelolaan sampah; j) Penyediaan makanan; dan k) Pengelolaan kamar jenazah Data surveilans dikumpulkan di rumah sakit secara periodik dan dianalisis setiap triwulan. Data surveilans ini meliputi: a) Saluran pernapasan seperti prosedur dan tindakan terkait intubasi, bantuan ventilasi mekanis, trakeostomi, dan lain- lain; b) Saluran kemih seperti kateter, pembilasan urine, dan lain lain; c) Alat invasif intravaskular, saluran vena verifer, saluran vena sentral, dan lain-lain d) Lokasi operasi, perawatan, pembalutan luka, prosedur aseptik, dan lain-lain; e) Penyakit dan organisme yang penting dari sudut epidemiologik seperti Multidrug Resistant Organism dan infeksi yang virulen; dan f) Timbul nya penyakit infeksi baru atau timbul kembali penyakit infeksi di masyarakat (Emerging and or Re- Emerging Disease). Berdasarkan hasil pengkajian risiko pengendalian infeksi (ICRA), Komite/ Tim PPI menyusun Program PPI rumah sakit setiap tahunnya. Program pencegahan dan pengendalian infeksi harus komprehensif, mencakup risiko infeksi bagi pasien maupun staf yang meliputi: a) Identifikasi dan penanganan: (1) Masalah infeksi yang penting secara epidemiologis seperti data surveilans (2) Infeksi yang dapat memberikan dampak bagi pasien, staf dan pengunjung: b) Strategi lintas unit: kegiatan di area-area yang berisiko tinggi terjadinya infeksi; c) Kebersihan tangan; d) Pengawasan untuk peningkatan penggunaan antimikroba yang aman serta memastikan penyiapan obat yang aman; e) Investigasi wabah penyakit menular; f) Penerapan program vaksinasi untuk staf dan pasien: g) Pelayanan sterilisasi alat dan pelayanan yang menggunakan peralatan yang berisiko infeksi; h) Pembersihan permukaan dan kebersihan lingkungan; i) Pengelolaan linen/laundri; j) Pengelolaan sampah; k) Penyediaan makanan; dan l) Pengelolaan di kamar jenazah. Rumah sakit juga melakukan kaji banding angka kejadian dan tren di rumah sakit lain yang setara. Ilmu pengetahuan terkait pengendalian infeksi melalui pedoman praktik klinik, program pengawasan antibiotik, program PPI dan pembatasan penggunaan peralatan invasif yang tidak diperlukan telah diterapkan untuk menurunkan tingkat infeksi secara signifikan Penanggung jawab program menerapkan intervensi berbasis bukti untuk meminimalkan risiko infeksi. Pemantauan yang berkelanjutan untuk risiko yang teridentifikasi dan intervensi pengurangan risiko dipantau efektivitasnya, termasuk perbaikan yang progresif dan berkelanjutan, serta apakah sasaran program perlu diubah berdasarkan keberhasilan dan tantangan yang muncul dari data pemantauan.', 11, 'f) dalam maksud dan tujuan IPCN d. Peralatan Medis dan /atau Bahan Medis Habis Pakai (BMHP)', 'Komite/Tim PPI', 'W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.4.a', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 4', 'Rumah sakit mengurangi risiko infeksi terkait peralatan medis dan/atau bahan medis habis pakai (BMHP) dengan memastikan kebersihan, desinfeksi, sterilisasi, dan penyimpanan yang memenuhi syarat.', 'Prosedur/tindakan yang menggunakan peralatan medis dan/atau bahan medis habis pakai (BMHP), dapat menjadi sumber utama patogen yang menyebabkan infeksi. Kesalahan dalam membersihkan, mendesinfeksi, maupun mensterilisasi, serta penggunaan maupun penyimpanan yang tidak layak dapat berisiko penularan infeksi. Tenaga medis dan tenaga kesehatan harus mengikuti standar yang ditetapkan dalam melakukan kebersihan, desinfeksi, dan sterilisasi. Tingkat disinfeksi atau sterilisasi tergantung pada kategori peralatan medis dan/atau bahan medis habis pakai (BMHP): a) Tingkat 1 - Kritikal: Benda yang dimasukkan ke jaringan yang normal steril atau ke sistem vaskular dan membutuhkan sterilisasi. b) Tingkat 2 - Semi-kritikal: Benda yang menyentuh selaput lendir atau kulit yang tidak intak dan membutuhkan disinfeksi tingkat tinggi. c) Tingkat 3 - Non-kritikal: Benda yang menyentuh kulit intak tetapi tidak menyentuh selaput lendir, dan membutuhkan disinfeksi tingkat rendah. Pembersihan dan disinfeksi tambahan dibutuhkan untuk peralatan medis dan/atau bahan medis habis pakai (BMHP) yang digunakan pada pasien yang diisolasi sebagai bagian dari kewaspadaan berbasis transmisi. Pembersihan, desinfeksi, dan sterilisasi dapat dilakukan di area CSSD atau, di area lain di rumah sakit dengan pengawasan. Metode pembersihan, desinfeksi, dan sterilisasi dilakukan sesuai standar dan seragam di semua area rumah sakit. Staf yang memroses peralatan medis dan/atau BMHP harus mendapatkan pelatihan. Untuk mencegah kontaminasi, peralatan medis dan/atau BMHP bersih dan steril disimpan di area penyimpanan yang telah ditetapkan, bersih dan kering serta terlindung dari debu, kelembaban, dan perubahan suhu yang drastis. Idealnya, peralatan medis dan BMHP disimpan terpisah dan area penyimpanan steril memiliki akses terbatas.', 12, 'Rumah sakit telah menerapkan pengolahan sterilisasi sesuai dengan sterilisasi mengikuti peraturan perundang-undangan. peraturan perundang- undangan. peraturan perundang-undangan. Kepala/Staf CSSD', 'Bukti penerapan pengolahan Pengelolaan sterilisasi sesuai IPCN', 'D,O,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
