INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.7.1.c', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 7.1', 'Rumah sakit menetapkan pengelolaan kamar mayat dan kamar bedah mayat sesuai dengan peraturan perundang- undangan.', '', 33, 'Ada bukti pemantauan dan evaluasi, serta tindak lanjut evaluasi, serta tindak lanjut kepatuhan prinsip-prinsip PPI kepatuhan prinsip-prinsip PPI sesuai dengan peraturan (hasil audit) perundang-undangan.', 'Bukti pemantauan dan', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.7.2.a', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 7.2', 'Rumah sakit menetapkan pengelolaan limbah benda tajam dan jarum secara aman. Rumah sakit menetapkan pengelolaan limbah benda tajam dan jarum secara aman.', 'Setiap hari rumah sakit banyak menghasilkan limbah, termasuk limbah infeksius. Pembuangan limbah infeksius dengan tidak benar dapat menimbulkan risiko infeksi di rumah sakit. Hal ini nyata terjadi pada pembuangan cairan tubuh dan material terkontaminasi dengan cairan tubuh, pembuangan darah dan komponen darah, serta pembuangan limbah dari lokasi kamar mayat dan kamar bedah mayat (post mortem). Pemerintah mempunyai regulasi terkait dengan penanganan limbah infeksius dan limbah cair, sedangkan rumah sakit diharapkan melaksanakan ketentuan tersebut sehingga dapat mengurangi risiko infeksi di rumah sakit. Rumah sakit menyelenggaraan pengelolaan limbah dengan benar untuk meminimalkan risiko infeksi melalui kegiatan sebagai berikut: a) Pengelolaan limbah cairan tubuh infeksius; b) Penanganan dan pembuangan darah serta komponen darah; c) Pemulasaraan jenazah dan bedah mayat; d) Pengelolaan limbah cair; e) Pelaporan pajanan limbah infeksius. Salah satu bahaya luka karena tertusuk jarum suntik adalah terjadi penularan penyakit melalui darah (blood borne diseases). Pengelolaan limbah benda tajam dan jarum yang tidak benar merupakan kekhawatiran staf terhadap keamanannya. Kebiasaan bekerja sangat memengaruhi timbulnya risiko menderita luka dan kemungkinan terpapar penyakit secara potensial. Identifikasi dan melaksanakan kegiatan praktik berdasar atas bukti sahih (evidence based) menurunkan risiko luka karena tertusuk jarum dan benda tajam. Rumah sakit perlu mengadakan edukasi kepada staf bagaimana mengelola dengan aman benda tajam dan jarum. Pembuangan yang benar adalah dengan menggunakan wadah menyimpan khusus (safety box) yang dapat ditutup, antitertusuk, dan antibocor baik di dasar maupun di sisinya sesuai dengan peraturan perundangan. Wadah ini harus tersedia dan mudah dipergunakan oleh staf serta wadah tersebut tidak boleh terisi terlalu penuh. Pembuangan jarum yang tidak terpakai, pisau bedah (scalpel), dan limbah benda tajam lainnya jika tidak dilakukan dengan benar akan berisiko terhadap kesehatan masyarakat umumnya dan terutama pada mereka yang bekerja di pengelolaan sampah. Pembuangan wadah berisi limbah benda tajam di laut, misalnya akan menyebabkan risiko pada masyarakat karena wadah dapat rusak atau terbuka. Rumah sakit menetapkan regulasi yang memadai mencakup semua tahapan proses, termasuk identifikasi jenis dan penggunaan wadah secara tepat, pembuangan wadah, dan surveilans proses pembuangan. Salah satu bahaya luka karena tertusuk jarum suntik adalah terjadi penularan penyakit melalui darah (blood borne diseases). Pengelolaan limbah benda tajam dan jarum yang tidak benar merupakan kekhawatiran staf terhadap keamanannya. Kebiasaan bekerja sangat memengaruhi timbulnya risiko menderita luka dan kemungkinan terpapar penyakit secara potensial. Identifikasi dan melaksanakan kegiatan praktik berdasar atas bukti sahih (evidence based) menurunkan risiko luka karena tertusuk jarum dan benda tajam. Rumah sakit perlu mengadakan edukasi kepada staf bagaimana mengelola dengan aman benda tajam dan jarum. Pembuangan yang benar adalah dengan menggunakan wadah menyimpan khusus (safety box) yang dapat ditutup, anti tertusuk, dan anti bocor baik di dasar maupun di sisinya sesuai dengan peraturan perundangan. Wadah ini harus tersedia dan mudah dipergunakan oleh staf serta wadah tersebut tidak boleh terisi terlalu penuh. Pembuangan jarum yang tidak terpakai, pisau bedah (scalpel), dan limbah benda tajam lainnya jika tidak dilakukan dengan benar akan berisiko terhadap kesehatan masyarakat umumnya dan terutama pada mereka yang bekerja di pengelolaan sampah. Pembuangan wadah berisi limbah benda tajam di laut, misalnya akan menyebabkan risiko pada masyarakat karena wadah dapat rusak atau terbuka. Rumah sakit menetapkan regulasi yang memadai mencakup: a) Semua tahapan proses termasuk identifikasi jenis dan penggunaan wadah secara tepat, pembuangan wadah, dan surveilans proses pembuangan. b) Laporan tertusuk jarum dan benda tajam.', 34, 'Benda tajam dan jarum sudah dikumpulkan, disimpan di penyimpanan benda tajam dan dalam wadah yang tidak jarum dalam wadah yang sesuai tembus, tidak bocor, berwarna kuning, diberi label infeksius, IPCN dan dipergunakan hanya sekali Kepala/ Staf Unit pakai sesuai dengan peraturan Pelayanan perundang-undangan. Petugas Cleaning Service', 'Pengumpulan, pelabelan, IPCLN', 'O,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
