INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.7.2.d', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 7.2', 'Rumah sakit menetapkan pengelolaan limbah benda tajam dan jarum secara aman. Rumah sakit menetapkan pengelolaan limbah benda tajam dan jarum secara aman.', 'Setiap hari rumah sakit banyak menghasilkan limbah, termasuk limbah infeksius. Pembuangan limbah infeksius dengan tidak benar dapat menimbulkan risiko infeksi di rumah sakit. Hal ini nyata terjadi pada pembuangan cairan tubuh dan material terkontaminasi dengan cairan tubuh, pembuangan darah dan komponen darah, serta pembuangan limbah dari lokasi kamar mayat dan kamar bedah mayat (post mortem). Pemerintah mempunyai regulasi terkait dengan penanganan limbah infeksius dan limbah cair, sedangkan rumah sakit diharapkan melaksanakan ketentuan tersebut sehingga dapat mengurangi risiko infeksi di rumah sakit. Rumah sakit menyelenggaraan pengelolaan limbah dengan benar untuk meminimalkan risiko infeksi melalui kegiatan sebagai berikut: a) Pengelolaan limbah cairan tubuh infeksius; b) Penanganan dan pembuangan darah serta komponen darah; c) Pemulasaraan jenazah dan bedah mayat; d) Pengelolaan limbah cair; e) Pelaporan pajanan limbah infeksius. Salah satu bahaya luka karena tertusuk jarum suntik adalah terjadi penularan penyakit melalui darah (blood borne diseases). Pengelolaan limbah benda tajam dan jarum yang tidak benar merupakan kekhawatiran staf terhadap keamanannya. Kebiasaan bekerja sangat memengaruhi timbulnya risiko menderita luka dan kemungkinan terpapar penyakit secara potensial. Identifikasi dan melaksanakan kegiatan praktik berdasar atas bukti sahih (evidence based) menurunkan risiko luka karena tertusuk jarum dan benda tajam. Rumah sakit perlu mengadakan edukasi kepada staf bagaimana mengelola dengan aman benda taj