INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.10.d', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 10', 'Rumah sakit menyediakan APD untuk kewaspadaan (barrier precautions) dan prosedur isolasi untuk penyakit menular melindungi pasien dengan imunitas rendah (immunocompromised) dan mentransfer pasien dengan airborne diseases di dalam rumah sakit dan keluar rumah sakit serta penempatannya dalam waktu sin', '', 48, 'Ada bukti pemantauan ruang tekanan negatif dan negative (hasil audit) penempatan pasien secara rutin. IPCN Kepala Unit/Ruangan', 'Bukti pemantauan ruang tekanan Ruang tekanan negatif Komite/Tim PPI', 'D,O,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.10.1.a', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 10.1', 'Rumah sakit mengembangkan dan menerapkan sebuah proses untuk menangani lonjakan mendadak (outbreak) penyakit infeksi air borne.', 'Rumah sakit menetapkan kebijakan berupa regulasi isolasi dan pemberian penghalang pengaman serta menyediakan fasilitasnya. Regulasi rumah sakit ditetapkan berdasar atas bagaimana penyakit menular dan cara menangani pasien infeksius atau pasien immuno-suppressed. Regulasi isolasi juga memberikan perlindungan kepada staf dan pengunjung serta lingkungan pasien. (lihat juga PP 3) Kewaspadaan terhadap udara penting untuk mencegah penularan bakteri infeksius yang dapat bertahan lama di udara. Pasien dengan infeksi “airborne” sebaiknya ditempatkan di kamar dengan tekanan negatif (negative pressure room). Jika struktur bangunan tidak memungkinkan membangun ruangan dengan tekanan negatif maka rumah sakit dapat mengalirkan udara lewat sistem penyaring HEPA (high effieciency particulate air) pada tingkat paling sedikit 12 kali pertukaran udara per jam. Rumah sakit sebaiknya menetapkan program untuk menangani pasien infeksi “air borne” dalam waktu singkat jika sistem HEPA tidak ada, termasuk jika ada banyak pasien masuk menderita infeksi menular. Pembersihan kamar dengan benar setiap hari selama pasien tinggal di rumah sakit dan pembersihan kembali setelah pasien keluar pulang harus dilakukan sesuai dengan tandar atau pedoman pengedalian infeksi', 49, 'Rumah sakit menerapkan proses pengelolaan pasien bila terjadi ledakan pasien (outbreak) terjadi ledakan pasien penyakit infeksi air borne (outbreak) penyakit infeksi air borne. pengelolaan pasien bila terjadi ledakan pasien (outbreak) penyakit infeksi air borne. Komite/Tim PPI', 'Regulasi pengelolaan pasien bila Bukti penerapan proses IPCN', 'D,R,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.10.1.b', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 10.1', 'Rumah sakit mengembangkan dan menerapkan sebuah proses untuk menangani lonjakan mendadak (outbreak) penyakit infeksi air borne.', 'Rumah sakit menetapkan kebijakan berupa regulasi isolasi dan pemberian penghalang pengaman serta menyediakan fasilitasnya. Regulasi rumah sakit ditetapkan berdasar atas bagaimana penyakit menular dan cara menangani pasien infeksius atau pasien immuno-suppressed. Regulasi isolasi juga memberikan perlindungan kepada staf dan pengunjung serta lingkungan pasien. (lihat juga PP 3) Kewaspadaan terhadap udara penting untuk mencegah penularan bakteri infeksius yang dapat bertahan lama di udara. Pasien dengan infeksi “airborne” sebaiknya ditempatkan di kamar dengan tekanan negatif (negative pressure room). Jika struktur bangunan tidak memungkinkan membangun ruangan dengan tekanan negatif maka rumah sakit dapat mengalirkan udara lewat sistem penyaring HEPA (high effieciency particulate air) pada tingkat paling sedikit 12 kali pertukaran udara per jam. Rumah sakit sebaiknya menetapkan program untuk menangani pasien infeksi “air borne” dalam waktu singkat jika sistem HEPA tidak ada, termasuk jika ada banyak pasien masuk menderita infeksi menular. Pembersihan kamar dengan benar setiap hari selama pasien tinggal di rumah sakit dan pembersihan kembali setelah pasien keluar pulang harus dilakukan sesuai dengan tandar atau pedoman pengedalian infeksi', 50, 'Rumah sakit menyediakan ruang isolasi dengan tekanan negatif bila terjadi ledakan pasien negatif bila terjadi ledakan (outbreak) pasien (outbreak) sesuai dengan peraturan IPCN perundangan. Kepala Unit/Ruangan', 'Ruang isolasi dengan tekanan Komite/Tim PPI', 'O,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
