tihan kepada staf Komite/Tim PPI', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.11.a', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 11', 'Kebersihan tangan menggunakan sabun dan desinfektan adalah sarana efektif untuk mencegah dan mengendalikan infeksi.', '', 52, 'Rumah sakit telah menerapkan hand hygiene hygiene yang mencakup kapan, di mana, dan bagaimana IPCN melakukan cuci tangan Kepala Unit/Ruangan mempergunakan sabun (hand wash) dan atau Lihat SKP dengan disinfektan (hand rubs) serta ketersediaan fasilitas hand hygiene.', 'Penerapan momen hand Komite/Tim PPI Hand hygiene', 'O,S,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
