INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.11.1.a', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 11.1', 'Sarung tangan, masker, pelindung mata, serta alat pelindung diri lainnya tersedia dan digunakan secara tepat apabila disyaratkan. 3) Maksud dan tujaun PPI 11 dan PPI 11.1 Kebersihan tangan, menggunakan alat pelindung diri, serta disinfektan adalah sarana efektif untuk mencegah dan mengendalikan infe', '', 59, 'Standar PPI 12 Kegiatan PPI diintegrasikan dengan program PMKP (Peningkatan Mutu dan Keselamatan Pasien) dengan menggunakan indikator yang secara epidemiologik penting bagi rumah sakit.', '', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.11.1.b', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 11.1', 'Sarung tangan, masker, pelindung mata, serta alat pelindung diri lainnya tersedia dan digunakan secara tepat apabila disyaratkan. 3) Maksud dan tujaun PPI 11 dan PPI 11.1 Kebersihan tangan, menggunakan alat pelindung diri, serta disinfektan adalah sarana efektif untuk mencegah dan mengendalikan infe', '', 60, 'Maksud dan Tujuan PPI 12 Rumah sakit menggunakan indikator sebagai informasi untuk memperbaiki kegiatan PPI dan mengurangi tingkat infeksi yang terkait layanan kesehatan sampai tingkat serendah-rendahnya. Rumah sakit dapat menggunakan data indikator dan informasi dan membandingkan dengan tingkat dan kecenderungan di rumah sakit lain. Semua departemen/unit layanan diharuskan ikut serta menentukan prioritas yang diukur di tingkat rumah sakit dan tingkat departemen/unit layanan program PPI.', '', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
