INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PPI.13.a', 'PPI', 6, 'Pencegahan dan Pengendalian Infeksi', 2, 'PPI 13', 'Rumah sakit melakukan edukasi tentang PPI kepada staf klinis dan nonklinis, pasien, keluarga pasien, serta petugas lainnya yang terlibat dalam pelayanan pasien.', 'Agar program PPI efektif harus dilakukan edukasi kepada staf klinis dan nonkliniks tentang program PPI pada waktu mereka baru bekerja di rumah sakit dan diulangi secara teratur. Edukasi diikuti oleh staf klinik dan staf nonklinik, pasien, keluarga pasien, pedagang, dan juga pengunjung. Pasien dan keluarga didorong untuk berpartisipasi dalam implementasi program PPI. Pelatihan diberikan sebagai bagian dari orientasi kepad semua staf baru dan dilakukan pelatihan kembali secara berkala, atau paling sedikit jika ada perubahan kebijakan, prosedur, dan praktik yang menjadi panduan program PPI. Dalam pendidikan juga disampaikan temuan dan kecenderungan ukuran kegiatan. Berdasar atas hal di atas maka rumah sakit agar menetapkan program pelatihan PPI yang meliputi pelatihan untuk: a) Orientasi pegawai baru baik staf klinis maupun nonklinis di tingkat rumah sakit maupun di unit pelayanan; b) Staf klinis (profesional pemberi asuhan) secara berkala; c) staf nonklinis; d) Pasien dan keluarga; dan e) Pengunjung.', 66, 'Rumah sakit menetapkan program pelatihan dan dan edukasi tentang PPI edukasi tentang PPI yang meliputi a) – e) yang ada pada meliputi a) – e) yang ada pada maksud dan tujuan. maksud dan tujuan.', 'Penetapan program pelatihan', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
