INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.1.a', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 1', 'Rumah sakit menetapkan proses skrining baik pasien rawat inap maupun rawat jalan untuk mengidentifikasi pelayanan Kesehatan yang dibutuhkan sesuai dengan misi serta sumber daya rumah sakit.', 'Menyesuaikan kebutuhan pasien dengan misi dan sumber daya rumah sakit bergantung pada informasi yang diperoleh tentang kebutuhan pasien dan kondisinya lewat skrining pada kontak pertama. Skrining penerimaan pasien dilaksanakan melalui jalur cepat (fast track) kriteria triase, evaluasi visual atau pengamatan, atau hasil pemeriksaan fisis, psikologis, laboratorium klinis, atau diagnostik imajing sebelumnya. Skrining dapat dilakukan di luar rumah sakit seperti ditempat pasien berada, di ambulans, atau saat pasien tiba di rumah sakit. Keputusan untuk mengobati, mentransfer atau merujuk dilakukan setelah hasil hasil skrining selesai dievaluasi. Bila rumah sakit mempunyai kemampuan memberikan pelayanan yang dibutuhkan serta konsisten dengan misi dan kemampuan pelayanannya maka dipertimbangkan untuk menerima pasien rawat inap atau pasien rawat jalan. Skirining khusus dapat dilakukan oleh rumah sakit sesuai kebutuhan seperti skrining infeksi (TBC, PINERE, COVID-19, dll), skrining nyeri, skrining geriatri, skrining jatuh atau skrining lainnya.', 1, 'Rumah sakit telah menetapkan regulasi akses Akses dan dan kesinambungan Kesinambungan pelayanan (AKP) meliputi pelayanan (AKP) meliputi poin a) – f) pada gambaran poin a) – f) pada umum gambaran umum.', 'Penetapan Pedoman', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
