INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.1.c', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 1', 'Rumah sakit menetapkan proses skrining baik pasien rawat inap maupun rawat jalan untuk mengidentifikasi pelayanan Kesehatan yang dibutuhkan sesuai dengan misi serta sumber daya rumah sakit.', 'Menyesuaikan kebutuhan pasien dengan misi dan sumber daya rumah sakit bergantung pada informasi yang diperoleh tentang kebutuhan pasien dan kondisinya lewat skrining pada kontak pertama. Skrining penerimaan pasien dilaksanakan melalui jalur cepat (fast track) kriteria triase, evaluasi visual atau pengamatan, atau hasil pemeriksaan fisis, psikologis, laboratorium klinis, atau diagnostik imajing sebelumnya. Skrining dapat dilakukan di luar rumah sakit seperti ditempat pasien berada, di ambulans, atau saat pasien tiba di rumah sakit. Keputusan untuk mengobati, mentransfer atau merujuk dilakukan setelah hasil hasil skrining selesai dievaluasi. Bila rumah sakit mempunyai kemampuan memberikan pelayanan yang dibutuhkan serta konsisten dengan misi dan kemampuan pelayanannya maka dipertimbangkan untuk menerima pasien rawat inap atau pasien rawat jalan. Skirining khusus dapat dilakukan oleh rumah sakit sesuai kebutuhan seperti skrining infeksi (TBC, PINERE, COVID-19, dll), skrining nyeri, skrining geriatri, skrining jatuh atau skrining lainnya.', 3, 'Ada proses untuk memberikan hasil Hasil pemeriksaan pemeriksaan diagnostik diagnostik diserahkan kepada tenaga kesehatan kepada tenaga yang kompeten/terlatih kesehatan kompeten untuk bertanggung jawab / terlatih yang diberi menentukan apakah pasien tanggungjawab untuk menentukan pasien akan diterima, akan diterima, ditransfer, ditransfer atau atau dirujuk. dirujuk 2. SPK dan RKK Staf keperawatan', '1. Bukti rekam medis: Staf medis', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.1.d', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 1', 'Rumah sakit menetapkan proses skrining baik pasien rawat inap maupun rawat jalan untuk mengidentifikasi pelayanan Kesehatan yang dibutuhkan sesuai dengan misi serta sumber daya rumah sakit.', 'Menyesuaikan kebutuhan pasien dengan misi dan sumber daya rumah sakit bergantung pada informasi yang diperoleh tentang kebutuhan pasien dan kondisinya lewat skrining pada kontak pertama. Skrining penerimaan pasien dilaksanakan melalui jalur cepat (fast track) kriteria triase, evaluasi visual atau pengamatan, atau hasil pemeriksaan fisis, psikologis, laboratorium klinis, atau diagnostik imajing sebelumnya. Skrining dapat dilakukan di luar rumah sakit seperti ditempat pasien berada, di ambulans, atau saat pasien tiba di rumah sakit. Keputusan untuk mengobati, mentransfer atau merujuk dilakukan setelah hasil hasil skrining selesai dievaluasi. Bila rumah sakit mempunyai kemampuan memberikan pelayanan yang dibutuhkan serta konsisten dengan misi dan kemampuan pelayanannya maka dipertimbangkan untuk menerima pasien rawat inap atau pasien rawat jalan. Skirining khusus dapat dilakukan oleh rumah sakit sesuai kebutuhan seperti skrining infeksi (TBC, PINERE, COVID-19, dll), skrining nyeri, skrining geriatri, skrining jatuh atau skrining lainnya.', 4, 'Bila kebutuhan pasien tidak D1. Bukti rekam medis dapat dipenuhi sesuai misi pasien dirujuk oleh dan sumber daya yang ada, karena fasilitas maka rumah sakit akan pelayanan yang ada di merujuk atau membantu rumah sakit tidak pasien ke fasilitas pelayanan dapat memenuhi yang sesuai kebutuhannya. kebutuhan pasien 2. Bukti rekam medis pasien dirujuk ke fasilitas Kesehatan lain yang mampu memberikan pelayanan yang dibutuhkan pasien PPA Petugas rujukan', 'Dokter IGD', 'W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.1.1.a', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 1.1', 'Pasien dengan kebutuhan darurat, sangat mendesak, atau yang membutuhkan pertolongan segera diberikan prioritas untuk pengkajian dan tindakan.', 'Pasien dengan kebutuhan gawat dan/atau darurat, atau pasien yang membutuhkan pertolongan segera diidentifikasi menggunakan proses triase berbasis bukti untuk memprioritaskan kebutuhan pasien, dengan mendahulukan dari pasien yang lain. Pada kondisi bencana, dapat menggunakan triase bencana. Sesudah dinyatakan pasien darurat, mendesak dan membutuhkan pertolongan segera, dilakukan pengkajian dan memberikan pelayanan sesegera mungkin. Kriteria psikologis berbasis bukti dibutuhkan dalam proses triase untuk kasus kegawatdaruratan psikiatris. Pelatihan bagi staf diadakan agar staf mampu menerapkan kriteria triase berbasis bukti dan memutuskan pasien yang membutuhkan pertolongan segera serta pelayanan yang dibutuhkan.', 5, 'Proses triase dan pelayanan kegawatdaruratan telah proses triase dan diterapkan oleh staf yang pelayanan kompeten dan bukti dokumen kegawatdaruratan kompetensi dan kewenangan dilaksanakan oleh staf klinisnya tersedia. yang kompeten (mempunyai Sertifika: PPGD, BTCLS, ACLS, ATLS) 2. SPK dan RKK masing- masing staf klinis di IGD PPA', '1. Bukti rekam medis Dokter IGD', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.1.1.b', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 1.1', 'Pasien dengan kebutuhan darurat, sangat mendesak, atau yang membutuhkan pertolongan segera diberikan prioritas untuk pengkajian dan tindakan.', 'Pasien dengan kebutuhan gawat dan/atau darurat, atau pasien yang membutuhkan pertolongan segera diidentifikasi menggunakan proses triase berbasis bukti untuk memprioritaskan kebutuhan pasien, dengan mendahulukan dari pasien yang lain. Pada kondisi bencana, dapat menggunakan triase bencana. Sesudah dinyatakan pasien darurat, mendesak dan membutuhkan pertolongan segera, dilakukan pengkajian dan memberikan pelayanan sesegera mungkin. Kriteria psikologis berbasis bukti dibutuhkan dalam proses triase untuk kasus kegawatdaruratan psikiatris. Pelatihan bagi staf diadakan agar staf mampu menerapkan kriteria triase berbasis bukti dan memutuskan pasien yang membutuhkan pertolongan segera serta pelayanan yang dibutuhkan.', 6, 'Staf telah menggunakan kriteria triase berbasis bukti triase berbasis bukti untuk memprioritaskan (berdasarkan referensi pasien sesuai dengan ilmiah) kegawatannya PPA', 'Bukti rekam medis: Kriteria Pelaksanaan triase Dokter IGD', 'D,O,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.1.1.c', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 1.1', 'Pasien dengan kebutuhan darurat, sangat mendesak, atau yang membutuhkan pertolongan segera diberikan prioritas untuk pengkajian dan tindakan.', 'Pasien dengan kebutuhan gawat dan/atau darurat, atau pasien yang membutuhkan pertolongan segera diidentifikasi menggunakan proses triase berbasis bukti untuk memprioritaskan kebutuhan pasien, dengan mendahulukan dari pasien yang lain. Pada kondisi bencana, dapat menggunakan triase bencana. Sesudah dinyatakan pasien darurat, mendesak dan membutuhkan pertolongan segera, dilakukan pengkajian dan memberikan pelayanan sesegera mungkin. Kriteria psikologis berbasis bukti dibutuhkan dalam proses triase untuk kasus kegawatdaruratan psikiatris. Pelatihan bagi staf diadakan agar staf mampu menerapkan kriteria triase berbasis bukti dan memutuskan pasien yang membutuhkan pertolongan segera serta pelayanan yang dibutuhkan.', 7, 'Pasien darurat dinilai dan distabilkan sesuai kapasitas monitoring pasien darurat di rumah sakit sebelum IGD sebelum pasien ditransfer ke ruang rawat dilakukan transfer ke rawat atau dirujuk dan inap atau dirujuk) didokumentasikan dalam rekam medik PPA', 'Bukti rekam medis: Dokter IGD', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.1.2.a', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 1.2', 'Rumah sakit melakukan skrining kebutuhan pasien saat admisi rawat inap untuk menetapkan pelayanan preventif, paliatif, kuratif, rehabilitatif, pelayanan khusus/spesialistik atau pelayanan intensif.', 'Ketika pasien diputuskan diterima untuk masuk rawat inap, maka proses skrining akan membantu staf mengidentifikasi pelayanan preventif, kuratif, rehabilitatif, paliatif yang dibutuhkan pasien kemudian menentukan pelayanan yang paling sesuai dan mendesak atau yang paling diprioritaskan. Setiap rumah sakit harus menetapkan kriteria prioritas untuk menentukan pasien yang membutuhkan pelayanan di unit khusus/spesialistik (misalnya unit luka bakar atau transplantasi organ) atau pelayanan di unit intensif (misalnya ICU, ICCU, NICU, PICU, pascaoperasi). Kriteria prioritas meliputi kriteria masuk dan kriteria keluar menggunakan parameter diagnostik dan atau parameter objektif termasuk kriteria berbasis fisiologis. Dengan mempertimbangkan bahwa pelayanan di unit khusus/spesialistik dan di unit intensif menghabiskan banyak sumber daya, maka rumah sakit dapat membatasi hanya pasien dengan kondisi medis yang reversibel yang dapat diterima dan pasien kondisi khusus termasuk menjelang akhir kehidupan yang sesuai dengan peraturan perundangundangan. Staf di unit khusus/spesialistik atau unit intensif berpartisipasi dalam menentukan kriteria masuk dan kriteria keluar dari unit tersebut. Kriteria dipergunakan untuk menentukan apakah pasien dapat diterima di unit tersebut, baik dari dalam atau dari luar rumah sakit. Pasien yang diterima di unit tersebut harus dilakukan pengkajian ulang untuk menentukan apakah kondisi pasien berubah sehingga tidak memerlukan lagi pelayanan khusus/intensif misalnya, jika status fisiologis sudah stabil dan pemantauan intensif baik sehingga tindakan lain tidak diperlukan lagi maka pasien dapat dipindah ke unit layanan yang lebih rendah (seperti unit rawat inap atau unit pelayanan paliatif). Apabila rumah sakit melakukan penelitian atau menyediakan pelayanan spesialistik atau melaksanakan program, penerimaan pasien di program tersebut harus melalui kriteria tertentu atau ketentuan protokol. Mereka yang terlibat dalam riset atau program lain harus terlibat dalam menentukan kriteria atau protokol. Penerimaan ke dalam program tercatat di rekam medis pasien termasuk kriteria atau protokol yang diberlakukan terhadap pasien yang diterima masuk', 8, 'Rumah sakit telah melaksanakan skrining pasien skrining pasien yang masuk masuk rawat inap untuk rawat inap yang berisi menetapkan kebutuhan penetapan kebutuhan pelayanan preventif, paliatif, pelayanan preventif, paliatif, kuratif, dan rehabilitatif, kuratif, dan rehabilitatif, pelayanan khusus/spesialistik pelayanan khusus/spesialistik atau pelayanan intensif. atau pelayanan intensif', 'Bukti rekam medis: Formulir', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
