INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.2.b', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 2', '', '', 16, 'Rumah sakit telah menerapkan sistem pendaftaran pasien pasien rawat pendaftaran pasien rawat jalan dan rawat inap baik secara jalan dan rawat inap baik online maupun offline secara offline maupun 2. Laporan evaluasi dan tindak secara online dan lanjut Sistem pendaftaran pasien dilakukan evaluasi dan secara online dan offline tindak lanjutnya.', '1. Bukti penerapan sistem Staf pendaftaran', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.2.c', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 2', '', '', 17, 'Rumah sakit telah memberikan informasi informasi tentang rencana tentang rencana asuhan asuhan yang akan diberikan yang akan diberikan, hasil pada pengkajian awal rawat asuhan yang diharapkan inap, dan hasil yang diharapkan serta perkiraan biaya yang 2. Bukti penjelasan perkiraan biaya harus dibayarkan oleh oleh staf admisi saat melakukan pasien/keluarga registrasi awat inap (formulir khusus atau ada pada persetujuan umum yang sudah terisi) (Lihat KE 4) Staf pendaftaran pasien/keluarga', '1. Bukti rekam medis pemberian DPJP', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.2.d', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 2', '', '', 18, 'Saat diterima sebagai pasien rawat inap, pasien edukasi dan orientasi tentang ruang dan keluarga mendapat rawat inap edukasi dan orientasi tentang ruang rawat inap Kepala instalasi/ ruangan Pasien/Keluarga', 'Bukti rekam medis: pemberian PPA', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.2.1.a', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 2.1', 'Rumah sakit menetapkan proses untuk mengelola alur pasien di seluruh area rumah sakit.', 'Rumah sakit menetapkan pengelolaan alur pasien saat terjadi penumpukan pasien di UGD sementara tempat tidur di rawat inap sedang terisi penuh. Pengelolaan alur tersebut harus dilakukan secara efektif mulai dari penerimaan, pengkaijan, tindakan, transfer pasien sampai pemulangan untuk mengurangi penundaan asuhan kepada pasien. Komponen pengelolaan alur pasien tersebut meliputi: a) Ketersediaan tempat tidur di tempat sementara/transit/intermediate sebelum mendapatkan tempat tidur di rawat inap; b) Perencanaan fasilitas, peralatan, utilitas, teknologi medis, dan kebutuhan lain untuk mendukung penempatan sementara pasien; c) Perencanaan tenaga untuk memberikan asuhan pasien di tempat sementara/transit termasuk pasien yang diobservasi di unit gawat darurat; d) Alur pelayanan pasien di tempat sementara/transit meliputi pemberian asuhan, tindakan, pemeriksaan laboratorium, pemeriksaan radiologi, tindakan di kamar operasi, dan unit pascaanestes harus sama seperti yang diberikan dirawat inap; e) Efisiensi pelayanan nonklinis penunjang asuhan dan tindakan kepada pasien (seperti kerumahtanggaan dan transportasi); f) Memberikan asuhan pasien yang sama kepada pasien yang dirawat di tempat sementara/transit/intermediate seperti perawatan kepada pasien yang dirawat di ruang rawat inap; dan g) Akses pelayanan yang bersifat mendukung (seperti pekerja sosial, keagamaan atau bantuan spiritual, dan sebagainya). h) Pemantauan dan perbaikan proses ini bermanfaat untuk mengatasi masalah penumpukan pasien. Semua staf rumah sakit, mulai dari unit gawat darurat, unit rawat inap, staf medis, keperawatan, administrasi, lingkungan, dan manajemen risiko dapat ikut berperan serta menyelesaikan masalah alur pasien ini. Koordinasi dapat dilakukan oleh Manajer Pelayanan Pasien (MPP)/Case Manager. Rumah sakit harus menetapkan standar waktu berapa lama pasien dapat diobservasi di unit gawat darurat dan kapan harus di transfer ke di lokasi sementara/transit/intermediate sebelum ditransfer ke unit rawat inap di rumah sakit. Diharapkan rumah sakit dapat mengatur dan menyediakan tempat tersebut bagi pasien.', 19, 'Rumah sakit telah melaksanakan pengelolaan untuk menghindari alur pasien untuk penumpukan, mencakup poin menghindari penumpukan. a) – g) pada maksud dan Mencakup poin a) – g) pada tujuan. maksud dan tujuan pasien mencakup poin a) g) pada maksud dan tujuan. PPA Staf pendaftaran MPP', 'Bukti pengelolaan alur pasien Pengelolaan kelancaran alur Ka IGD', 'D,O,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
