INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.5.2.d', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 5.2', 'Rumah sakit menetapkan proses untuk mengelola dan melakukan tindak lanjut pasien dan memberitahu staf rumah sakit bahwa mereka berniat keluar rumah sakit serta menolak rencana asuhan medis.', '', 45, 'Dokter keluarga (bila ada) atau dokter yang memberi kepada dokter keluarga (bila asuhan berikutnya kepada ada) atau dokter yang pasien diberitahu tentang memberikan asuhan kondisi tersebut. berikutnya tentang kondisi pasien yang keluar rumah sakit serta menolak rencana asuhan medis PPA lainnya', 'Bukti pemberian informasi DPJP', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.5.2.e', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 5.2', 'Rumah sakit menetapkan proses untuk mengelola dan melakukan tindak lanjut pasien dan memberitahu staf rumah sakit bahwa mereka berniat keluar rumah sakit serta menolak rencana asuhan medis.', '', 46, 'Ada dokumentasi rumah sakit melakukan pengkajian alasan pasien keluar rumah untuk mengetahui alasan sakit atas permintaan pasien keluar rumah sakit sendiri, menolak asuhan, apakah permintaan sendiri, atau tidak melanjutkan menolak asuhan medis, atau pengobatan. tidak melanjutkan program pengobatan.', 'Bukti adanya pengkajian', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.5.3.a', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 5.3', 'Rumah sakit menetapkan proses untuk mengelola pasien yang menolak rencana asuhan medis yang melarikan diri.', 'Jika seorang pasien rawat inap atau rawat jalan telah selesai menjalani pemeriksaan lengkap dan sudah ada rekomendasi tindakan yang akan dilakukan, kemudian pasien memutuskan meninggalkan rumah sakit maka pasien ini dianggap sebagai pasien keluar dan menolak rencana asuhan medis. Pasien rawat inap dan rawat jalan (termasuk pasien dari unit gawat darurat) berhak menolak tindakan medis dan keluar rumah sakit. Pasien ini menghadapi risiko karena menerima pelayanan atau tindakan tidak lengkap yang berakibat terjadi kerusakan permanen atau kematian. Jika seorang pasien rawat inap atau rawat jalan minta untuk keluar dari rumah sakit tanpa persetujuan dokter maka pasien harus diberitahu tentang risiko medis oleh dokter yang membuat rencana asuhan atau tindakan dan proses keluarnya pasien sesuai dengan regulasi rumah sakit. Jika pasien mempunyai dokter keluarga maka dokter keluarga tersebut harus diberitahu tentang keputusan pasien. Bila tidak ada dokter keluarga maka pasien dimotivasi untuk mendapat/mencari pelayanan kesehatan lebih lanjut. Harus diupayakan agar mengetahui alasan mengapa pasien keluar menolak rencana asuhan medis. Rumah sakit perlu mengetahui alasan ini agar dapat melakukan komunikasi lebih baik dengan pasien dan atau keluarga pasien dalam rangka memperbaiki proses. Jika pasien menolak rencana asuhan medis tanpa memberi tahu siapapun di dalam rumah sakit atau ada pasien rawat jalan yang menerima pelayanan kompleks atau pelayanan untuk menyelamatkan jiwa, seperti kemoterapi atau terapi radiasi, tidak kembali ke rumah sakit maka rumah sakit harus berupaya menghubungi pasien untuk memberi tahu tentang potensi risiko bahaya yang ada. Rumah sakit menetapkan regulasi untuk proses ini sesuai dengan peraturan perundangan yang berlaku, termasuk rumah sakit membuat laporan ke dinas kesehatan atau kementerian kesehatan tentang kasus infeksi dan memberi informasi tentang pasien yang mungkin mencelakakan dirinya atau orang lain.', 47, 'Ada regulasi yang mengatur pasien rawat inap dan rawat mengatur tentang pasien jalan yang meninggalkan rumah rawat inap dan rawat jalan sakit tanpa pemberitahuan yang meninggalkan rumah (melarikan diri). sakit tanpa pemberitahuan (melarikan diri)', 'Penetapan regulasi yang', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
