INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.5.4.a', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 5.4', 'Pasien dirujuk ke fasilitas pelayanan kesehatan lain berdasar atas kondisi pasien untuk memenuhi kebutuhan asuhan berkesinambungan dan sesuai dengan kemampuan fasilitas kesehatan penerima untuk memenuhi kebutuhan pasien.', 'Pasien dirujuk ke fasilitas kesehatan lain didasarkan atas kondisi pasien dan kebutuhan untuk memperoleh asuhan berkesinambungan. Rujukan pasien antara lain untuk memenuhi kebutuhan pasien atau konsultasi spesialistik dan tindakan, serta penunjang diagnostik. Jika pasien dirujuk ke rumah sakit lain, yang merujuk harus memastikan fasilitas kesehatan penerima menyediakan pelayanan yang dapat memenuhi kebutuhan pasien dan mempunyai kapasitas menerima pasien. Diperoleh kepastian terlebih dahulu dan kesediaan menerima pasien serta persyaratan rujukan diuraikan dalam kerja sama formal atau dalam bentuk perjanjian. Ketentuan seperti ini dapat memastikan kesinambungan asuhan tercapai dan kebutuhan pasien terpenuhi. Rujukan terjadi juga ke fasilitas kesehatan lain dengan atau tanpa ada perjanjian formal.', 50, 'Ada regulasi tentang rujukan sesuai dengan peraturan pelaksanaan rujukan sesuai perundang-undangan. dengan peraturan perundang-undangan.', 'Penetapan regulasi', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
