INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.5.4.c', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 5.4', 'Pasien dirujuk ke fasilitas pelayanan kesehatan lain berdasar atas kondisi pasien untuk memenuhi kebutuhan asuhan berkesinambungan dan sesuai dengan kemampuan fasilitas kesehatan penerima untuk memenuhi kebutuhan pasien.', 'Pasien dirujuk ke fasilitas kesehatan lain didasarkan atas kondisi pasien dan kebutuhan untuk memperoleh asuhan berkesinambungan. Rujukan pasien antara lain untuk memenuhi kebutuhan pasien atau konsultasi spesialistik dan tindakan, serta penunjang diagnostik. Jika pasien dirujuk ke rumah sakit lain, yang merujuk harus memastikan fasilitas kesehatan penerima menyediakan pelayanan yang dapat memenuhi kebutuhan pasien dan mempunyai kapasitas menerima pasien. Diperoleh kepastian terlebih dahulu dan kesediaan menerima pasien serta persyaratan rujukan diuraikan dalam kerja sama formal atau dalam bentuk perjanjian. Ketentuan seperti ini dapat memastikan kesinambungan asuhan tercapai dan kebutuhan pasien terpenuhi. Rujukan terjadi juga ke fasilitas kesehatan lain dengan atau tanpa ada perjanjian formal.', 52, 'Rumah sakit yang merujuk memastikan bahwa fasilitas dengan rumah sakit kesehatan yang menerima tujuan rujukan dapat memenuhi kebutuhan 2. Formulir rujukan yang pasien yang dirujuk. terisi lengkap termasuk nama petugas yang berkomunikasi pada RS rujukan', '1. Bukti komunikasi Pengelola rujukan', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.5.4.d', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 5.4', 'Pasien dirujuk ke fasilitas pelayanan kesehatan lain berdasar atas kondisi pasien untuk memenuhi kebutuhan asuhan berkesinambungan dan sesuai dengan kemampuan fasilitas kesehatan penerima untuk memenuhi kebutuhan pasien.', 'Pasien dirujuk ke fasilitas kesehatan lain didasarkan atas kondisi pasien dan kebutuhan untuk memperoleh asuhan berkesinambungan. Rujukan pasien antara lain untuk memenuhi kebutuhan pasien atau konsultasi spesialistik dan tindakan, serta penunjang diagnostik. Jika pasien dirujuk ke rumah sakit lain, yang merujuk harus memastikan fasilitas kesehatan penerima menyediakan pelayanan yang dapat memenuhi kebutuhan pasien dan mempunyai kapasitas menerima pasien. Diperoleh kepastian terlebih dahulu dan kesediaan menerima pasien serta persyaratan rujukan diuraikan dalam kerja sama formal atau dalam bentuk perjanjian. Ketentuan seperti ini dapat memastikan kesinambungan asuhan tercapai dan kebutuhan pasien terpenuhi. Rujukan terjadi juga ke fasilitas kesehatan lain dengan atau tanpa ada perjanjian formal.', 53, 'Ada kerjasama rumah sakit yang merujuk dengan rumah rumah sakit yang sakit yang menerima rujukan merujuk dengan rumah yang sering dirujuk. sakit penerima rujukan yang sering dirujuk 2. Daftar RS yang sering menerima rujukan', '1. Perjanjian kerjasama', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('AKP.5.5.a', 'AKP', 11, 'Akses dan Kontinuitas Pelayanan', 1, 'AKP 5.5', 'Rumah sakit menetapkan proses rujukan untuk memastikan pasien pindah dengan aman.', 'Rujukan pasien sesuai dengan kondisi pasien, menentukan kualifikasi staf pendamping yang memonitor dan menentukan jenis peralatan medis khusus. Selain itu, harus dipastikan fasilitas pelayanan kesehatan penerima menyediakan pelayanan yang dapat memenuhi kebutuhan pasien dan mempunyai kapasitas pasien dan jenis teknologi medis. Diperlukan proses konsisten melakukan rujukan pasien untuk memastikan keselamatan pasien. Proses ini menangani: a) Ada staf yang bertanggung jawab dalam pengelolaan rujukan termasuk untuk memastikan pasien diterima di rumah sakit rujukan yang dapat memenuhi kebutuhan pasien; b) Selama dalam proses rujukan ada staf yang kompeten sesuai dengan kondisi pasien yang selalu memonitor dan mencatatnya dalam rekam medis; c) Dilakukan identifikasi kebutuhan obat, bahan medis habis pakai, alat kesehatan dan peralatan medis yang dibutuhkan selama proses rujukan; dan d) Dalam proses pelaksanaan rujukan, ada proses serah terima pasien antara staf pengantar dan yang menerima. Rumah sakit melakukan evaluasi terhadap mutu dan keamanan proses rujukan untuk memastikan pasien telah ditransfer dengan staf yang kompeten dan dengan peralatan medis yang tepat.', 54, 'Rumah sakit memiliki staf yang bertanggung jawab bertanggung jawab dalam pengelolaan rujukan melakukan pengelolaan termasuk untuk memastikan rujukan, yang disertai uraian pasien diterima di rumah tugas dan tanggung jawab sakit rujukan yang dapat memenuhi kebutuhan pasien.', 'Penetapan staf yang', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
