INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('HPK.1.3.d', 'HPK', 12, 'Hak Pasien dan Keluarga', 1, 'HPK 1.3', 'Rumah sakit menjaga privasi pasien dan kerahasiaan informasi dalam perawatan, serta memberikan hak kepada pasien untuk memperoleh akses dalam informasi kesehatan mereka sesuai perundang-undangan yang berlaku.', 'Hak privasi pasien, terutama ketika diwawancara, diperiksa, dirawat dan dipindahkan adalah hal yang sangat penting. Pasien mungkin menginginkan privasinya terlindung dari para karyawan, pasien lain, dan bahkan dari anggota keluarga atau orang lain yang ditentukan oleh pasien. Oleh karena itu staf rumah sakit yang melayani dan merawat pasien harus menanyakan tentang kebutuhan privasi pasien dan harapan yang terkait dengan pelayanan yang dimaksud serta meminta persetujuan terhadap pelepasan informasi medik yang diperlukan. Informasi medis serta informasi kesehatan lainnya yang didokumentasikan dan dikumpulkan harus dijaga kerahasiannya. Rumah sakit menghargai kerahasiaan informasi tersebut dan menerapkan prosedur yang melindungi informasi tersebut dari kehilangan atau penyalahgunaan. Kebijakan dan prosedur mencakup informasi yang dapat diberikan sesuai ketentuan peraturan dan undang-undang lainnya. Pasien juga memiliki hak untuk mengakses informasi kesehatan mereka sendiri. Ketika mereka memiliki akses terhadap informasi kesehatan mereka, pasien dapat lebih terlibat di dalam keputusan perawatan dan membuat keputusan yang lebih baik tentang perawatan mereka.', 14, 'Rumah sakit memiliki proses untuk memberikan pasien memiliki proses untuk akses terhadap informasi memberikan pasien akses kesehatan mereka. terhadap informasi kesehatan mereka. (Lihat MRMIK 10, KE 4) Admisi Pasien/ Keluarga', 'Bukti rumah sakit telah PPA', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('HPK.1.4.a', 'HPK', 12, 'Hak Pasien dan Keluarga', 1, 'HPK 1.4', 'Rumah sakit melindungi harta benda pasien dari pencurian atau kehilangan', 'Rumah sakit bertanggung jawab melindungi terhadap harta benda pasien dari pencurian atau kehilangan. Terdapat proses untuk mencatat dan membuat daftar harta benda yang dibawa pasien dan memastikan agar harta benda tersebut tidak dicuri atau hilang. Proses ini dilakukan di ODC (Pelayanan Satu Hari), pasien rawat inap dengan menyediakan nakas/lemari kecil tempat penyimpanan barang pasien, serta untuk pasien yang tidak mampu mengambil keputusan untuk menjaga keamanan harta benda mereka karena tidak sadarkan diri atau tidak didampingi penunggu.', 15, 'Rumah sakit menetapkan proses untuk mencatat dan mencatat dan melindungi melindungi pertanggungjawaban harta pertanggungjawaban harta benda pasien benda pasien.', 'Penetapan proses untuk', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
