INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('HPK.1.5.a', 'HPK', 12, 'Hak Pasien dan Keluarga', 1, 'HPK 1.5', 'Rumah sakit melindungi pasien dari serangan fisik dan verbal, dan populasi yang berisiko diidentifikasi serta dilindungi dari kerentanan.', 'Rumah sakit bertanggung jawab untuk melindungi pasien dari penganiayaan fisik dan verbal yang dilakukan pengunjung, pasien lain, dan petugas. Tanggung jawab ini sangat penting terutama bagi bayi dan anak-anak, lansia, dan kelompok yang tidak mampu melindungi dirinya sendiri. Rumah sakit berupaya mencegah penganiayaan melalui berbagai proses seperti memeriksa orang-orang yang berada dilokasi tanpa identifikasi yang jelas, memantau wilayah yang terpencil atau terisolasi, dan cepat tanggap dalam membantu mereka yang berada dalam bahaya atau dianiaya.', 17, 'Rumah sakit mengembangkan dan menerapkan proses untuk perlindungan semua pasien melindungi semua pasien dari dari serangan fisik dan verbal. serangan fisik dan verbal. tersebut. inap PPA, Admisi Pasien/ Keluarga', 'Penetapan proses Bukti perlaksanaan proses Perlindungan pasien di rawat Pimpinan RS', 'D,O,R,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
