INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('HPK.1.5.c', 'HPK', 12, 'Hak Pasien dan Keluarga', 1, 'HPK 1.5', 'Rumah sakit melindungi pasien dari serangan fisik dan verbal, dan populasi yang berisiko diidentifikasi serta dilindungi dari kerentanan.', 'Rumah sakit bertanggung jawab untuk melindungi pasien dari penganiayaan fisik dan verbal yang dilakukan pengunjung, pasien lain, dan petugas. Tanggung jawab ini sangat penting terutama bagi bayi dan anak-anak, lansia, dan kelompok yang tidak mampu melindungi dirinya sendiri. Rumah sakit berupaya mencegah penganiayaan melalui berbagai proses seperti memeriksa orang-orang yang berada dilokasi tanpa identifikasi yang jelas, memantau wilayah yang terpencil atau terisolasi, dan cepat tanggap dalam membantu mereka yang berada dalam bahaya atau dianiaya.', 19, 'Rumah sakit memantau area fasilitas yang terisolasi dan area fasilitas yang terisolasi terpencil. dan terpencil. dan terpencil CCTV PPA Staf Keamanan Pasien / Keluarga', 'Bukti proses pemantauan Area fasilitas yang terisolasi Pimpinan RS', 'D,O,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('HPK.2.a', 'HPK', 12, 'Hak Pasien dan Keluarga', 1, 'HPK 2', 'Pasien dan keluarga pasien dilibatkan dalam semua aspek perawatan dan tata laksana medis melalui edukasi, dan diberikan kesempatan untuk berpartisipasi dalam proses', 'Pasien dan keluarganya ikut berperan serta dalam proses asuhan dengan membuat keputusan mengenai perawatan, mengajukan pertanyaan tentang perawatan, dan bahkan menolak prosedur diagnostik dan tata laksana. Agar pasien dan keluarga dapat berpartisipasi dalam keputusan perawatan, mereka memerlukan informasi mengenai kondisi medis, hasil pemeriksaan, diagnosis, rencana pengobatan dan rencana tindakan serta perawatan, dan alternatif tindakan bila ada. Rumah sakit memastikan mereka dapat berpartisipasi dalam pengambilan keputusan terkait perawatan termasuk untuk melakukan perawatan sendiri di rumah. Selama proses asuhan, pasien juga memiliki hak untuk diberitahu mengenai kemungkinan hasil yang tidak dapat diantisipasi dari terapi dan perawatan, serta ketika suatu peristiwa atau kejadian yang tidak terduga terjadi selama perawatan dilakukan Pasien dan keluarga pasien memahami jenis keputusan yang harus diambil terkait asuhan dan bagaimana mereka berpartisipasi dalam pengambilan keputusan tersebut. Ketika pasien meminta pendapat kedua, rumah sakit tidak boleh menghambat, mencegah ataupun menghalangi upaya pasien yang mencari pendapat kedua, namun sebaliknya, rumah sakit harus memfasilitasi permintaan akan pendapat kedua tersebut dan membantu menyediakan informasi mengenai kondisi pasien, seperti informasi hasil pemeriksaan, diagnosis, rekomendasi terapi, dan sebagainya. Rumah sakit mendukung dan menganjurkan keterlibatan pasien dan keluarga dalam semua aspek perawatan. Seluruh staf diajarkan mengenai kebijakan dan prosedur serta peranan mereka dalam mendukung hak pasien dan keluarga untuk berpartisipasi dalam proses perawatan.', 20, 'Rumah sakit menerapkan proses untuk mendukung untuk mendukung pasien pasien dan keluarga terlibat dan keluarga terlibat dan dan berpartisipasi dalam berpartisipasi dalam proses asuhan dan dalam proses perawatan dan pengambilan keputusan. dalam pengambilan keputusan (Lihat KE 4) Pasien/ Keluarga', 'Bukti penerapan proses PPA', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
