INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('HPK.4.a', 'HPK', 12, 'Hak Pasien dan Keluarga', 1, 'HPK 4', 'Rumah sakit menetapkan batasan yang jelas untuk persetujuan umum yang diperoleh pasien pada saat akan menjalani rawat inap atau didaftarkan pertama kalinya sebagai pasien rawat jalan.', 'Rumah sakit meminta persetujuan umum untuk pengobatan ketika pasien di terima rawat inap di rumah sakit atau ketika pasien didaftarkan untuk pertama kalinya sebagai pasien rawat jalan. Pada saat persetujuan umum itu diperoleh, pasien telah diberi informasi mengenai lingkup persetujuan umum tersebut. Selanjutnya, rumah sakit menentukan bagaimana persetujuan umum didokumentasikan dalam rekam medis pasien. Selain general consent (persetujuan umum), semua pasien diberikan informasi mengenai pemeriksaan, tindakan dan pengobatan di mana informed consent (persetujuan tindakan) terpisah akan dibuat. Selain itu, pasien juga harus menerima informasi mengenai kemungkinan adanya peserta didik, seperti peserta didik perawat, peserta didik fisioterapi, mahasiswa kedokteran, dokter yang sedang menjalani pendidikan spesialis/trainee/fellowship, serta peserta didik lainnyayang terlibat dalam proses asuhan.', 32, 'Rumah sakit menerapkan proses bagaimana persetujuan persetujuan umum. umum didokumentasikan dalam rekam medis pasien. persetujuan umum di rekam medis. persetujuan umum. Pasien/ keluarga', 'Penetapan proses Bukti penerapan proses Proses pemberian Staf admisi', 'D,O,R,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
