INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('HPK.4.c', 'HPK', 12, 'Hak Pasien dan Keluarga', 1, 'HPK 4', 'Rumah sakit menetapkan batasan yang jelas untuk persetujuan umum yang diperoleh pasien pada saat akan menjalani rawat inap atau didaftarkan pertama kalinya sebagai pasien rawat jalan.', 'Rumah sakit meminta persetujuan umum untuk pengobatan ketika pasien di terima rawat inap di rumah sakit atau ketika pasien didaftarkan untuk pertama kalinya sebagai pasien rawat jalan. Pada saat persetujuan umum itu diperoleh, pasien telah diberi informasi mengenai lingkup persetujuan umum tersebut. Selanjutnya, rumah sakit menentukan bagaimana persetujuan umum didokumentasikan dalam rekam medis pasien. Selain general consent (persetujuan umum), semua pasien diberikan informasi mengenai pemeriksaan, tindakan dan pengobatan di mana informed consent (persetujuan tindakan) terpisah akan dibuat. Selain itu, pasien juga harus menerima informasi mengenai kemungkinan adanya peserta didik, seperti peserta didik perawat, peserta didik fisioterapi, mahasiswa kedokteran, dokter yang sedang menjalani pendidikan spesialis/trainee/fellowship, serta peserta didik lainnyayang terlibat dalam proses asuhan.', 34, 'Pasien menerima informasi mengenai kemungkinan mengenai kemungkinan keterlibatan peserta didik, keterlibatan peserta didik, mahasiswa, residen traine dan mahasiswa, residen traine TDD fellow yang berpartisipasi dan fellow yang dalam proses perawatan berpartisipasi dalam proses perawatan yang tercatat pada general consent PPA Pasien/ Keluarga', 'Bukti pemberian informasi Petugas admisi', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('HPK.4.1.a', 'HPK', 12, 'Hak Pasien dan Keluarga', 1, 'HPK 4.1', 'Persetujuan tindakan (informed consent) pasien diperoleh melalui cara yang telah ditetapkan rumah sakit dan dilaksanakan oleh petugas terlatih dengan cara dan bahasa yang mudah dipahami pasien.', 'Salah satu proses penting di mana pasien dapat terlibat dalam pengambilan keputusan tentang perawatan mereka adalah dengan memberikan informed consent. Untuk memberikan persetujuan ini, pasien harus di informasikan terlebih dahulu mengenai faktor-faktor yang terkait dengan rencana perawatan yang dibutuhkan untuk mengambil keputusan. Proses persetujuan harus didefinisikan secara jelas oleh rumah sakit dalam kebijakan dan prosedur sesuai perundang-udangan yang berlaku. Pasien dan keluarga diberikan informasi mengenai pemeriksaan, tindakan, dan pengobatan mana yang memerlukan persetujuan dan bagaimana mereka dapat memberikan persetujuan. Edukasi diberikan oleh staf rumah sakit yang kompeten dan merupakan bagian dari proses untuk mendapatkan informed consent (sebagai contoh, untuk pembedahan dan anestesi). Jika perawatan yang direncanakan meliputi prosedur pembedahan atau tindakan invasif, anestesi, sedasi, penggunaan darah dan produk darah, perawatan atau tindakan berisiko tinggi, maka diperlukan persetujuan tindakan secara terpisah. Rumah sakit mengidentifikasi.', 35, 'Rumah sakit menerapkan proses bagi pasien untuk pemberian informed consent. mendapatkan informed consent. Pasien/ Keluarga', 'Bukti rekam medis: DPJP', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
