Y UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('HPK.4.1.c', 'HPK', 12, 'Hak Pasien dan Keluarga', 1, 'HPK 4.1', 'Persetujuan tindakan (informed consent) pasien diperoleh melalui cara yang telah ditetapkan rumah sakit dan dilaksanakan oleh petugas terlatih dengan cara dan bahasa yang mudah dipahami pasien.', 'Salah satu proses penting di mana pasien dapat terlibat dalam pengambilan keputusan tentang perawatan mereka adalah dengan memberikan informed consent. Untuk memberikan persetujuan ini, pasien harus di informasikan terlebih dahulu mengenai faktor-faktor yang terkait dengan rencana perawatan yang dibutuhkan untuk mengambil keputusan. Proses persetujuan harus didefinisikan secara jelas oleh rumah sakit dalam kebijakan dan prosedur sesuai perundang-udangan yang berlaku. Pasien dan keluarga diberikan informasi mengenai pemeriksaan, tindakan, dan pengobatan mana yang memerlukan persetujuan dan bagaimana mereka dapat memberikan persetujuan. Edukasi diberikan oleh staf rumah sakit yang kompeten dan merupakan bagian dari proses untuk mendapatkan informed consent (sebagai contoh, untuk pembedahan dan anestesi). Jika perawatan yang direncanakan meliputi prosedur pembedahan atau tindakan invasif, anestesi, sedasi, penggunaan darah dan produk darah, perawatan atau tindakan berisiko tinggi, maka diperlukan persetujuan tindakan secara terpisah. Rumah sakit mengidentifikasi.', 37, 'Rumah sakit memiliki daftar tindakan invasif, invasif, pemeriksaan dan pemeriksaan dan terapi terapi tambahan yang tambahan yang memerlukan memerlukan informed consent informed consent.', 'Penetapan daftar tindakan', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('HPK.4.2.a', 'HPK', 12, 'Hak Pasien dan Keluarga', 1, 'HPK 4.2', 'Rumah sakit menerapkan proses untuk pemberian persetujuan oleh orang lain, sesuai dengan peraturan perundangan yang berlaku.', 'Ada kalanya terdapat kondisi dimana orang lain selain pasien (baik sendiri maupun bersama pasien) ikut terlibat dalam keputusan mengenai perawatan pasien dalam proses pemberian informed consent untuk perawatan. Hal ini terutama berlaku ketika pasien tidak memiliki kemampuan mental atau fisik untuk mengambil keputusan tentang perawatannya sendiri, ketika latar belakang budaya atau kebiasaan mengharuskan orang lain yang mengambil keputusan tentang perawatan atau ketika pasien masih kanak-kanak. Ketika pasien tidak dapat membuat keputusan tentang perawatannya, maka ditentukan perwakilan untuk mengambil keputusan tersebut. Ketika ada orang lain selain pasien itu yang memberi persetujuan, nama individu itu dicatat dalam rekam medis pasien.', 38, 'Rumah sakit menerapkan proses untuk pemberian informed consent oleh orang informed consent oleh orang lain selain pasien sesuai lain selain pasien sesuai peraturan perundang- peraturan perundangan yang undangan. berlaku. PPA Pasien/ Keluarga', 'Bukti rekam medis pemberian DPJP', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('HPK.4.2.b', 'HPK', 12, 'Hak Pasien dan Keluarga', 1, 'HPK 4.2', 'Rumah sakit menerapkan proses untuk pemberian persetujuan oleh orang lain, sesuai dengan peraturan perundangan yang berlaku.', 'Ada kalanya terdapat kondisi dimana orang lain selain pasien (baik sendiri maupun bersama pasien) ikut terlibat dalam keputusan mengenai perawatan pasien dalam proses pemberian informed consent untuk perawatan. Hal ini terutama berlaku ketika pasien tidak memiliki kemampuan mental atau fisik untuk mengambil keputusan tentang perawatannya sendiri, ketika latar belakang budaya atau kebiasaan mengharuskan orang lain yang mengambil keputusan tentang perawatan atau ketika pasien masih kanak-kanak. Ketika pasien tidak dapat membuat keputusan tentang perawatannya, maka ditentukan perwakilan untuk mengambil keputusan tersebut. Ketika ada orang lain selain pasien itu yang memberi persetujuan, nama individu itu dicatat dalam rekam medis pasien.', 39, 'Rekam medis pasien mencantumkan (satu atau mencantumkan (satu atau lebih) nama individu yang lebih) nama orang yang menyatakan persetujuan. menggantikan pemberian persetujuan (selain pasien) sesuai peraturan perundangan yang berlaku. Pasien/ Keluarga', 'Bukti dalam rekam medis PPA', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.1.a', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 1', 'Semua pasien yang dirawat di rumah sakit diidentifikasi kebutuhan perawatan kesehatannya melalui suatu proses pengkajian yang telah ditetapkan oleh rumah sakit.', '', 1, 'Rumah sakit menetapkan regulasi tentang pengkajian awal dan pengkajian ulang awal dan pengkajian ulang medis dan keperawatan di unit medis dan keperawatan di gawat darurat, rawat inap dan unit gawat darurat, rawat rawat jalan. inap dan rawat jalan.', 'Regulasi tentang pengkajian', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
