INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.1.d', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 1', 'Semua pasien yang dirawat di rumah sakit diidentifikasi kebutuhan perawatan kesehatannya melalui suatu proses pengkajian yang telah ditetapkan oleh rumah sakit.', '', 4, 'Perencanaan pulang yang mencakup identifikasi awal mencakup perencanaan kebutuhan khusus dan pulang pasien yang rencana untuk memenuhi memerlukan kebutuhan khusus kebutuhan tersebut, dan rencana memenuhi disusun sejak pengkajian kebutuhan khusus tersebut. awal.', 'Bukti Rekam Medis pengkajian', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
