INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.1.1.c', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 1.1', 'Kebutuhan medis dan keperawatan pasien diidentifikasi berdasarkan pengkajian awal.', '', 7, 'Pengkajian awal keperawatan menghasilkan diagnosis awal keperawatan yang keperawatan untuk menghasilkan diagnosis menentukan kebutuhan keperawatan untuk asuhan keperawatan, menentukan kebutuhan intervensi atau pemantauan asuhan keperawatan, pasien yang spesifik. intervensi atau pemantauan pasien yang spesifik.', 'Bukti Rekam Medis pengkajian', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.1.1.d', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 1.1', 'Kebutuhan medis dan keperawatan pasien diidentifikasi berdasarkan pengkajian awal.', '', 8, 'Sebelum pembedahan pada kondisi mendesak, minimal awal yang memuat catatan terdapat catatan singkat dan singkat dan diagnosis diagnosis praoperasi yang praoperasi sebelum didokumentasikan di dalam pembedahan pada kondisi rekam medik. mendesak.', 'Bukti Rekam Medis pengkajian', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.1.1.e', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 1.1', 'Kebutuhan medis dan keperawatan pasien diidentifikasi berdasarkan pengkajian awal.', '', 9, 'Pengkajian medis yang dilakukan sebelum masuk awal pasien yang memuat rawat inap atau sebelum sebelum masuk rawat inap pasien menjalani prosedur di atau sebelum menjalani layanan rawat jalan rumah prosedur di layanan rawat sakit harus dilakukan dalam jalan dalam waktu kurang atau waktu kurang atau sama sama dengan 30 (tiga puluh) dengan 30 (tiga puluh) hari hari sebelumnya. Jika lebih sebelumnya. Jika lebih dari 30 dari 30 (tiga puluh) hari, maka (tiga puluh) hari, maka harus harus dilakukan pengkajian dilakukan pengkajian ulang. ulang.', 'Bukti Rekam Medis pengkajian', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.1.1.a', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 1.1', 'Kebutuhan medis dan keperawatan pasien diidentifikasi berdasarkan pengkajian awal.', '', 10, 'Hasil dari seluruh pengkajian yang dikerjakan di luar rumah dikerjakan di luar rumah sakit sakit ditinjau dan/atau telah ditinjau dan/atau diverifikasi pada saat masuk diverifikasi pada saat masuk rawat inap atau sebelum rawat inap atau sebelum tindakan di unit rawat jalan. tindakan di unit rawat jalan.', 'Bukti pengkajian yang', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.1.2.a', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 1.2', 'Pasien dilakukan skrining risiko nutrisi, skrining nyeri, kebutuhan fungsional termasuk risiko jatuh dan kebutuhan khusus lainnya', 'Proses pengkajian pasien yang efektif menghasilkan keputusan tentang kebutuhan pasien untuk mendapatkan tata laksana segera dan berkesinambungan untuk pelayanan gawat darurat, elektif atau terencana, bahkan ketika kondisi pasien mengalami perubahan. Pengkajian pasien adalah sebuah proses berkesinambungan dan dinamis yang dilakukan di unit gawat darurat, rawat inap dan rawat jalan serta unit lainnya. Pengkajian pasien terdiri dari tiga proses primer: a) Pengumpulan informasi dan data mengenai kondisi fisik, psikologis, dan status sosial serta riwayat kesehatan pasien sebelumnya b) Analisis data dan informasi, termasuk hasil pemeriksaan laboratorium dan uji diagnostik pencitraan, untuk mengidentifikasi kebutuhan perawatan pasien. c) Pengembangan rencana perawatan pasien untuk memenuhi kebutuhan yang telah diidentifikasi. Pengkajian disesuaikan dengan kebutuhan pasien, sebagai contoh, rawat inap atau rawat jalan. Bagaimana pengkajian ini dilakukan dan informasi apa yang perlu dikumpulkan serta didokumentasikan ditetapkan dalam kebijakan dan prosedur rumah sakit. Isi minimal pengkajian awal antara lain: a) Keluhan saat ini b) Status fisik; c) Psiko-sosio-spiritual; d) Ekonomi; e) Riwayat kesehatan pasien; f) Riwayat alergi; g) Riwayat penggunaan obat; h) Pengkajian nyeri; i) Risiko jatuh; j) Pengkajian fungsional; k) Risiko nutritional; l) Kebutuhan edukasi; dan m) Perencanaan pemulangan pasien (Discharge Planning). Pada kelompok pasien tertentu, misalnya dengan risiko jatuh, nyeri dan status nutrisi maka dilakukan skrining sebagai bagian dari pengkajian awal, kemudian dilanjutkan dengan pengkajian lanjutan. Agar pengkajian kebutuhan pasien dilakukan secara konsisten, rumah sakit harus mendefinisikan dalam kebijakan, isi minimum dari pengkajian yang dilakukan oleh para dokter, perawat, dan disiplin klinis lainnya. Pengkajian dilakukan oleh setiap disiplin dalam ruang lingkup praktiknya, perizinan, perundang undangan. Hanya PPA yang kompeten dan diizinkan oleh rumah sakit yang akan melakukan pengkajian. Rumah sakit mendefinisikan elemen-elemen yang akan digunakan pada seluruh pengkajian dan mendefinisikan perbedaan-perbedaan yang ada terutama dalam ruang lingkup kedokteran umum dan layanan spesialis. Pengkajian yang didefinisikan dalam kebijakan dapat dilengkapi oleh lebih dari satu individu yang kompeten dan dilakukan pada beberapa waktu yang berbeda. Semua pengkajian tersebut harus sudah terisi lengkap dan memiliki informasi terkini (kurang dari atau sama dengan 30 (tiga puluh) hari) pada saat tatalaksana dimulai.', 11, 'Rumah sakit menetapkan kriteria risiko nutrisional yang nutrisional. dikembangkan bersama staf kompeten dan berwenang (staf yang kompeten dan gizi) dalam pembuatan kriteria berwenang. risiko nutrisional.', 'Regulasi tentang kriteria risiko Bukti keterlibatan staf yang', 'D,R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
