INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.2.d', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 2', '', '', 21, 'Terdapat bukti pengkajian ulang oleh PPA lainnya ulang oleh PPA lainnya yang dilaksanakan dengan interval dilaksanakan dengan interval sesuai regulasi rumah sakit. sesuai regulasi rumah sakit. c. Pelayanan Laboratorium dan Pelayanan Darah', 'Bukti Rekam Medis pengkajian', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.3.a', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 3', 'Pelayanan laboratorium tersedia untuk memenuhi kebutuhan pasien sesuai peraturan perundangan.', 'Rumah Sakit mempunyai sistem untuk menyediakan pelayanan laboratorium, meliputi pelayanan patologi klinis, dapat juga tersedia patologi anatomi dan pelayanan laboratorium lainnya, yang dibutuhkan populasi pasiennya, dan PPA. Organisasi pelayanan laboratorium yang di bentuk dan diselenggarakan sesuai peraturan perundangan Di Rumah Sakit dapat terbentuk pelayanan laboratorium utama (induk), dan juga pelayanan laboratorium lain, misalnya laboratorium Patologi Anatomi, laboratorium Mikrobiologi maka harus diatur secara organisatoris pelayanan laboratorium terintegrasi, dengan pengaturan tentang kepala pelayanan laboratorium terintegrasi yang membawahi semua jenis pelayanan laboratorium di Rumah Sakit. Salah satu pelayanan laboratorium di ruang rawat (Point of Care Testing) yang dilakukan oleh perawat ruangan harus memenuhi persyaratan kredensial. Pelayanan laboratorium, tersedia 24 jam termasuk pelayanan darurat, diberikan di dalam rumah sakit dan rujukan sesuai dengan peraturan perundangan. Rumah sakit dapat juga menunjuk dan menghubungi para spesialis di bidang diagnostik khusus, seperti parasitologi, virologi, atau toksikologi. Jika diperlukan, rumah sakit dapat melakukan pemeriksaan rujukan dengan memilih sumber dari luar berdasarkan rekomendasi dari pimpinan laboratorium rumah sakit. Sumber dari luar tersebut dipilih oleh Rumah Sakit karena memenuhi peraturan perundangan dan mempunyai sertifikat mutu. Bila melakukan pemeriksaan rujukan keluar, harus melalui laboratorium Rumah Sakit.', 22, 'Rumah sakit menetapkan regulasi tentang pelayanan Pelayanan Laboratorium di laboratorium di rumah sakit. Rumah Sakit', 'Regulasi tentang Pedoman', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.3.b', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 3', 'Pelayanan laboratorium tersedia untuk memenuhi kebutuhan pasien sesuai peraturan perundangan.', 'Rumah Sakit mempunyai sistem untuk menyediakan pelayanan laboratorium, meliputi pelayanan patologi klinis, dapat juga tersedia patologi anatomi dan pelayanan laboratorium lainnya, yang dibutuhkan populasi pasiennya, dan PPA. Organisasi pelayanan laboratorium yang di bentuk dan diselenggarakan sesuai peraturan perundangan Di Rumah Sakit dapat terbentuk pelayanan laboratorium utama (induk), dan juga pelayanan laboratorium lain, misalnya laboratorium Patologi Anatomi, laboratorium Mikrobiologi maka harus diatur secara organisatoris pelayanan laboratorium terintegrasi, dengan pengaturan tentang kepala pelayanan laboratorium terintegrasi yang membawahi semua jenis pelayanan laboratorium di Rumah Sakit. Salah satu pelayanan laboratorium di ruang rawat (Point of Care Testing) yang dilakukan oleh perawat ruangan harus memenuhi persyaratan kredensial. Pelayanan laboratorium, tersedia 24 jam termasuk pelayanan darurat, diberikan di dalam rumah sakit dan rujukan sesuai dengan peraturan perundangan. Rumah sakit dapat juga menunjuk dan menghubungi para spesialis di bidang diagnostik khusus, seperti parasitologi, virologi, atau toksikologi. Jika diperlukan, rumah sakit dapat melakukan pemeriksaan rujukan dengan memilih sumber dari luar berdasarkan rekomendasi dari pimpinan laboratorium rumah sakit. Sumber dari luar tersebut dipilih oleh Rumah Sakit karena memenuhi peraturan perundangan dan mempunyai sertifikat mutu. Bila melakukan pemeriksaan rujukan keluar, harus melalui laboratorium Rumah Sakit.', 23, 'Pelayanan laboratorium buka 24 jam, 7 (tujuh) hari laboratorium buka 24 jam, 7 seminggu, sesuai dengan (tujuh) hari seminggu sesuai kebutuhan pasien. dengan kebutuhan pasien. laboratorium 24 jam, 7 (tujuh) hari seminggu sesuai dengan kebutuhan pasien. 2. Bukti jadwal staf laboratorium yang bertugas selama 24 jam, 7 (tujuh) hari seminggu.', 'Regulasi tentang pelayanan 1. Bukti hasil pemeriksaan', 'D,R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.3.1.a', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 3.1', 'Rumah sakit menetapkan bahwa seorang yang kompeten dan berwenang, bertanggung jawab mengelola pelayanan laboratorium.', 'Pelayanan laboratorium berada dibawah pimpinan seorang yang kompeten dan memenuhi persyaratan peraturan - perundang-undangan. Pimpinan laboratorium bertanggung jawab mengelola fasilitas dan pelayanan laboratorium, termasuk pemeriksaan Point-of-care testing (POCT), juga tanggung jawabnya dalam melaksanakan regulasi RS secara konsisten, seperti pelatihan, manajemen logistik dan sebagainya. Tanggung jawab pimpinan laboratorium antara lain: a) Menyusun dan evaluasi regulasi. b) Pengawasan pelaksanaan administrasi. c) Melaksanakan program kendali mutu (PMI dan PME) dan mengintegrasikan program mutu laboratorium dengan program Manajemen Fasilitas dan Keamanan serta program Pencegahan dan Pengendalian Infeksi di rumah sakit. d) Melakukan pemantauan dan evaluasi semua jenis pelayanan laboratorium. e) Mereview dan menindaklanjuti hasil pemeriksaan laboratorium rujukan.', 24, 'Direktur rumah sakit menetapkan penanggung jawab laboratorium yang jawab laboratorium yang memiliki kompetensi sesuai memiliki kompetensi sesuai ketentuan perundang- ketentuan perundang- undangan, yang disertai uraian undangan. tugas dan wewenang penanggung jawab laboratorium.', 'Regulasi tentang penanggung Bukti SIP, SPK dan RKK', 'D,R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.3.1.b', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 3.1', 'Rumah sakit menetapkan bahwa seorang yang kompeten dan berwenang, bertanggung jawab mengelola pelayanan laboratorium.', 'Pelayanan laboratorium berada dibawah pimpinan seorang yang kompeten dan memenuhi persyaratan peraturan - perundang-undangan. Pimpinan laboratorium bertanggung jawab mengelola fasilitas dan pelayanan laboratorium, termasuk pemeriksaan Point-of-care testing (POCT), juga tanggung jawabnya dalam melaksanakan regulasi RS secara konsisten, seperti pelatihan, manajemen logistik dan sebagainya. Tanggung jawab pimpinan laboratorium antara lain: a) Menyusun dan evaluasi regulasi. b) Pengawasan pelaksanaan administrasi. c) Melaksanakan program kendali mutu (PMI dan PME) dan mengintegrasikan program mutu laboratorium dengan program Manajemen Fasilitas dan Keamanan serta program Pencegahan dan Pengendalian Infeksi di rumah sakit. d) Melakukan pemantauan dan evaluasi semua jenis pelayanan laboratorium. e) Mereview dan menindaklanjuti hasil pemeriksaan laboratorium rujukan.', 25, 'Terdapat bukti pelaksanaan tanggung jawab pimpinan jawab pimpinan laboratorium laboratorium sesuai poin a) e) sesuai poin a) e) pada pada maksud dan tujuan. maksud dan tujuan.', 'Bukti pelaksanaan tanggung', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
