INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.3.4.a', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 3.4', 'Rumah sakit memiliki prosedur pengelolaan semua reagensia esensial dan di evaluasi secara berkala pelaksaksanaannya.', 'Rumah sakit menetapkan reagensia dan bahan-bahan lain yang selalu harus ada untuk pelayanan laboratorium bagi pasien. Suatu proses yang efektif untuk pemesanan atau menjamin ketersediaan reagensia esensial dan bahan lain yang diperlukan. Semua reagensia disimpan dan didistribusikan sesuai prosedur yang ditetapkan. Dilakukan audit secara periodik untuk semua reagensia esensial untuk memastikan akurasi dan presisi hasil pemeriksaan, antara lain untuk aspek penyimpanan, label, kadaluarsa dan fisik. Prosedur tertulis memastikan pemberian label secara lengkap dan akurat untuk reagensia dan larutan dan akurasi serta presisi dari hasil. Rumah sakit memiliki prosedur pengelolaan semua reagensia esensial dan di evaluasi secara berkala pelaksaksanaannya.', 32, 'Terdapat bukti pelaksanaan semua esensial disimpan dan diberi label, reagensia esensial serta di distribusi sesuai prosedur disimpan dan diberi label, dari pembuatnya atau instruksi serta didistribusi sesuai pada kemasannya prosedur dari pembuatnya atau penyimpanan pelabelan, dan instruksi pada pendistribusian reagen. kemasannya', 'Bukti pelaksanaan semua reagensia Observasi pelaksanaan', 'D,O', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=V