INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.4.a', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 4', 'Pelayanan radiologi klinik menetapkan regulasi pelayanan radiologi klinis di rumah sakit.', 'Pelayanan radiodiagnostik, imajing dan radiologi intervensional (RIR) meliputi: a) Pelayanan radiodiagnostik; b) Pelayanan diagnostik Imajing; c) Pelayanan radiologi intervensional. Rumah sakit menetapkan sistem yang terintegrasi untuk menyelenggarakan pelayanan radiodiagnostik, imajing dan radiologi intervensional yang dibutuhkan pasien, asuhan klinis dan Profesional Pemberi Asuhan (PPA). Pelayanan radiologi klinik buka 24 jam, 7 (tujuh) hari seminggu sesuai dengan kebutuhan pasien.', 46, 'Rumah Sakit menetapkan dan melaksanakan regulasi pelayanan radiologi klinik. pelayanan radiologi klinik. pelayanan radiologi klinik sesuai regulasi.', 'Regulasi tentang Pedoman Bukti tentang pelaksanaan', 'D,R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.4.b', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 4', 'Pelayanan radiologi klinik menetapkan regulasi pelayanan radiologi klinis di rumah sakit.', 'Pelayanan radiodiagnostik, imajing dan radiologi intervensional (RIR) meliputi: a) Pelayanan radiodiagnostik; b) Pelayanan diagnostik Imajing; c) Pelayanan radiologi intervensional. Rumah sakit menetapkan sistem yang terintegrasi untuk menyelenggarakan pelayanan radiodiagnostik, imajing dan radiologi intervensional yang dibutuhkan pasien, asuhan klinis dan Profesional Pemberi Asuhan (PPA). Pelayanan radiologi klinik buka 24 jam, 7 (tujuh) hari seminggu sesuai dengan kebutuhan pasien.', 47, 'Terdapat pelayanan radiologi klinik selama 24 jam, 7 (tujuh) radiologi klinik selama 24 jam, hari seminggu, sesuai dengan 7 (tujuh) hari seminggu, sesuai kebutuhan pasien. dengan kebutuhan pasien. radiologi selama 24 jam, 7 (tujuh) hari seminggu. 2. Bukti jadwal staf radiologi yang bertugas selama 24 jam, 7 (tujuh) hari seminggu.', 'Regulasi tentang pelayanan 1. Bukti hasil pemeriksaan', 'D,R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.4.1.a', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 4.1', 'Rumah Sakit menetapkan seorang yang kompeten dan berwenang, bertanggung jawab mengelola pelayanan RIR.', 'Pelayanan Radiodiagnostik, Imajing dan Radiologi Intervensional berada dibawah pimpinan seorang yang kompeten dan berwenang memenuhi persyaratan peraturan perundangan. Pimpinan radiologi klinik bertanggung jawab mengelola fasilitas dan pelayanan RIR, termasuk pemeriksaan yang dilakukan di tempat tidur pasien (POCT), juga tanggung jawabnya dalam melaksanakan regulasi RS secara konsisten, seperti pelatihan, manajemen logistik, dan sebagainya. Tanggung jawab pimpinan pelayanan radiologi diagnostik imajing, dan radiologi intervensional antara lain: a) Menyusun dan evaluasi regulasi. b) Pengawasan pelaksanaan administrasi. c) Melaksanakan program kendali mutu (PMI dan PME) dan mengintegrasikan program mutu radiologi dengan program Manajemen Fasilitas dan Keamanan serta program Pencegahan dan Pengendalian Infeksi di rumah sakit. d) Memonitor dan evaluasi semua jenis pelayanan RIR. e) Mereviu dan menindak lanjuti hasil pemeriksaan pelayanan RIR rujukan.', 48, 'Direktur menetapkankan penanggung jawab radiologi penanggung jawab radiologi klinik yang memiliki klinik sesuai ketentuan kompetensi sesuai ketentuan perundang-undangan yang dengan peraturan disertai uraian tugas dan perundang-undangan. wewenang. penanggung jawab radiologi klinik.', 'Regulasi tentang penetapan Bukti SIP, SPK dan RKK', 'D,R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.4.1.b', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 4.1', 'Rumah Sakit menetapkan seorang yang kompeten dan berwenang, bertanggung jawab mengelola pelayanan RIR.', 'Pelayanan Radiodiagnostik, Imajing dan Radiologi Intervensional berada dibawah pimpinan seorang yang kompeten dan berwenang memenuhi persyaratan peraturan perundangan. Pimpinan radiologi klinik bertanggung jawab mengelola fasilitas dan pelayanan RIR, termasuk pemeriksaan yang dilakukan di tempat tidur pasien (POCT), juga tanggung jawabnya dalam melaksanakan regulasi RS secara konsisten, seperti pelatihan, manajemen logistik, dan sebagainya. Tanggung jawab pimpinan pelayanan radiologi diagnostik imajing, dan radiologi intervensional antara lain: a) Menyusun dan evaluasi regulasi. b) Pengawasan pelaksanaan administrasi. c) Melaksanakan program kendali mutu (PMI dan PME) dan mengintegrasikan program mutu radiologi dengan program Manajemen Fasilitas dan Keamanan serta program Pencegahan dan Pengendalian Infeksi di rumah sakit. d) Memonitor dan evaluasi semua jenis pelayanan RIR. e) Mereviu dan menindak lanjuti hasil pemeriksaan pelayanan RIR rujukan.', 49, 'Terdapat bukti pengawasan pelayanan radiologi klinik jawab radiologi klinik sesuai oleh penanggung jawab poin a) – e) pada maksud dan radiologi klinik sesuai poin a) tujuan. – e) pada maksud dan tujuan.', 'Bukti pelaksanaan tanggung', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.4.2.a', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 4.2', 'Semua staf radiologi klinik mempunyai pendidikan, pelatihan, kualifikasi dan pengalaman yang dipersyaratkan untuk mengerjakan pemeriksaan.', 'Rumah sakit menetapkan mereka yang bekerja sebagai staf radiologi dan diagnostik imajing yang kompeten dan berwenang melakukan pemeriksaan radiodiagnostik, imajing dan radiologi intervensional, pembacaan diagnostik imajing, pelayanan pasien di tempat tidur (POCT), membuat interpretasi, melakukan verifikasi dan serta melaporkan hasilnya, serta mereka yang mengawasi prosesnya. Staf pengawas dan staf pelaksana teknikal mempunyai latar belakang pelatihan, pengalaman, keterampilan dan telah menjalani orientasi tugas pekerjaannya. Staf teknikal diberi tugas pekerjaan sesuai latar belakang pendidikan dan pengalaman mereka. Sebagai tambahan, jumlah staf cukup tersedia untuk melakukan tugas, membuat interpretasi, dan melaporkan segera hasilnya untuk layanan darurat.', 50, 'Staf radiologi klinik yang membuat interpretasi telah dilakukan oleh staf radiologi memenuhi persyaratan klinik yang telah memenuhi kredensial persyaratan kredensial. 2. Bukti SPK dan RKK staf radiologi klinik yang membuat interpretasi.', '1. Bukti hasil interpretasi yang', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.4.2.b', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 4.2', 'Semua staf radiologi klinik mempunyai pendidikan, pelatihan, kualifikasi dan pengalaman yang dipersyaratkan untuk mengerjakan pemeriksaan.', 'Rumah sakit menetapkan mereka yang bekerja sebagai staf radiologi dan diagnostik imajing yang kompeten dan berwenang melakukan pemeriksaan radiodiagnostik, imajing dan radiologi intervensional, pembacaan diagnostik imajing, pelayanan pasien di tempat tidur (POCT), membuat interpretasi, melakukan verifikasi dan serta melaporkan hasilnya, serta mereka yang mengawasi prosesnya. Staf pengawas dan staf pelaksana teknikal mempunyai latar belakang pelatihan, pengalaman, keterampilan dan telah menjalani orientasi tugas pekerjaannya. Staf teknikal diberi tugas pekerjaan sesuai latar belakang pendidikan dan pengalaman mereka. Sebagai tambahan, jumlah staf cukup tersedia untuk melakukan tugas, membuat interpretasi, dan melaporkan segera hasilnya untuk layanan darurat.', 51, 'Staf radiologi klinik dan staf lain yang melaksanakan radiologi klinik yang pemeriksaan termasuk yang melaksanakan pemeriksaan mengerjakan tindakan di termasuk yang mengerjakan Ruang Rawat pasien, tindakan di Ruang Rawat memenuhi persyaratan pasien kredensial.', 'Bukti SPK dan RKK staf', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.4.3.a', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 4.3', 'Rumah sakit menetapkan kerangka waktu penyelesaian pemeriksaan radiologi klinik regular dan cito.', 'Rumah sakit menetapkan kerangka waktu penyelesaian pemeriksaan radiologi dan diagnostik imajing. Penyelesaian pemeriksaan radiodiagnostik, imajing dan radiologi intervensional (RIR) dilaporkan sesuai kebutuhan pasien. Hasil pemeriksaan cito, antara lain dari unit darurat, kamar operasi, unit intensif diberi perhatian khusus terkait kecepatan hasil pemeriksaan. Jika pemeriksaan dilakukan melalui kontrak (pihak ketiga) atau radiologi rujukan, kerangka waktu melaporkan hasil pemeriksaan mengikuti ketentuan rumah sakit dan MOU dengan radiodiagnostik, imajing dan radiologi intervensional (RIR) rujukan.', 52, 'Rumah sakit menetapkan kerangka waktu penyelesaian kerangka waktu penyelesaian pemeriksaan radiologi klinik. pemeriksaan radiologi klinik regular dan cito.', 'Regulasi tentang penetapan', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
