INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PP.4.5.b', 'PP', 13, 'Pengkajian Pasien', 1, 'PP 4.5', 'Rumah sakit menetapkan program kendali mutu, dilaksanakan, divalidasi dan didokumentasikan.', 'Kendali mutu dalam pelayanan radiodiagnostik terdiri dari Pemantapan Mutu Internal dan Pemantapan Mutu Eksternal. Kedua hal tersebut dilakukan sesuai ketentuan peraturan perundangan.', 59, 'Terdapat bukti bahwa unit radiologi klinik melaksanakan Pemantapan Mutu Eksternal Pemantapan Mutu Eksternal (PME). (PME).', 'Bukti pelaksanaan', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.1.a', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 1', 'Pelayanan dan asuhan yang seragam diberikan untuk semua pasien sesuai peraturan perundang-undangan.', 'Pasien dengan masalah kesehatan dan kebutuhan pelayanan yang sama berhak mendapat mutu asuhan yang seragam di rumah sakit. Untuk melaksanakan prinsip mutu asuhan yang setingkat, pimpinan harus merencanakan dan mengkoordinasi pelayanan pasien. Secara khusus, pelayanan yang diberikan kepada populasi pasien yang sama pada berbagai unit kerja sesuai dengan regulasi yang ditetapkan rumah sakit. Sebagai tambahan, pimpinan harus menjamin bahwa rumah sakit menyediakan tingkat mutu asuhan yang sama setiap hari dalam seminggu dan pada setiap shift. Regulasi tersebut harus sesuai dengan peraturan perundangan yang berlaku sehingga proses pelayanan pasien dapat diberikan secara kolaboratif. Asuhan pasien yang seragam tercermin dalam hal-hal berikut: a) Akses untuk mendapatkan asuhan dan pengobatan tidak bergantung pada kemampuan pasien untuk membayar atau sumber pembayaran. b) Akses untuk mendapatkan asuhan dan pengobatan yang diberikan oleh PPA yang kompeten tidak bergantung pada hari atau jam yaitu 7 (tujuh) hari, 24 (dua puluh empat) jam c) Kondisi pasien menentukan sumber daya yang akan dialokasikan untuk memenuhi kebutuhannya d) Pemberian asuhan yang diberikan kepada pasien, sama di semua unit pelayanan di rumah sakit misalnya pelayanan anestesi. e) Pasien yang membutuhkan asuhan keperawatan yang sama akan menerima tingkat asuhan keperawatan yang sama di semua unit pelayanan di rumah sakit. Keseragaman dalam memberikan asuhan pada semua pasien akan menghasilkan penggunaan sumber daya yang efektif dan memungkinkan dilakukan evaluasi terhadap hasil asuhan yang sama di semua unit pelyanan di rumah sakit. 3) Elemen penilaian PAP 1', 1, 'Rumah sakit menetapkan regulasi tentang pelayanan dan asuhan pasien meliputi: dan asuhan pasien (PAP) poin a) – e) dalam gambaran yang meliputi poin a) – e) umum dalam gambaran umum.', 'Regulasi tentang pelayanan', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.1.b', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 1', 'Pelayanan dan asuhan yang seragam diberikan untuk semua pasien sesuai peraturan perundang-undangan.', 'Pasien dengan masalah kesehatan dan kebutuhan pelayanan yang sama berhak mendapat mutu asuhan yang seragam di rumah sakit. Untuk melaksanakan prinsip mutu asuhan yang setingkat, pimpinan harus merencanakan dan mengkoordinasi pelayanan pasien. Secara khusus, pelayanan yang diberikan kepada populasi pasien yang sama pada berbagai unit kerja sesuai dengan regulasi yang ditetapkan rumah sakit. Sebagai tambahan, pimpinan harus menjamin bahwa rumah sakit menyediakan tingkat mutu asuhan yang sama setiap hari dalam seminggu dan pada setiap shift. Regulasi tersebut harus sesuai dengan peraturan perundangan yang berlaku sehingga proses pelayanan pasien dapat diberikan secara kolaboratif. Asuhan pasien yang seragam tercermin dalam hal-hal berikut: a) Akses untuk mendapatkan asuhan dan pengobatan tidak bergantung pada kemampuan pasien untuk membayar atau sumber pembayaran. b) Akses untuk mendapatkan asuhan dan pengobatan yang diberikan oleh PPA yang kompeten tidak bergantung pada hari atau jam yaitu 7 (tujuh) hari, 24 (dua puluh empat) jam c) Kondisi pasien menentukan sumber daya yang akan dialokasikan untuk memenuhi kebutuhannya d) Pemberian asuhan yang diberikan kepada pasien, sama di semua unit pelayanan di rumah sakit misalnya pelayanan anestesi. e) Pasien yang membutuhkan asuhan keperawatan yang sama akan menerima tingkat asuhan keperawatan yang sama di semua unit pelayanan di rumah sakit. Keseragaman dalam memberikan asuhan pada semua pasien akan menghasilkan penggunaan sumber daya yang efektif dan memungkinkan dilakukan evaluasi terhadap hasil asuhan yang sama di semua unit pelyanan di rumah sakit. 3) Elemen penilaian PAP 1', 2, 'Asuhan yang seragam diberikan kepada setiap yang seragam meliputi poin pasien meliputi poin a) – e) a) – e) dalam maksud dan dalam maksud dan tujuan tujuan 2. Bukti rekam medis: memuat rencana pemberian asuhan diintegrasikan dan koordinasikan dengan PPA, MPP, PPA dengan pasien sesuai dengan kebutuhan pasien. • PPA • MPP', '1. Bukti pemberian asuhan • DPJP', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.1.1.a', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 1.1', 'Proses pelayanan dan asuhan pasien yang terintegrasi serta terkoordinasi telah dilakukan sesuai instruksi.', 'Proses pelayanan dan asuhan pasien bersifat dinamis dan melibatkan banyak PPA dan berbagai unit pelayanan. Agar proses pelayanan dan asuhan pasien menjadi efisien, penggunaan sumber daya manusia dan sumber lainnya menjadi efektif, dan hasil akhir kondisi pasien menjadi lebih baik maka diperlukan integrasi dan koordinasi. Kepala unit pelayanan menggunakan cara untuk melakukan integrasi dan koordinasi pelayanan serta asuhan lebih baik (misalnya, pemberian asuhan pasein secara tim oleh para PPA, ronde pasien multidisiplin, formulir catatan perkembangan pasien terintegrasi (CPPT), dan manajer pelayanan pasien/case manager). Instruksi PPA dibutuhkan dalam pemberian asuhan pasien misalnya instruksi pemeriksaan di laboratorium (termasuk patologi anatomi), pemberian obat, asuhan keperawatan khusus, terapi nurtrisi, dan lain-lain. Instruksi ini harus tersedia dan mudah diakses sehingga dapat ditindaklanjuti tepat waktu misalnya dengan menuliskan instruksi pada formulir catatan perkembangan pasien terintegrasi (CPPT) dalam rekam medis atau didokumentasikan dalam elektronik rekam medik agar staf memahami kapan instruksi harus dilakukan, dan siapa yang akan melaksanakan instruksi tersebut. Setiap rumah sakit harus mengatur dalam regulasinya: a) Instruksi seperti apa yang harus tertulis/ didokumentasikan (bukan instruksi melalui telepon atau instruksi lisan saat PPA yang memberi instruksi sedang berada di tempat/rumah sakit), antara lain: (1) Instruksi yang diijinkan melalui telepon terbatas pada situasi darurat dan ketika dokter tidak berada di tempat/di rumah sakit. (2) Instruksi verbal diijinkan terbatas pada situasi dimana dokter yang memberi instruksi sedang melakukan tindakan/prosedur steril. b) Permintaan pemeriksaan laboratorium (termasuk pemeriksaan patologi anatomi) dan diagnostik imajing tertentu harus disertai indikasi klinik c) Pengecualian dalam kondisi khusus, misalnya di unit darurat dan unit intensif d) Siapa yang diberi kewenangan memberi instruksi dan perintah catat di dalam berkas rekam medik/sistem elektronik rekam medik sesuai regulasi rumah sakit Prosedur diagnostik dan tindakan klinis, yang dilakukan sesuai instruksi serta hasilnya didokumentasikan di dalam rekam medis pasien. Contoh prosedur dan tindakan misalnya endoskopi, kateterisasi jantung, terapi radiasi, pemeriksaan Computerized Tomography (CT), dan tindakan serta prosedur diagnostik invasif dan non-invasif lainnya. Informasi mengenai siapa yang meminta dilakukannya prosedur atau tindakan, dan alasan dilakukannya prosedur atau tindakan tersebut didokumentasikan dalam rekam medik. Di rawat jalan bila dilakukan tindakan diagnostik invasif/berisiko, termasuk pasien yang dirujuk dari luar, juga harus dilakukan pengkajian serta pencatatannya dalam rekam medis. 6) Elemen penilaian standar PAP 1.1', 3, 'Rumah sakit telah melakukan pelayanan dan asuhan yang pelayanan dan asuhan pasien terintegrasi serta terkoordinasi terintegrasi (antara DPJP kepada setiap pasien. sebagai ketua tim, PPA lainnya sebagai tim, MPP) PPA MPP', 'Bukti rekam medis: DPJP', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
