INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.2.2.a', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 2.2', 'Rumah sakit melakukan promosi dan edukasi sebagai bagian dari pelayanan kesehatan warga lanjut usia di masyarakat berbasis rumah sakit (hospital based community geriatric service).', 'Pasien geriatri adalah pasien lanjut usia dengan multi penyakit/gangguan akibat penurunan fungsi organ, psikologi, sosial, ekonomi dan lingkungan yang membutuhkan pelayanan kesehatan secara tepadu dengan pendekatan multi disiplin yang bekerja sama secara interdisiplin. Dengan meningkatnya sosial ekonomi dan pelayanan kesehatan maka usia harapan hidup semakin meningkat, sehingga secara demografi terjadi peningkatan populasi lanjut usia. Sehubungan dengan itu rumah sakit perlu menyelenggarakan pelayanan geriatri sesuai dengan tingkat jenis pelayanan geriatri: a) Tingkat sederhana (rawat jalan dan home care) b) Tingkat lengkap (rawat jalan, rawat inap akut dan home care) c) Tingkat sempurna (rawat jalan, rawat inap akut dan home care klinik asuhan siang) d) Tingkat paripurna (rawat jalan, klinik asuhan siang, rawat inap akut, rawat inap kronis, rawat inap psychogeriatri, penitipan pasien respit care dan home care) 7) Elemen penilaian PAP 2.1', 16, 'Rumah sakit telah menetapkan regulasi tentang pelayanan geriatri di rumah penyelenggaraan pelayanan sakit sesuai dengan geriatri di rumah sakit sesuai kemampuan, sumber daya dengan kemampuan, sumber dan sarana prasarana nya daya dan sarana prasarananya.', 'Penetapan penyelenggaraan', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
