INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.2.3.a', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 2.3', 'Rumah sakit memberikan pelayanan kesehatan jiwa rawat jalan, rawat inap dan gawat darurat sesuai dengan tingkat jenis pelayanan.', 'Kesehatan jiwa merupakan kondisi dimana seorang individu dapat berkembang secara fisik, mental, spiritual, dan sosial sehingga individu tersebut menyadari kemampuan sendiri, dapat mengatasi tekanan, dapat bekerja secara produktif, dan mempu memberikan kontibusi untuk komunitasnya Orang yang berisiko gangguan jiwa adalah orang yang mempunyai masalah fisik, mental, sosial, pertumbuhan dan perkembangan, dan/atau kualitas hidup sehingga memiliki risiko mengalami gangguan jiwa. Orang dengan gangguan jiwa (ODGJ) adalah orang yang mengalami gangguan dalam pikiran, perilaku, dan perasaan yang termanifestasi dalam bentuk sekumpulan gejala dan/atau perubahan perilaku yang bermakna, serta dapat menimbulkan penderitaan dan hambatan dalam menjalankan fungsi orang sebagai manusia. Orang dengan masalah kejiwaan (ODMK) dan ODGJ termasuk dalam populasi pasien yang memiliki risiko tinggi. Rumah sakit dalam melakukan penanganan ODMK dan ODGJ perlu menghargai hak asasi manusia. Berdasarkan hal tersebut, diperlukan penyelenggaraan pelayanan jiwa di rumah sakit yang berkualitas dan menghargai hak-hak asasi orang dengan gangguan jiwa yang meliputi penghargaan (to respect), pemenuhan perawatan (to fullfill), dan perlindungan (to protect). Hak-hak pengguna pelayanan kesehatan jiwa dalam mendapatkan perawatan yang berkualitas, meliputi dan tidak terbatas pada: a) Penghargaan terhadap kebutuhan pelayanan fisik maupun psikologis; b) Kebebasan untuk berkomunikasi; dan c) Hak untuk dilibatkan dalam pengambilan keputusan, sampai pada sarana prasarana, makanan dan pakaian. 11) Elemen penilaian PAP 2.3', 25, 'Rumah sakit telah menetapkan regulasi penyelenggaraan pelayanan tentang penyelenggaraan jiwa di rumah sakit sesuai pelayanan jiwa di rumah dengan kemampuan sakit sesuai dengan pelayanan, sarana, kemampuan pelayanan, prasarana, peralatan, sumber sarana, prasarana, daya manusia, dan sumber peralatan, sumber daya daya lain sesuai dengan manusia, dan sumber daya peraturan perundang- lain sesuai dengan undangan. peraturan perundang- undangan.', 'Penetapan kebijakan', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.2.3.b', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 2.3', 'Rumah sakit memberikan pelayanan kesehatan jiwa rawat jalan, rawat inap dan gawat darurat sesuai dengan tingkat jenis pelayanan.', 'Kesehatan jiwa merupakan kondisi dimana seorang individu dapat berkembang secara fisik, mental, spiritual, dan sosial sehingga individu tersebut menyadari kemampuan sendiri, dapat mengatasi tekanan, dapat bekerja secara produktif, dan mempu memberikan kontibusi untuk komunitasnya Orang yang berisiko gangguan jiwa adalah orang yang mempunyai masalah fisik, mental, sosial, pertumbuhan dan perkembangan, dan/atau kualitas hidup sehingga memiliki risiko mengalami gangguan jiwa. Orang dengan gangguan jiwa (ODGJ) adalah orang yang mengalami gangguan dalam pikiran, perilaku, dan perasaan yang termanifestasi dalam bentuk sekumpulan gejala dan/atau perubahan perilaku yang bermakna, serta dapat menimbulkan penderitaan dan hambatan dalam menjalankan fungsi orang sebagai manusia. Orang dengan masalah kejiwaan (ODMK) dan ODGJ termasuk dalam populasi pasien yang memiliki risiko tinggi. Rumah sakit dalam melakukan penanganan ODMK dan ODGJ perlu menghargai hak asasi manusia. Berdasarkan hal tersebut, diperlukan penyelenggaraan pelayanan jiwa di rumah sakit yang berkualitas dan menghargai hak-hak asasi orang dengan gangguan jiwa yang meliputi penghargaan (to respect), pemenuhan perawatan (to fullfill), dan perlindungan (to protect). Hak-hak pengguna pelayanan kesehatan jiwa dalam mendapatkan perawatan yang berkualitas, meliputi dan tidak terbatas pada: a) Penghargaan terhadap kebutuhan pelayanan fisik maupun psikologis; b) Kebebasan untuk berkomunikasi; dan c) Hak untuk dilibatkan dalam pengambilan keputusan, sampai pada sarana prasarana, makanan dan pakaian. 11) Elemen penilaian PAP 2.3', 26, 'Rumah sakit telah melaksanakan berkualitas dan penyelenggaraan pelayanan menghargai hak-hak asasi jiwa yang berkualitas dan orang dengan gangguan menghargai hak-hak asasi jiwa sesuai dengan orang dengan gangguan kemampuan rumah sakit. jiwa 2. Dokter dan perawat yang kompeten (SPK dan RKK) mendukung pelayanan jiwa', '1. Bukti pelayanan jiwa yang Sarana dan prasarana untuk Kepala instalasi terkait', 'D,O,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.2.3.c', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 2.3', 'Rumah sakit memberikan pelayanan kesehatan jiwa rawat jalan, rawat inap dan gawat darurat sesuai dengan tingkat jenis pelayanan.', 'Kesehatan jiwa merupakan kondisi dimana seorang individu dapat berkembang secara fisik, mental, spiritual, dan sosial sehingga individu tersebut menyadari kemampuan sendiri, dapat mengatasi tekanan, dapat bekerja secara produktif, dan mempu memberikan kontibusi untuk komunitasnya Orang yang berisiko gangguan jiwa adalah orang yang mempunyai masalah fisik, mental, sosial, pertumbuhan dan perkembangan, dan/atau kualitas hidup sehingga memiliki risiko mengalami gangguan jiwa. Orang dengan gangguan jiwa (ODGJ) adalah orang yang mengalami gangguan dalam pikiran, perilaku, dan perasaan yang termanifestasi dalam bentuk sekumpulan gejala dan/atau perubahan perilaku yang bermakna, serta dapat menimbulkan penderitaan dan hambatan dalam menjalankan fungsi orang sebagai manusia. Orang dengan masalah kejiwaan (ODMK) dan ODGJ termasuk dalam populasi pasien yang memiliki risiko tinggi. Rumah sakit dalam melakukan penanganan ODMK dan ODGJ perlu menghargai hak asasi manusia. Berdasarkan hal tersebut, diperlukan penyelenggaraan pelayanan jiwa di rumah sakit yang berkualitas dan menghargai hak-hak asasi orang dengan gangguan jiwa yang meliputi penghargaan (to respect), pemenuhan perawatan (to fullfill), dan perlindungan (to protect). Hak-hak pengguna pelayanan kesehatan jiwa dalam mendapatkan perawatan yang berkualitas, meliputi dan tidak terbatas pada: a) Penghargaan terhadap kebutuhan pelayanan fisik maupun psikologis; b) Kebebasan untuk berkomunikasi; dan c) Hak untuk dilibatkan dalam pengambilan keputusan, sampai pada sarana prasarana, makanan dan pakaian. 11) Elemen penilaian PAP 2.3', 27, 'Rumah sakit telah melaksanakan proses evaluasi kegiatan pelayanan pemantauan dan evaluasi jiwa di rumah sakit sesuai kegiatan pelayanan jiwa dengan kemampuan rumah sakit.', 'Hasil pemantauan dan', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.2.4.a', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 2.4', 'Rumah sakit memiliki pelayanan dalam mengidentifikasi, menilai, mengelola dan menindaklanjuti seseorang yang memiliki risiko bunuh diri.', 'Bunuh diri merupakan upaya yang dilakukan seseorang dengan sengaja untuk mengakhiri kehidupan. Faktor risiko bunuh diri adalah situasi yang memicu seseorang melakukan bunuh diri, yaitu: a) Penyakit kronis, b) Penyakit jiwa khususnya depresi, c) Riwayat percobaan bunuh diri, d) Pengguna napza & alcohol, e) Kegagalan, f) Pengalaman traumatis, g) Kesepian, h) Kehilangan, i) Kemiskinan dan j) Sistem pendukung yang kurang. Pasien yang dirawat di rumah sakit harus dilakukan skrining dan pengkajian untuk mengidentifikasi risiko bunuh diri dan melukai diri sendiri sehingga dapat diminimalkan kemungkinan upaya bunuh diri atau melukai diri sendiri. Pasien dengan risiko bunuh diri dilakukan penanganan lebih lanjut. Oleh karena itu rumah sakit perlu memiliki sumber daya manusia yang terlatih dalam mengidentifikasi risiko bunuh diri, melakukan pengkajian lanjut, mencegah risiko bunuh diri dan mengelola serta menindak lanjuti pasien yang risiko bunuh diri. Rumah sakit menerapkan SPO untuk meminimalkan risiko bunuh diri dan melukai diri sendiri pada pasien yang, berdasarkan pengkajian, berisiko untuk bunuh diri dan/atau melukai diri sendiri. Sebagai contoh, rawat inap umum dapat menerapkan persyaratan untuk pemantauan pasien yang berisiko bunuh diri oleh petugas yang ditugaskan (one-on- one), sedangkan unit psikiatri dapat memilih untuk memantau setiap jam. Perbedaan-perbedaan ini dipengaruhi oleh variasi dalam lingkungan fisik dari area perawatan, rasio kepegawaian dan pendidikan staf, dan lain sebagainya. Tujuannya adalah untuk menjaga keselamatan pasien, di mana pun mereka dirawat di rumah sakit; kepala bidang pelayanan melakukan pengkajian risiko dan berkolaborasi dengan staf klinis untuk mengidentifikasi dan menerapkan SPO yang paling sesuai dan tepat untuk setiap area perawatan klinis. Rumah sakit yang merawat pasien yang berisiko bunuh diri dan melukai diri sendiri, seperti rumah sakit dengan unit pelayanan kesehatan jiwa dan rumah sakit jiwa, perlu menilai risiko lingkungan fisik untuk mengidentifikasi area dan fitur yang dapat digunakan untuk percobaan bunuh diri. Kamar pasien, kamar mandi pasien, koridor, dan area lainnya harus dimasukkan dalam pengkajian risiko. Bahaya paling umum untuk risiko bunuh diri adalah titik jangkar/kaitan yang dapat digunakan untuk menggantung diri; namun, terdapat juga banyak jenis bahaya lainnya, dan penting untuk melakukan pengkajian lingkungan secara menyeluruh. Sebagai contoh, pengkajian risiko dapat meliputi pengkajian akses ke benda tajam, obat-obatan, bahan kimia pembersih, dan sebagainya. Unit non-psikiatri di rumah sakit harus menilai area klinis untuk mengidentifikasi objek yang dapat digunakan untuk melukai diri sendiri sehingga saat dibutuhkan, objek tersebut dapat dipindahkan dari area di sekitar pasien yang telah diidentifikasi berisiko tinggi untuk bunuh diri. Sebagai contoh, pelepasan titik jangkar/kaitan, engsel pintu, dan kait yang dapat digunakan untuk menggantung diri. 14) Elemen penialaian PAP 2.4', 28, 'Rumah sakit menetapkan regulasi skrining, pengkajian pengkajian dan pengelolaan dan mengelola serta dan tindak lanjut pasien risiko menindak lanjuti risiko bunuh diri/melukai diri bunuh diri dan melukai diri sendiri pasien yang masuk sendiri bagi semua pasien rawat inap di rumah sakit yang dirawat dirumah sakit. sesuai dengan kemampuan rumah sakit.', 'Penetapan kebijakan skrining,', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
