INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.2.5.a', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 2.5', 'Rumah sakit menerapkan proses pengenalan perubahan kondisi pasien yang memburuk.', 'Staf yang tidak bekerja di daerah pelayanan kritis/intensif mungkin tidak mempunyai pengetahuan dan pelatihan yang cukup untuk melakukan pengkajian, serta mengetahui pasien yang akan masuk dalam kondisi kritis. Padahal, banyak pasien di luar daerah pelayanan kritis mengalami keadaan kritis selama dirawat inap. Seringkali pasien memperlihatkan tanda bahaya dini (contoh, tanda- tanda vital yang memburuk dan perubahan kecil status neurologis) sebelum mengalami penurunan kondisi klinis yang meluas sehingga mengalami kejadian yang tidak diharapkan. Ada kriteria fisiologis yang dapat membantu staf untuk mengenali sedini-dininya pasien yang kondisinya memburuk. Sebagian besar pasien yang mengalami gagal jantung atau gagal paru sebelumnya memperlihatkan tanda-tanda fisiologis di luar kisaran normal yang merupakan indikasi keadaan pasien memburuk. Hal ini dapat diketahui dengan early warning system (EWS). Penerapan EWS membuat staf mampu mengidentifikasi keadaan pasien memburuk sedini- dininya dan bila perlu mencari bantuan staf yang kompeten. Dengan demikian, hasil asuhan akan lebih baik. Pelaksanaan ews dapat dilakukan menggunakan sistem skor oleh ppa yang terlatih. 17) Elemen penilaian PAP 2.5', 34, 'Rumah sakit telah menerapkan proses Pelaksanaan dan penerapan pengenalan perubahan proses pengenalan perubahan kondisi pasien yang kondisi pasien yang memburuk (EWS) dan memburuk (EWS) mendokumentasikannya di dalam rekam medik pasien.', 'Bukti rekam medis: PPA', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.2.5.b', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 2.5', 'Rumah sakit menerapkan proses pengenalan perubahan kondisi pasien yang memburuk.', 'Staf yang tidak bekerja di daerah pelayanan kritis/intensif mungkin tidak mempunyai pengetahuan dan pelatihan yang cukup untuk melakukan pengkajian, serta mengetahui pasien yang akan masuk dalam kondisi kritis. Padahal, banyak pasien di luar daerah pelayanan kritis mengalami keadaan kritis selama dirawat inap. Seringkali pasien memperlihatkan tanda bahaya dini (contoh, tanda- tanda vital yang memburuk dan perubahan kecil status neurologis) sebelum mengalami penurunan kondisi klinis yang meluas sehingga mengalami kejadian yang tidak diharapkan. Ada kriteria fisiologis yang dapat membantu staf untuk mengenali sedini-dininya pasien yang kondisinya memburuk. Sebagian besar pasien yang mengalami gagal jantung atau gagal paru sebelumnya memperlihatkan tanda-tanda fisiologis di luar kisaran normal yang merupakan indikasi keadaan pasien memburuk. Hal ini dapat diketahui dengan early warning system (EWS). Penerapan EWS membuat staf mampu mengidentifikasi keadaan pasien memburuk sedini- dininya dan bila perlu mencari bantuan staf yang kompeten. Dengan demikian, hasil asuhan akan lebih baik. Pelaksanaan ews dapat dilakukan menggunakan sistem skor oleh ppa yang terlatih. 17) Elemen penilaian PAP 2.5', 35, 'Rumah sakit memiliki bukti PPA dilatih menggunakan EWS EWS.', 'Bukti pelatihan PPA tentang', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.2.6.a', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 2.6', 'Pelayanan resusitasi tersedia di seluruh area rumah sakit.', 'Pelayanan resusitasi diartikan sebagai intervensi klinis pada pasien yang mengalami kejadian mengancam hidupnya seperti henti jantung atau paru. Pada saat henti jantung atau paru maka pemberian kompresi pada dada atau bantuan pernapasan akan berdampak pada hidup atau matinya pasien, setidak-tidaknya menghindari kerusakan jaringan otak. Resusitasi yang berhasil pada pasien dengan henti jantung-paru bergantung pada intervensi yang kritikal/penting seperti kecepatan pemberian bantuan hidup dasar, bantuan hidup lanjut yang akurat (code blue) dan kecepatan melakukan defibrilasi. Pelayanan seperti ini harus tersedia untuk semua pasien selama 24 jam setiap hari. Sangat penting untuk dapat memberikan pelayanan intervensi yang kritikal, yaitu tersedia dengan cepat peralatan medis terstandar, obat resusitasi, dan staf terlatih yang baik untuk resusitasi. Bantuan hidup dasar harus dilakukan secepatnya saat diketahui ada tanda henti jantung-paru dan proses pemberian bantuan hidup lanjut kurang dari 5 (lima) menit. Hal ini termasuk evaluasi terhadap pelaksanaan sebenarnya resusitasi atau terhadap simulasi pelatihan resusitasi di rumah sakit. Pelayanan resusitasi tersedia di seluruh area rumah sakit termasuk peralatan medis dan staf terlatih, berbasis bukti klinis, dan populasi pasien yang dilayani. 20) Elemen penilaian PAP 2.6', 36, 'Pelayanan resusitasi tersedia dan diberikan blue 24 jam setiap hari. selama 24 jam setiap hari di 2. Bukti jumlah tim code blue seluruh area rumah sakit. memadai sesuai luas area rumah sakit.', '1. Bukti Daftar jaga tim code Tim kode biru', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
