INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.2.7.c', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 2.7', 'Pelayanan darah dan produk darah dilaksanakan sesuai dengan panduan klinis serta prosedur yang ditetapkan rumah sakit.', 'Pelayanan darah dan produk darah harus diberikan sesuai peraturan perundangan meliputi antara lain: a) Pemberian persetujuan (informed consent); b) Permintaan darah; c) Tes kecocokan; d) Pengadaan darah; e) Penyimpanan darah; f) Identifikasi pasien; g) Distribusi dan pemberian darah; dan h) Pemantauan pasien dan respons terhadap reaksi transfusi. Staf kompeten dan berwenang melaksanakan pelayanan darah dan produk darah serta melakukan pemantauan dan evaluasi. 23) Elemen penilaian PAP 2.7', 42, 'Staf yang kompeten bertanggungjawab terhadap Penunjukan Staf kompeten pelayanan darah di rumah yang bertanggung jawab sakit. terhadap pelayanan darah sesuai dengan kualifikasi dalam pedoman pengorganisasian atau panduan pelayanan darah 2. SPK dan RKK staf yang bertanggung jawan terhadap pelayanan darah dan yang memberikan pelayanan darah/transfusi kepada pasien. darah/PPA c. Pemberian makanan dan terapi nutrisi', '1. Surat Keputusan Penanggung jawab pelayanan', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.3.a', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 3', 'Rumah sakit memberikan makanan untuk pasien rawat inap dan terapi nutrisi terintegrasi untuk pasien dengan risiko nutrisional.', 'Makanan dan terapi nutrisi yang sesuai sangat penting bagi kesehatan pasien dan penyembuhannya. Pilihan makanan disesuaikan dengan usia, budaya, pilihan, rencana asuhan, diagnosis pasien termasuk juga antara lain diet khusus seperti rendah kolesterol dan diet diabetes melitus. Berdasarkan pengkajian kebutuhan dan rencana asuhan, maka DPJP atau PPA lain yang kompeten memesan makanan dan nutrisi lainnya untuk pasien. Pasien berhak menentukan makanan sesuai dengan nilai yang dianut. Bila memungkinkan pasien ditawarkan pilihan makanan yang konsisten dengan status gizi. Jika keluarga pasien atau ada orang lain mau membawa makanan untuk pasien, maka mereka diberikan edukasi tentang makanan yang merupakan kontraindikasi terhadap rencana, kebersihan makanan, dan kebutuhan asuhan pasien, termasuk informasi terkait interaksi antara obat dan makanan. Makanan yang dibawa oleh keluarga atau orang lain disimpan dengan benar untuk mencegah kontaminasi. Skrining risiko gizi dilakukan pada pengkajian awal. Jika pada saat skrining ditemukan pasien dengan risiko gizi maka terapi gizi terintegrasi diberikan, dipantau, dan dievaluasi. 3) Elemen penilaian PAP 3', 43, 'Berbagai pilihan makanan atau terapi nutrisi yang 1. Daftar menu makanan sesuai untuk kondisi, pasien perawatan, dan 2. Daftar menu makanan kebutuhan pasien tersedia diet khusus dan disediakan tepat 3. Jadwal waktu penyajian waktu. makanan', 'Bukti:', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.3.b', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 3', 'Rumah sakit memberikan makanan untuk pasien rawat inap dan terapi nutrisi terintegrasi untuk pasien dengan risiko nutrisional.', 'Makanan dan terapi nutrisi yang sesuai sangat penting bagi kesehatan pasien dan penyembuhannya. Pilihan makanan disesuaikan dengan usia, budaya, pilihan, rencana asuhan, diagnosis pasien termasuk juga antara lain diet khusus seperti rendah kolesterol dan diet diabetes melitus. Berdasarkan pengkajian kebutuhan dan rencana asuhan, maka DPJP atau PPA lain yang kompeten memesan makanan dan nutrisi lainnya untuk pasien. Pasien berhak menentukan makanan sesuai dengan nilai yang dianut. Bila memungkinkan pasien ditawarkan pilihan makanan yang konsisten dengan status gizi. Jika keluarga pasien atau ada orang lain mau membawa makanan untuk pasien, maka mereka diberikan edukasi tentang makanan yang merupakan kontraindikasi terhadap rencana, kebersihan makanan, dan kebutuhan asuhan pasien, termasuk informasi terkait interaksi antara obat dan makanan. Makanan yang dibawa oleh keluarga atau orang lain disimpan dengan benar untuk mencegah kontaminasi. Skrining risiko gizi dilakukan pada pengkajian awal. Jika pada saat skrining ditemukan pasien dengan risiko gizi maka terapi gizi terintegrasi diberikan, dipantau, dan dievaluasi. 3) Elemen penilaian PAP 3', 44, 'Sebelum pasien rawat inap diberi makanan, terdapat pengkajian gizi/ nutrisi instruksi pemberian pasien makanan dalam rekam 2. Bukti rekam medis yang medis pasien yang berisi instruksi didasarkan pada status pemberian makanan gizi dan kebutuhan 3. Berkas pemesanan pasien. makanan pasien sesuai dengan status gizi dan kebutuhan pasien sesuai kebutuhan pasien.', '1. Bukti rekam medis Petugas gizi', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
