INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAP.5.a', 'PAP', 14, 'Pelayanan dan Asuhan Pasien', 1, 'PAP 5', 'Rumah sakit memberikan asuhan pasien menjelang akhir kehidupan dengan memperhatikan kebutuhan pasien dan keluarga, mengoptimalkan kenyamanan dan martabat pasien, serta mendokumentasikan dalam rekam medis.', 'Skrining dilakukan untuk menetapkan bahwa kondisi pasien masuk dalam fase menjelang ajal. Selanjutnya, PPA melakukan pengkajian menjelang akhir kehidupan yang bersifat individual untuk mengidentifikasi kebutuhan pasien dan keluarganya. Pengkajian pada pasien menjelang akhir kehidupan harus menilai kondisi pasien seperti: 1) Manajemen gejala dan respons pasien, termasuk mual, kesulitan bernapas, dan nyeri. 2) Faktor yang memperparah gejala fisik. 3) Orientasi spiritual pasien dan keluarganya, termasuk keterlibatan dalam kelompok agama tertentu. 4) Keprihatinan spiritual pasien dan keluarganya, seperti putus asa, penderitaan, rasa bersalah. 5) Status psikososial pasien dan keluarganya, seperti kekerabatan, kelayakan perumahan, pemeliharaan lingkungan, cara mengatasi, reaksi pasien dan keluarganya menghadapi penyakit. 6) Kebutuhan bantuan atau penundaan layanan untuk pasien dan keluarganya. 7) Kebutuhan alternatif layanan atau tingkat layanan. 8) Faktor risiko bagi yang ditinggalkan dalam hal cara mengatasi dan potensi reaksi patologis. 9) Pasien dan keluarga dilibatkan dalam pengambilan keputusan asuhan. 3) Elemen penilaian PAP 5', 52, 'Rumah sakit menerapkan pengkajian pasien menjelang pasien menjelang akhir akhir kehidupan dan dapat kehidupan dan pengkajian dilakukan pengkajian ulang ulang sampai pasien yang sampai pasien yang memasuki fase akhir memasuki fase akhir kehidupannya, meliputi poin kehidupannya, dengan 1)-9) pada maksud dan memperhatikan poin 1)-9) tujuan. pada maksud dan tujuan. Keluarga pasien', 'Bukti rekam medis pengkajian PPA', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
