INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAB.4.c', 'PAB', 15, 'Pelayanan Anestesi dan Bedah', 1, 'PAB 4', 'Profesional pemberi asuhan (PPA) yang kompeten dan telah diberikan kewenangan klinis pelayanan anestesi melakukan asesmen pra-anestesi dan prainduksi.', 'Oleh karena anestesi memiliki risiko tinggi maka pemberiannya harus direncanakan dengan hati-hati. Pengkajian pra-anestesi adalah dasar perencanaan ini untuk mengetahui temuan pemantauan selama anestesi dan pemulihan yang mungkin bermakna, dan juga untuk menentukan obat analgesi apa untuk pascaoperasi. Pengkajian pra-anestesi juga memberikan informasi yang diperlukan untuk: a) Mengetahui masalah saluran pernapasan; b) Memilih anestesi dan rencana asuhan anestesi; c) Memberikan anestesi yang aman berdasar atas pengkajian pasien, risiko yang ditemukan, dan jenis tindakan; d) Menafsirkan temuan pada waktu pemantauan selama anestesi dan pemulihan; dan e) Memberikan informasi obat analgesia yang akan digunakan pascaoperasi. Dokter spesialis anestesi akan melakukan pengkajian pra- anestesi yang dapat dilakukan sebelum masuk rawat inap atau sebelum dilakukan tindakan bedah atau sesaat menjelang operasi, misalnya pada pasien darurat. Asesmen prainduksi terpisah dari asesmen pra-anestesi, karena difokuskan pada stabilitas fisiologis dan kesiapan pasien untuk tindakan anestesi, dan berlangsung sesaat sebelum induksi anestesi. Jika anestesi diberikan secara darurat maka pengkajian pra-anestesi dan prainduksi dapat dilakukan berurutan atau simultan, namun dicatat secara terpisah.', 15, 'Kedua pengkajian tersebut telah dilakukan oleh PPA yang pengkajian pra anestesi dan kompeten dan telah diberikan pra induksi terisi lengkap dan kewenangan klinis ditandatangani oleh PPA yang didokumentasikan dalam kompeten (tenaga medis). rekam medis pasien.', 'Bukti rekam medis:', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAB.5.a', 'PAB', 15, 'Pelayanan Anestesi dan Bedah', 1, 'PAB 5', 'Risiko, manfaat, dan alternatif tindakan sedasi atau anestesi didiskusikan dengan pasien dan keluarga atau orang yang dapat membuat keputusan mewakili pasien sesuai dengan peraturan perundang-undangan.', 'Rencana tindakan sedasi atau anestesi harus diinformasikan kepada pasien, keluarga pasien, atau mereka yang membuat keputusan mewakili pasien tentang jenis sedasi, risiko, manfaat, dan alternatif terkait tindakan tersebut. Informasi tersebut sebagai bagian dari proses mendapat persetujuan tindakan kedokteran untuk tindakan sedasi atau anestesi sesuai dengan peraturan perundang-undangan yang berlaku.', 16, 'Rumah sakit telah menerapkan pemberian pemberian informasi kepada informasi kepada pasien dan pasien dan atau keluarga atau keluarga atau pihak yang atau pihak yang akan akan memberikan keputusan memberikan keputusan tentang jenis, risiko, manfaat, tentang jenis, risiko, manfaat, alternatif dan analgesia pasca alternatif dan analgesia pasca tindakan sedasi atau anestesi. tindakan sedasi atau anestesi. Pasien/keluarga.', 'Bukti rekam medis DPJP', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAB.5.b', 'PAB', 15, 'Pelayanan Anestesi dan Bedah', 1, 'PAB 5', 'Risiko, manfaat, dan alternatif tindakan sedasi atau anestesi didiskusikan dengan pasien dan keluarga atau orang yang dapat membuat keputusan mewakili pasien sesuai dengan peraturan perundang-undangan.', 'Rencana tindakan sedasi atau anestesi harus diinformasikan kepada pasien, keluarga pasien, atau mereka yang membuat keputusan mewakili pasien tentang jenis sedasi, risiko, manfaat, dan alternatif terkait tindakan tersebut. Informasi tersebut sebagai bagian dari proses mendapat persetujuan tindakan kedokteran untuk tindakan sedasi atau anestesi sesuai dengan peraturan perundang-undangan yang berlaku.', 17, 'Pemberian informasi dilakukan oleh dokter pemberian informasi spesialis anestesi dan dilakukan oleh dokter didokumentasikan dalam spesialis anestesi dan formulir persetujuan tindakan didokumentasikan di anestesi/sedasi. formulir persetujuan atau penolakan tindakan anestesi/sedasi. (Lihat HPK 4.1)', 'Bukti rekam medis Dokter Anestesi', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAB.6.a', 'PAB', 15, 'Pelayanan Anestesi dan Bedah', 1, 'PAB 6', 'Status fisiologis setiap pasien selama tindakan sedasi atau anestesi dipantau sesuai dengan panduan praktik klinis (PPK) dan didokumentasikan dalam rekam medis pasien.', 'Pemantauan fisiologis akan memberikan informasi mengenai status pasien selama tindakan anestesi (umum, spinal, regional dan lokal) dan masa pemulihan. Hasil pemantauan akan menjadi dasar untuk mengambil keputusan intra operasi yang penting dan juga menjadi dasar pengambilan keputusan pascaoperasi seperti pembedahan ulang, pemindahan ke tingkat perawatan lain, atau pemulangan pasien. Informasi hasil pemantauan akan memandu perawatan medis dan keperawatan serta mengidentifikasi kebutuhan diagnostik dan layanan lainnya. Temuan pemantauan dimasukkan ke dalam rekam medis pasien. Metode pemantauan bergantung pada status praanestesi pasien, pemilihan jenis tindakan anestesi, dan kerumitan pembedahan atau prosedur lainnya yang dilakukan selama tindakan anestesi dan pembedahan dalam semua kasus harus sesuai dengan panduan praktik klinis (PPK) dan kebijakan rumah sakit. Hasil pemantauan didokumentasikan dalam rekam medis.', 18, 'Frekuensi dan jenis pemantauan selama tindakan pemantauan selama anestesi dan pembedahan tindakan sedasi, anestesi didasarkan pada status pra dan pembedahan sesuai anestesi pasien, anestesi yang regulasi rumah sakit. digunakan, serta prosedur pembedahan yang dilakukan. Dokter Bedah', 'Bukti rekam medis: Dokter Anestesi', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAB.6.b', 'PAB', 15, 'Pelayanan Anestesi dan Bedah', 1, 'PAB 6', 'Status fisiologis setiap pasien selama tindakan sedasi atau anestesi dipantau sesuai dengan panduan praktik klinis (PPK) dan didokumentasikan dalam rekam medis pasien.', 'Pemantauan fisiologis akan memberikan informasi mengenai status pasien selama tindakan anestesi (umum, spinal, regional dan lokal) dan masa pemulihan. Hasil pemantauan akan menjadi dasar untuk mengambil keputusan intra operasi yang penting dan juga menjadi dasar pengambilan keputusan pascaoperasi seperti pembedahan ulang, pemindahan ke tingkat perawatan lain, atau pemulangan pasien. Informasi hasil pemantauan akan memandu perawatan medis dan keperawatan serta mengidentifikasi kebutuhan diagnostik dan layanan lainnya. Temuan pemantauan dimasukkan ke dalam rekam medis pasien. Metode pemantauan bergantung pada status praanestesi pasien, pemilihan jenis tindakan anestesi, dan kerumitan pembedahan atau prosedur lainnya yang dilakukan selama tindakan anestesi dan pembedahan dalam semua kasus harus sesuai dengan panduan praktik klinis (PPK) dan kebijakan rumah sakit. Hasil pemantauan didokumentasikan dalam rekam medis.', 19, 'Pemantauan status fisiologis pasien sesuai dengan pemantauan status fisiologis panduan praktik klinis (PPK) pasien yang menjalani anestesi. dan didokumentasikan dalam rekam medis pasien. Staf Anestesi.', 'Bukti rekam medis tentang Dokter Anestesi', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAB.6.1.a', 'PAB', 15, 'Pelayanan Anestesi dan Bedah', 1, 'PAB 6.1', 'Status pasca anestesi pasien dipantau dan didokumentasikan, dan pasien dipindahkan /ditransfer /dipulangkan dari area pemulihan oleh PPA yang kompeten dengan menggunakan kriteria baku yang ditetapkan rumah sakit.', 'Pemantauan selama anestesi menjadi dasar pemantauan saat pemulihan pascaanestesi. Pemantauan pasca anestesi dapat dilakukan di ruang rawat intensif atau di ruang pulih. Pemantauan pasca anestesi di ruang rawat intensif bisa direncanakan sejak awal sebelum tindakan operasi atau sebelumnya tidak direncanakan berubah dilakukan pemantauan di ruang intensif atas hasil keputusan PPA anestesi dan atau PPA bedah berdasarkan penilaian selama prosedur anestesi dan atau pembedahan. Bila pemantauan pasca anestesi dilakukan di ruang intensif maka pasien langsung di transfer ke ruang rawat intensif dan tatalaksana pemantauan selanjutnya secara berkesinambungan dan sistematis berdasarkan instruksi DPJP di ruang rawat intensif serta didokumentasikan. Bila pemantauan dilakukan di ruang pulih maka pasien dipantau secara berkesinambungan dan sistematis serta didokumentasikan. Pemindahan pasien dari area pemulihan pascaanestesi atau penghentian pemantauan pemulihan dilakukan dengan salah satu berdasarkan beberapa alternatif sebagai berikut: a) Pasien dipindahkan (atau pemantauan pemulihan dihentikan) oleh seorang ahli anestesi yang kompeten. b) Pasien dipindahkan (atau pemantauan pemulihan dihentikan) oleh seorang perawat atau penata anastesi yang kompeten berdasarkan kriteria pascaanestesi yang ditetapkan oleh rumah sakit, tercatat dalam rekam medis bahwa kriteria tersebut terpenuhi. c) Pasien dipindahkan ke unit yang mampu menyediakan perawatan pascaanestesi misalnya di unit perawatan intensif. Waktu masuk dan keluar dari ruang pemulihan (atau waktu mulai dan dihentikannya pemantauan pemulihan) didokumentasikan dalam rekam medis pasien.', 20, 'Rumah sakit telah menerapkan pemantauan pasien pasca pemantauan pasien pasca anestesi baik di ruang intensif anestesi baik di ruang maupun di ruang pemulihan intensif maupun di ruang dan didokumentasikan dalam pemulihan. rekam medis pasien. Staf Anestesi.', 'Bukti rekam medis tentang Dokter Anestesi', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAB.6.1.b', 'PAB', 15, 'Pelayanan Anestesi dan Bedah', 1, 'PAB 6.1', 'Status pasca anestesi pasien dipantau dan didokumentasikan, dan pasien dipindahkan /ditransfer /dipulangkan dari area pemulihan oleh PPA yang kompeten dengan menggunakan kriteria baku yang ditetapkan rumah sakit.', 'Pemantauan selama anestesi menjadi dasar pemantauan saat pemulihan pascaanestesi. Pemantauan pasca anestesi dapat dilakukan di ruang rawat intensif atau di ruang pulih. Pemantauan pasca anestesi di ruang rawat intensif bisa direncanakan sejak awal sebelum tindakan operasi atau sebelumnya tidak direncanakan berubah dilakukan pemantauan di ruang intensif atas hasil keputusan PPA anestesi dan atau PPA bedah berdasarkan penilaian selama prosedur anestesi dan atau pembedahan. Bila pemantauan pasca anestesi dilakukan di ruang intensif maka pasien langsung di transfer ke ruang rawat intensif dan tatalaksana pemantauan selanjutnya secara berkesinambungan dan sistematis berdasarkan instruksi DPJP di ruang rawat intensif serta didokumentasikan. Bila pemantauan dilakukan di ruang pulih maka pasien dipantau secara berkesinambungan dan sistematis serta didokumentasikan. Pemindahan pasien dari area pemulihan pascaanestesi atau penghentian pemantauan pemulihan dilakukan dengan salah satu berdasarkan beberapa alternatif sebagai berikut: a) Pasien dipindahkan (atau pemantauan pemulihan dihentikan) oleh seorang ahli anestesi yang kompeten. b) Pasien dipindahkan (atau pemantauan pemulihan dihentikan) oleh seorang perawat atau penata anastesi yang kompeten berdasarkan kriteria pascaanestesi yang ditetapkan oleh rumah sakit, tercatat dalam rekam medis bahwa kriteria tersebut terpenuhi. c) Pasien dipindahkan ke unit yang mampu menyediakan perawatan pascaanestesi misalnya di unit perawatan intensif. Waktu masuk dan keluar dari ruang pemulihan (atau waktu mulai dan dihentikannya pemantauan pemulihan) didokumentasikan dalam rekam medis pasien.', 21, 'Pasien dipindahkan dari unit pasca anestesi (atau pelaksanaan pemindahan pemantauan pemulihan pasien dari unit pasca dihentikan) sesuai dengan anestesi (atau pemantauan kriteria baku yang ditetapkan pemulihan dihentikan) sesuai dengan alternatif a) – c) pada dengan kriteria dengan maksud dan tujuan. alternatif a) – c) pada maksud dan tujuan', 'Bukti rekam medis tentang Staf anestesi.', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAB.6.1.c', 'PAB', 15, 'Pelayanan Anestesi dan Bedah', 1, 'PAB 6.1', 'Status pasca anestesi pasien dipantau dan didokumentasikan, dan pasien dipindahkan /ditransfer /dipulangkan dari area pemulihan oleh PPA yang kompeten dengan menggunakan kriteria baku yang ditetapkan rumah sakit.', 'Pemantauan selama anestesi menjadi dasar pemantauan saat pemulihan pascaanestesi. Pemantauan pasca anestesi dapat dilakukan di ruang rawat intensif atau di ruang pulih. Pemantauan pasca anestesi di ruang rawat intensif bisa direncanakan sejak awal sebelum tindakan operasi atau sebelumnya tidak direncanakan berubah dilakukan pemantauan di ruang intensif atas hasil keputusan PPA anestesi dan atau PPA bedah berdasarkan penilaian selama prosedur anestesi dan atau pembedahan. Bila pemantauan pasca anestesi dilakukan di ruang intensif maka pasien langsung di transfer ke ruang rawat intensif dan tatalaksana pemantauan selanjutnya secara berkesinambungan dan sistematis berdasarkan instruksi DPJP di ruang rawat intensif serta didokumentasikan. Bila pemantauan dilakukan di ruang pulih maka pasien dipantau secara berkesinambungan dan sistematis serta didokumentasikan. Pemindahan pasien dari area pemulihan pascaanestesi atau penghentian pemantauan pemulihan dilakukan dengan salah satu berdasarkan beberapa alternatif sebagai berikut: a) Pasien dipindahkan (atau pemantauan pemulihan dihentikan) oleh seorang ahli anestesi yang kompeten. b) Pasien dipindahkan (atau pemantauan pemulihan dihentikan) oleh seorang perawat atau penata anastesi yang kompeten berdasarkan kriteria pascaanestesi yang ditetapkan oleh rumah sakit, tercatat dalam rekam medis bahwa kriteria tersebut terpenuhi. c) Pasien dipindahkan ke unit yang mampu menyediakan perawatan pascaanestesi misalnya di unit perawatan intensif. Waktu masuk dan keluar dari ruang pemulihan (atau waktu mulai dan dihentikannya pemantauan pemulihan) didokumentasikan dalam rekam medis pasien.', 22, 'Waktu dimulai dan dihentikannya proses waktu dimulai dan pemulihan dicatat di dalam dihentikannya proses rekam medis pasien. pemulihan. d. Pelayanan Pembedahan', 'Bukti rekam medis tentang Staf Anestesi.', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAB.7.a', 'PAB', 15, 'Pelayanan Anestesi dan Bedah', 1, 'PAB 7', 'Asuhan setiap pasien bedah direncanakan berdasar atas hasil pengkajian dan dicatat dalam rekam medis pasien.', 'Karena prosedur bedah mengandung risiko tinggi maka pelaksanaannya harus direncanakan dengan saksama. Pengkajian prabedah menjadi acuan untuk menentukan jenis tindakan bedah yang tepat dan mencatat temuan penting. Hasil pengkajian prabedah memberikan informasi tentang: a) Tindakan bedah yang sesuai dan waktu pelaksanaannya; b) Melakukan tindakan dengan aman; dan c) Menyimpulkan temuan selama pemantauan. d) Pemilihan teknik operasi bergantung pada riwayat pasien, status fisik, data diagnostik, serta manfaat dan risiko tindakan yang dipilih. Untuk pasien yang saat masuk rumah sakit langsung dilayani oleh dokter bedah, pengkajian prabedah menggunakan formulir pengkajian awal rawat inap. Sedangkan pasien yang dikonsultasikan di tengah perawatan oleh dokter penanggung jawab pelayanan (DPJP) lain dan diputuskan operasi maka pengkajian prabedah dapat dicatat di rekam medis sesuai kebijakan rumah sakit. Hal ini termasuk diagnosis praoperasi dan pascaoperasi serta nama tindakan operasi.', 23, 'Rumah sakit telah menerapkan pengkajian pra penerapan pengkajian pra bedah pada pasien yang akan bedah pada pasien yang akan dioperasi oleh dokter dioperasi oleh dokter penanggung jawab pelayanan penanggung jawab pelayanan (DPJP) sebelum operasi (DPJP) sebelum operasi dimulai. dimulai, sesuai regulasi rumah sakit.', 'Bukti rekam medis tentang DPJP', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
