INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAB.7.2.a', 'PAB', 15, 'Pelayanan Anestesi dan Bedah', 1, 'PAB 7.2', 'Informasi yang terkait dengan operasi dicatat dalam laporan operasi dan digunakan untuk menyusun rencana asuhan lanjutan.', 'Asuhan pasien pascaoperasi bergantung pada temuan dalam operasi. Hal yang terpenting adalah semua tindakan dan hasilnya dicatat di rekam medis pasien. Laporan ini dapat dibuat dalam bentuk format template atau dalam bentuk laporan operasi tertulis sesuai dengan regulasi rumah sakit. Laporan yang tercatat tentang operasi memuat paling sedikit: e) Diagnosis pascaoperasi; f) Nama dokter bedah dan asistennya; g) Prosedur operasi yang dilakukan dan rincian temuan; h) Ada dan tidak ada komplikasi; i) Spesimen operasi yang dikirim untuk diperiksa; j) Jumlah darah yang hilang dan jumlah yang masuk lewat transfusi; k) Nomor pendaftaran alat yang dipasang (implan), (bila mempergunakan) l) Tanggal, waktu, dan tanda tangan dokter yang bertanggung jawab.', 27, 'Laporan operasi memuat poin a) – h) pada maksud dan tujuan pelaksanaan laporan operasi serta dicatat pada yang memuat poin a) h) formulir/template yang pada maksud dan tujuan. ditetapkan rumah sakit.', 'Bukti rekam medis:', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
