INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PAB.7.3.a', 'PAB', 15, 'Pelayanan Anestesi dan Bedah', 1, 'PAB 7.3', 'Rencana asuhan pascaoperasi disusun, ditetapkan dan dicatat dalam rekam medis.', 'Kebutuhan asuhan medis, keperawatan, dan profesional pemberi asuhan (PPA) lainnya sesuai dengan kebutuhan setiap pasien pascaoperasi berbeda bergantung pada tindakan operasi dan riwayat kesehatan pasien. Beberapa pasien mungkin membutuhkan pelayanan dari profesional pemberi asuhan (PPA) lain atau unit lain seperti rehabilitasi medik atau terapi fisik. Penting membuat rencana asuhan tersebut termasuk tingkat asuhan, metode asuhan, tindak lanjut monitor atau tindak lanjut tindakan, kebutuhan obat, dan asuhan lain atau tindakan serta layanan lain. Rencana asuhan pascaoperasi dapat dimulai sebelum tindakan operasi berdasarkan asesmen kebutuhan dan kondisi pasien serta jenis operasi yang dilakukan. Rencana asuhan pasca operasi juga memuat kebutuhan pasien yang segera. Rencana asuhan dicatat direkam medik pasien dalam waktu 24 jam dan diverifikasi oleh dokter penanggung jawab pelayanan (DPJP) sebagai pimpinan tim klinis untuk memastikan kontuinitas asuhan selama waktu pemulihan dan masa rehabilitasi.', 29, 'Rencana asuhan pascaoperasi dicatat di rekam medis pasien asuhan pascaoperasi dicatat dalam waktu 24 jam oleh dokter dalam waktu 24 jam oleh penanggung jawab pelayanan dokter penanggung jawab (DPJP). pelayanan (DPJP).', 'Bukti rekam medis: rencana', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
