INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PKPO.5.g', 'PKPO', 16, 'Pelayanan Kefarmasian dan Penggunaan Obat', 1, 'PKPO 5', 'Rumah sakit menetapkan dan menerapkan regulasi dispensing sediaan farmasi dan bahan medis habis pakai sesuai standar profesi dan peraturan perundang-undangan.', 'Penyiapan (dispensing) adalah rangkaian proses mulai dari diterimanya resep/permintaan obat/instruksi pengobatan sampai dengan penyerahan obat dan BMHP kepada dokter/perawat atau kepada pasien/keluarga. Penyiapan obat dilakukan oleh staf yang terlatih dalam lingkungan yang aman bagi pasien, staf dan lingkungan sesuai peraturan perundang-undangan dan standar praktik kefarmasian untuk menjamin keamanan, mutu, manfaat dan khasiatnya. Untuk menghindari kesalahan pemberian obat pada pasien rawat inap, maka obat yang diserahkan harus dalam bentuk yang siap digunakan, dan disertai dengan informasi lengkap tentang pasien dan obat.', 34, 'Obat yang sudah disiapkan diberi etiket yang meliputi identitas pasien, nama obat, dosis atau konsentrasi, cara pemakaian, waktu pemberian, tanggal dispensing dan tanggal kedaluwarsa/beyond use date (BUD).', 'Etiket obat sesuai ketentuan', 'O', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PKPO.5.1.a', 'PKPO', 16, 'Pelayanan Kefarmasian dan Penggunaan Obat', 1, 'PKPO 5.1', 'Rumah sakit menetapkan dan menerapkan regulasi pengkajian resep dan telaah obat sesuai peraturan perundang-undangan dan standar praktik profesi.', 'Pengkajian resep adalah kegiatan menelaah resep sebelum obat disiapkan, yang meliputi pengkajian aspek administratif, farmasetik dan klinis. Pengkajian resep dilakukan oleh tenaga kefarmasian yang kompeten dan diberi kewenangan dengan tujuan untuk mengidentifikasi dan menyelesaikan masalah terkait obat sebelum obat disiapkan. Pengkajian resep aspek administratif meliputi: kesesuaian identitas pasien (lihat SKP 1), ruang rawat, status pembiayaan, tanggal resep, identitas dokter penulis resep. Pengkajian resep aspek farmasetik meliputi: nama obat, bentuk dan kekuatan sediaan, jumlah obat, instruksi cara pembuatan (jika diperlukan peracikan), stabilitas dan inkompatibilitas sediaan. Pengkajian resep aspek klinis meliputi: a) Ketepatan identitas pasien, obat, dosis, frekuensi, aturan pakai dan waktu pemberian. b) Duplikasi pengobatan. c) Potensi alergi atau hipersensitivitas. d) Interaksi antara obat dan obat lain atau dengan makanan. e) Variasi kriteria penggunaan dari rumah sakit, misalnya membandingkan dengan panduan praktik klinis, formularium nasional. f) Berat badan pasien dan atau informasi fisiologis lainnya. g) Kontraindikasi. Dalam pengkajian resep tenaga teknis kefarmasian diberi kewenangan terbatas hanya aspek administratif dan farmasetik. Pengkajian resep aspek klinis yang baik oleh apoteker memerlukan data klinis pasien, sehingga apoteker harus diberi kemudahan akses untuk mendapatkan informasi klinis pasien. Apoteker/tenaga teknis kefarmasian harus melakukan telaah obat sebelum obat diserahkan kepada perawat/pasien.untuk memastikan bahwa obat yang sudah disiapkan tepat: a) Pasien. b) Nama obat. c) Dosis dan jumlah obat. d) Rute pemberian. e) Waktu pemberian.', 35, 'Telah melaksanakan pengkajian resep yang staf yang kompeten dan dilakukan oleh staf yang berwenang kompeten dan berwenang 2. SPK dan RKK serta didukung tersedianya informasi klinis pasien yang diakses oleh apoteker pada memadai. saat melakukan pengkajian resep. Apoteker Tenaga vokasi farmasi', '1. Bukti pengkajian resep oleh Tersedia data klinis yang dapat Kepala Instalasi Farmasi Pengkajian resep oleh apoteker', 'D,O,S,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PKPO.5.1.b', 'PKPO', 16, 'Pelayanan Kefarmasian dan Penggunaan Obat', 1, 'PKPO 5.1', 'Rumah sakit menetapkan dan menerapkan regulasi pengkajian resep dan telaah obat sesuai peraturan perundang-undangan dan standar praktik profesi.', 'Pengkajian resep adalah kegiatan menelaah resep sebelum obat disiapkan, yang meliputi pengkajian aspek administratif, farmasetik dan klinis. Pengkajian resep dilakukan oleh tenaga kefarmasian yang kompeten dan diberi kewenangan dengan tujuan untuk mengidentifikasi dan menyelesaikan masalah terkait obat sebelum obat disiapkan. Pengkajian resep aspek administratif meliputi: kesesuaian identitas pasien (lihat SKP 1), ruang rawat, status pembiayaan, tanggal resep, identitas dokter penulis resep. Pengkajian resep aspek farmasetik meliputi: nama obat, bentuk dan kekuatan sediaan, jumlah obat, instruksi cara pembuatan (jika diperlukan peracikan), stabilitas dan inkompatibilitas sediaan. Pengkajian resep aspek klinis meliputi: a) Ketepatan identitas pasien, obat, dosis, frekuensi, aturan pakai dan waktu pemberian. b) Duplikasi pengobatan. c) Potensi alergi atau hipersensitivitas. d) Interaksi antara obat dan obat lain atau dengan makanan. e) Variasi kriteria penggunaan dari rumah sakit, misalnya membandingkan dengan panduan praktik klinis, formularium nasional. f) Berat badan pasien dan atau informasi fisiologis lainnya. g) Kontraindikasi. Dalam pengkajian resep tenaga teknis kefarmasian diberi kewenangan terbatas hanya aspek administratif dan farmasetik. Pengkajian resep aspek klinis yang baik oleh apoteker memerlukan data klinis pasien, sehingga apoteker harus diberi kemudahan akses untuk mendapatkan informasi klinis pasien. Apoteker/tenaga teknis kefarmasian harus melakukan telaah obat sebelum obat diserahkan kepada perawat/pasien.untuk memastikan bahwa obat yang sudah disiapkan tepat: a) Pasien. b) Nama obat. c) Dosis dan jumlah obat. d) Rute pemberian. e) Waktu pemberian.', 36, 'Telah memiliki proses telaah obat sebelum diserahkan. diserahkan oleh farmasi Apoteker Tenaga vokasi farmasi Apoteker f. Pemberian Obat', 'Bukti telaah obat sebelum Telaah obat Kepala Instalasi Farmasi Proses telaah obat oleh', 'D,O,S,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PKPO.6.a', 'PKPO', 16, 'Pelayanan Kefarmasian dan Penggunaan Obat', 1, 'PKPO 6', 'Rumah sakit menetapkan dan menerapkan regulasi pemberian obat sesuai peraturan perundang-undangan.', 'Tahap pemberian obat merupakan tahap akhir dalam proses penggunaan obat sebelum obat masuk ke dalam tubuh pasien. Tahap ini merupakan tahap yang kritikal ketika terjadi kesalahan obat (medication error) karena pasien akan langsung terpapar dan dapat menimbulkan cedera. Rumah sakit harus menetapkan dan menerapkan regulasi pemberian obat. Rumah sakit menetapkan profesional pemberi asuhan (PPA) yang kompeten dan berwenang memberikan obat sesuai peraturan perundang-undangan. Rumah sakit dapat membatasi kewenangan staf klinis dalam melakukan pemberian obat, misalnya pemberian obat anestesi, kemoterapi, radioaktif, obat penelitian. Sebelum pemberian obat kepada pasien, dilakukan verifikasi kesesuaian obat dengan instruksi pengobatan yang meliputi: a) Identitas pasien. b) Nama obat. c) Dosis. d) Rute pemberian e) Waktu pemberian. Obat yang termasuk golongan obat high alert, harus dilakukan double checking untuk menjamin ketepatan pemberian obat.', 37, 'Staf yang melakukan pemberian obat, kompeten staf klinis yg kompeten dalam dan berwenang dengan melakukan pemberian obat pembatasan yang ditetapkan. sesuai maksud dan tujuan. staf klinis yang kompeten dan berwenang 2. SPK dan RKK', 'Bukti penetapan kewenangan 1. Bukti pemberian obat oleh Tenaga Medis', 'D,R,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
