INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PKPO.6.d', 'PKPO', 16, 'Pelayanan Kefarmasian dan Penggunaan Obat', 1, 'PKPO 6', 'Rumah sakit menetapkan dan menerapkan regulasi pemberian obat sesuai peraturan perundang-undangan.', 'Tahap pemberian obat merupakan tahap akhir dalam proses penggunaan obat sebelum obat masuk ke dalam tubuh pasien. Tahap ini merupakan tahap yang kritikal ketika terjadi kesalahan obat (medication error) karena pasien akan langsung terpapar dan dapat menimbulkan cedera. Rumah sakit harus menetapkan dan menerapkan regulasi pemberian obat. Rumah sakit menetapkan profesional pemberi asuhan (PPA) yang kompeten dan berwenang memberikan obat sesuai peraturan perundang-undangan. Rumah sakit dapat membatasi kewenangan staf klinis dalam melakukan pemberian obat, misalnya pemberian obat anestesi, kemoterapi, radioaktif, obat penelitian. Sebelum pemberian obat kepada pasien, dilakukan verifikasi kesesuaian obat dengan instruksi pengobatan yang meliputi: a) Identitas pasien. b) Nama obat. c) Dosis. d) Rute pemberian e) Waktu pemberian. Obat yang termasuk golongan obat high alert, harus dilakukan double checking untuk menjamin ketepatan pemberian obat.', 40, 'Pasien diberi informasi tentang obat yang akan tentang obat yang akan diberikan. diberikan kepada pasien. Perawat Pasien', 'Bukti pemberian informasi Apoteker', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PKPO.6.1.a', 'PKPO', 16, 'Pelayanan Kefarmasian dan Penggunaan Obat', 1, 'PKPO 6.1', 'Rumah sakit menetapkan dan menerapkan regulasi penggunaan obat yang dibawa pasien dari luar rumah sakit dan penggunaan obat oleh pasien secara mandiri.', 'Obat yang dibawa pasien/keluarga dari luar rumah sakit berisiko dalam hal identifikasi/keaslian dan mutu obat. Oleh sebab itu rumah sakit harus melakukan penilaian terhadap obat tersebut terkait kelayakanpenggunaannya di rumah sakit. Penggunaan obat oleh pasien secara mandiri, baik yang dibawa dari luar rumah sakit atau yang diresepkan dari rumah sakit harus diketahui oleh dokter yang merawat dan dicatat di rekam medis pasien. Penggunaan obat secara mandiri harus ada proses edukasi dan pemantauan penggunaannya untuk menghindari penggunaan obat yang tidak tepat.', 41, 'Telah melakukan penilaian obat yang dibawa pasien dari dibawa pasien dari luar luar rumah sakit untuk rumah sakit. kelayakan penggunaannya di rumah sakit. Apoteker Staf Farmasi', 'Bukti penilaian obat yang Kepala Instalasi Farmasi', 'D,W', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
