INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('PKPO.7.1.a', 'PKPO', 16, 'Pelayanan Kefarmasian dan Penggunaan Obat', 1, 'PKPO 7.1', 'Rumah sakit menetapkan dan menerapkan proses pelaporan serta tindak lanjut terhadap kesalahan obat (medication error) dan berupaya menurunkan kejadiannya.', 'Insiden kesalahan obat (medication error) merupakan penyebab utama cedera pada pasien yang seharusnya dapat dicegah. Untuk meningkatkan keselamatan pasien, rumah sakit harus berupaya mengurangi terjadinya kesalahan obat dengan membuat sistem pelayanan kefarmasian dan penggunaan obat yang lebih aman (medication safety). Insiden kesalahan obat harus dijadikan sebagai pembelajaran bagi rumah sakit agar kesalahan tersebut tidak terulang lagi. Rumah sakit menerapkan pelaporan insiden keselamatan pasien serta tindak lanjut terhadap kejadian kesalahan obat serta upaya perbaikannya. Proses pelaporan kesalahan obat yang mencakup kejadian sentinel, kejadian yang tidak diharapkan (KTD), kejadian tidak cedera (KTC) maupun kejadian nyaris cedera (KNC), menjadi bagian dari program peningkatan mutu dan keselamatan pasien. Rumah sakit memberikan pelatihan kepada staf rumah sakit tentang kesalahan obat dalam rangka upaya perbaikan dan untuk mencegah kesalahan obat, serta meningkatkan keselamatan pasien.', 46, 'Rumah sakit telah memiliki regulasi tentang medication safety safety yang bertujuan mengarahkan penggunaan obat yang aman dan meminimalkan risiko kesalahan penggunaan obat sesuai dengan peraturan perundang-undangan.', 'Regulasi tentang medication', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
