INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KE.1.a', 'KE', 17, 'Komunikasi dan Edukasi', 1, 'KE 1', 'Rumah sakit menetapkan tim atau unit Promosi Kesehatan Rumah Sakit (PKRS) dengan tugas dan tanggung jawab sesuai peraturan perundangan.', 'Setiap rumah sakit mengintegrasikan edukasi pasien dan keluarga sebagai bagian dari proses perawatan, disesuaikan dengan misi, pelayanan yang disediakan, serta populasi pasiennya. Edukasi direncanakan sedemikian rupa sehingga setiap pasien mendapatkan edukasi yang dibutuhkan oleh pasien tersebut. Rumah sakit menetapkan pengaturan sumber daya edukasi secara efisien dan efektif. Oleh karena itu, rumah sakit dapat menetapkan tim atau unit Promosi Kesehatan Rumah Sakit (PKRS), menyelenggarakan pelayanan edukasi, dan mengatur penugasan seluruh staf yang memberikan edukasi secara terkoordinasi. Staf klinis memahami kontribusinya masing-masing dalam pemberian edukasi pasien, sehingga mereka dapat berkolaborasi secara efektif. Kolaborasi menjamin bahwa informasi yang diterima pasien dan keluarga adalah komprehensif, konsisten, dan efektif. Kolaborasi ini didasarkan pada kebutuhan pasien, oleh karena itu mungkin tidak selalu diperlukan. Agar edukasi yang diberikan dapat berhasil guna, dibutuhkan pertimbangan- pertimbangan penting seperti pengetahuan tentang materi yang akan diedukasikan, waktu yang cukup untuk memberi edukasi, dan kemampuan untuk berkomunikasi secara efektif.', 1, 'Rumah Sakit menetapkan regulasi tentang pelaksanaan pelaksanaan PKRS di rumah PKRS di rumah sakit sesuai sakit sesuai poin a) – b) pada poin a) – b) pada gambaran gambaran umum. umum.', 'Regulasi tentang', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
