INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KE.2.a', 'KE', 17, 'Komunikasi dan Edukasi', 1, 'KE 2', 'Rumah sakit memberikan informasi kepada pasien dan keluarga tentang jenis asuhan dan pelayanan, serta akses untuk mendapatkan pelayanan.', 'Pasien dan keluarga membutuhkan informasi lengkap mengenai asuhan dan pelayanan yang disediakan oleh rumah sakit, serta bagaimana untuk mengakses pelayanan tersebut. Hal ini akan membantu menghubungkan harapan pasien dengan kemampuan rumah sakit. Rumah sakit memberikan informasi tentang sumber alternatif asuhan dan pelayanan di tempat lain, jika rumah sakit tidak dapat menyediakan asuhan serta pelayanan yang dibutuhkan pasien. Akses mendapatkan informasi kesehatan diberikan secara tepat waktu, dan status sosial ekonomi perawatan pasien tidak menghalangi pasien dan keluarga untuk mendapatkan informasi yang dibutuhkan.', 5, 'Tersedia informasi untuk pasien dan keluarga informasi untuk pasien dan mengenai asuhan dan keluarga mengenai asuhan pelayanan yang disediakan dan pelayanan yang oleh rumah sakit serta akses disediakan oleh rumah sakit untuk mendapatkan serta informasi akses untuk layanan tersebut. Informasi mendapatkan layanan dapat disampaikan secara tersebut. Informasi dapat langsung dan/atau tidak disampaikan secara langsung langsung. dan/atau tidak langsung.', 'Dokumen bukti adanya', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
