INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KE.2.c', 'KE', 17, 'Komunikasi dan Edukasi', 1, 'KE 2', 'Rumah sakit memberikan informasi kepada pasien dan keluarga tentang jenis asuhan dan pelayanan, serta akses untuk mendapatkan pelayanan.', 'Pasien dan keluarga membutuhkan informasi lengkap mengenai asuhan dan pelayanan yang disediakan oleh rumah sakit, serta bagaimana untuk mengakses pelayanan tersebut. Hal ini akan membantu menghubungkan harapan pasien dengan kemampuan rumah sakit. Rumah sakit memberikan informasi tentang sumber alternatif asuhan dan pelayanan di tempat lain, jika rumah sakit tidak dapat menyediakan asuhan serta pelayanan yang dibutuhkan pasien. Akses mendapatkan informasi kesehatan diberikan secara tepat waktu, dan status sosial ekonomi perawatan pasien tidak menghalangi pasien dan keluarga untuk mendapatkan informasi yang dibutuhkan.', 7, 'Akses mendapatkan informasi kesehatan telah diberikan secara tepat Elemen Penilaian Kelengkapan Bukti skoring diberikan secara tepat waktu dan status sosial waktu, dan status sosial ekonomi perawatan pasien ekonomi perawatan pasien tidak menghalangi pasien dan tidak menghalangi pasien keluarga untuk mendapatkan dan keluarga untuk informasi yang dibutuhkan mendapatkan informasi pada rekam medik yang dibutuhkan.', 'Bukti informasi kesehatan', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KE.2.d', 'KE', 17, 'Komunikasi dan Edukasi', 1, 'KE 2', 'Rumah sakit memberikan informasi kepada pasien dan keluarga tentang jenis asuhan dan pelayanan, serta akses untuk mendapatkan pelayanan.', 'Pasien dan keluarga membutuhkan informasi lengkap mengenai asuhan dan pelayanan yang disediakan oleh rumah sakit, serta bagaimana untuk mengakses pelayanan tersebut. Hal ini akan membantu menghubungkan harapan pasien dengan kemampuan rumah sakit. Rumah sakit memberikan informasi tentang sumber alternatif asuhan dan pelayanan di tempat lain, jika rumah sakit tidak dapat menyediakan asuhan serta pelayanan yang dibutuhkan pasien. Akses mendapatkan informasi kesehatan diberikan secara tepat waktu, dan status sosial ekonomi perawatan pasien tidak menghalangi pasien dan keluarga untuk mendapatkan informasi yang dibutuhkan.', 8, 'Terdapat bukti pemberian informasi untuk pasien dan medik tentang pemberian keluarga mengenai asuhan informasi untuk pasien dan dan pelayanan di rumah keluarga mengenai asuhan sakit.', 'Dokumen bukti di rekam', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KE.3.a', 'KE', 17, 'Komunikasi dan Edukasi', 1, 'KE 3', 'Rumah sakit melakukan pengkajian terhadap kebutuhan edukasi setiap pasien, beserta kesiapan dan kemampuan pasien untuk menerima edukasi.', 'Edukasi berfokus pada pemahaman yang dibutuhkan pasien dan keluarga dalam pengambilan keputusan, berpartisipasi dalam asuhan dan asuhan berkelanjutan di rumah. Untuk memahami kebutuhan edukasi dari setiap pasien beserta keluarganya, perlu dilakukan pengkajian. Pengkajian ini memungkinkan staf rumah sakit untuk merencanakan dan memberikan edukasi sesuai kebutuhan pasien. Pengetahuan dan keterampilan pasien dan keluarga yang menjadi kekuatan dan kekurangan diidentifikasi untuk digunakan dalam membuat rencana edukasi. Pengkajian kemampuan dan kemauan belajar pasien/keluarga meliputi: a) Kemampuan membaca, tingkat Pendidikan; b) Bahasa yang digunakan (apakah diperlukan penerjemah atau penggunaan bahasa isyarat); c) Hambatan emosional dan motivasi; d) Keterbatasan fisik dan kognitif; e) Kesediaan pasien untuk menerima informasi; dan f) Nilai-nilai dan pilihan pasien. Hasil pengkajian tersebut dijadikan dasar oleh staf klinis dalam merencanakan dan melaksanakan pemberian informasi dan edukasi kepada pasien dan keluarga. Hasil pengkajian didokumentasikan di rekam medis pasien agar PPA yang terlibat merawat pasien dapat berpartisipasi dalam proses edukasi.', 9, 'Kebutuhan edukasi pasien dan keluarga dinilai berdasarkan penilaian kebutuhan pengkajian terhadap edukasi pasien dan kemampuan dan kemauan keluarga yang berdasarkan belajar pasien dan keluarga pengkajian terhadap yang meliputi poin a) – f) pada kemampuan dan kemauan maksud dan tujuan, dan belajar pasien dan keluarga dicatat di rekam medis. yang meliputi poin a) –', 'Pengkajian tentang', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
