INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KE.5.a', 'KE', 17, 'Komunikasi dan Edukasi', 1, 'KE 5', 'Metode edukasi dipilih dengan mempertimbangkan nilai yang dianut serta preferensi pasien dan keluarganya, untuk memungkinkan terjadinya interaksi yang memadai antara pasien, keluarga pasien dan staf.', 'Proses edukasi akan berlangsung dengan baik bila mengunakan metode yang tepat. Pemahaman tentang kebutuhan edukasi pasien serta keluarganya akan membantu rumah sakit untuk memilih edukator dan metode edukasi yang sesuai dengan nilai dan preferensi dari pasien dan keluarganya, serta mengidentifikasi peran pasien/keluarga. Dalam proses edukasi pasien dan keluarga didorong untuk bertanya/berdiskusi agar dapat berpartisipasi dalam proses asuhan. Materi edukasi yang diberikan harus selalu diperbaharui dan dapat dipahami oleh pasien dan keluarga. Pasien dan keluarga diberi kesempatan untuk berinteraksi aktif sehingga mereka dapat memberikan umpan balik untuk memastikan bahwa informasi dimengerti dan bermanfaat untuk diterapkan. Edukasi lisan dapat diperkuat dengan materi tertulis agar pemahaman pasien meningkat dan sebagai referensi untuk bahan edukasi selanjutnya. Rumah sakit harus menyediakan penerjemah sesuai dengan kebutuhan pasien dan keluarga. Bila di rumah sakit tidak ada petugas penerjemah maka dapat dilakukan kerja sama dengan pihak ketiga diluar rumah sakit.', 16, 'Rumah sakit memiliki proses untuk memastikan bahwa untuk memastikan bahwa pasien dan keluarganya pasien dan keluarganya memahami edukasi yang paham edukasi yang diberikan. diberikan, melalui wawancara', 'Bukti pelaksanaan verifikasi', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KE.5.b', 'KE', 17, 'Komunikasi dan Edukasi', 1, 'KE 5', 'Metode edukasi dipilih dengan mempertimbangkan nilai yang dianut serta preferensi pasien dan keluarganya, untuk memungkinkan terjadinya interaksi yang memadai antara pasien, keluarga pasien dan staf.', 'Proses edukasi akan berlangsung dengan baik bila mengunakan metode yang tepat. Pemahaman tentang kebutuhan edukasi pasien serta keluarganya akan membantu rumah sakit untuk memilih edukator dan metode edukasi yang sesuai dengan nilai dan preferensi dari pasien dan keluarganya, serta mengidentifikasi peran pasien/keluarga. Dalam proses edukasi pasien dan keluarga didorong untuk bertanya/berdiskusi agar dapat berpartisipasi dalam proses asuhan. Materi edukasi yang diberikan harus selalu diperbaharui dan dapat dipahami oleh pasien dan keluarga. Pasien dan keluarga diberi kesempatan untuk berinteraksi aktif sehingga mereka dapat memberikan umpan balik untuk memastikan bahwa informasi dimengerti dan bermanfaat untuk diterapkan. Edukasi lisan dapat diperkuat dengan materi tertulis agar pemahaman pasien meningkat dan sebagai referensi untuk bahan edukasi selanjutnya. Rumah sakit harus menyediakan penerjemah sesuai dengan kebutuhan pasien dan keluarga. Bila di rumah sakit tidak ada petugas penerjemah maka dapat dilakukan kerja sama dengan pihak ketiga diluar rumah sakit.', 17, 'Proses pemberian edukasi di dokumentasikan dalam tentang pelaksanaan edukasi rekam medik sesuai dengan yang sesuai dengan metode metode edukasi yang dapat edukasi yang dapat diterima diterima pasien dan pasien dan keluarganya. keluarganya.', 'Bukti dalam rekam medik', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
