INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KE.7.a', 'KE', 17, 'Komunikasi dan Edukasi', 1, 'KE 7', 'Profesional Pemberi Asuhan (PPA) mampu memberikan edukasi secara efektif.', 'Profesional Pemberi Asuhan (PPA) yang memberi asuhan memahami kontribusinya masing-masing dalam pemberian edukasi pasien. Informasi yang diterima pasien dan keluarga harus komprehensif, konsisten, dan efektif. Profesional Pemberi Asuhan (PPA) diberikan pelatihan sehingga terampil melaksanakan komunikasi efektif. 18) Elemen penilaian KE 7', 25, 'Profesional Pemberi Asuhan (PPA) telah diberikan pelatihan Pemberi Asuhan (PPA) telah dan terampil melaksanakan diberikan pelatihan dan komunikasi efektif. terampil dalam melaksanakan komunikasi efektif berupa TOR, Materi, Undangan, Sertifikat, Notulen dan Bukti Pelaksanaan lainnya', 'Bukti bahwa Profesional', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('KE.7.b', 'KE', 17, 'Komunikasi dan Edukasi', 1, 'KE 7', 'Profesional Pemberi Asuhan (PPA) mampu memberikan edukasi secara efektif.', 'Profesional Pemberi Asuhan (PPA) yang memberi asuhan memahami kontribusinya masing-masing dalam pemberian edukasi pasien. Informasi yang diterima pasien dan keluarga harus komprehensif, konsisten, dan efektif. Profesional Pemberi Asuhan (PPA) diberikan pelatihan sehingga terampil melaksanakan komunikasi efektif. 18) Elemen penilaian KE 7', 26, 'PPA telah memberikan edukasi yang efektif kepada pasien dan bahwa Profesional Pemberi keluarga secara kolaboratif. Asuhan (PPA) telah memberikan edukasi yang efektif kepada pasien dan keluarga secara kolaboratif.', 'Bukti dalam rekam medik', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('SKP.1.1', 'SKP', 20, 'Sasaran Keselamatan Pasien', 3, 'SKP 1', 'Rumah sakit menerapkan proses untuk menjamin ketepatan identifikasi pasien.', 'Kesalahan mengidentifikasi pasien dapat terjadi di semua aspek pelayanan baik diagnosis, proses pengobatan serta tindakan. Misalnya saat keadaan pasien masih dibius, mengalami disorientasi atau belum sepenuhnya sadar; adanya kemungkinan pindah tempat tidur, pindah kamar, atau pindah lokasi di dalam rumah sakit; atau apabila pasien memiliki cacat indra atau rentan terhadap situasi berbeda. Adapun tujuan dari identifikasi pasien secara benar ini adalah: 1) Mengidentifikasi pasien sebagai individu yang akan diberi layanan, tindakan atau pengobatan tertentu secara tepat. 2) Mencocokkan layanan atau perawatan yang akan diberikan dengan pasien yang akan menerima layanan. Identifikasi pasien dilakukan setidaknya menggunakan minimal 2 (dua) identitas yaitu nama lengkap dan tanggal lahir/bar code, dan tidak termasuk nomor kamar atau lokasi pasien agar tepat pasien dan tepat pelayanan sesuai dengan regulasi rumah sakit. Pasien diidentifikasi menggunakan minimal dua jenis identitas pada saat: 1) melakukan tindakan intervensi/terapi (misalnya pemberian obat, pemberian darah atau produk darah, melakukan terapi radiasi); 2) melakukan tindakan (misalnya memasang jalur intravena atau hemodialisis); 3) sebelum tindakan diagnostik apa pun (misalnya mengambil darah dan spesimen lain untuk pemeriksaan laboratorium penunjang, atau sebelum melakukan kateterisasi jantung ataupun tindakan radiologi diagnostik); dan 4) menyajikan makanan pasien. Rumah sakit memastikan pasien teridentifikasi dengan tepat pada situasi khusus, seperti pada pasien koma atau pada bayi baru lahir yang tidak segera diberi nama serta identifikasi pasien pada saat terjadi darurat bencana. Penggunaan dua identitas juga digunakan dalam pelabelan. misalnya, sampel darah dan sampel patologi, nampan makanan pasien, label ASI yang disimpan untuk bayi yang dirawat di rumah sakit.', 1, 'Rumah sakit telah menetapkan regulasi terkait Sasaran pasien meliputi poin 1 – 6 pada keselamatan pasien meliputi gambaran umum. poin 1 – 6 pada gambaran umum.', 'Penetapan sasaran keselamatan', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
