INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('Prognas.1.1.3', 'Prognas', 30, 'Program Nasional', 4, 'Prognas 1.1', 'Untuk meningkatkan efektifitas sistem rujukan maka Rumah sakit melakukan pembinaan kepada jejaring fasilitas Kesehatan rujukan yang ada.', 'Salah satu tugas dari rumah sakit dengan kemampuan PONEK adalah melakukan pembinaan kepada jejaring rujukan seperti Puskesmas, Klinik bersalin, praktek perseorangan dan fasilitas pelayanan kesehatan lainnya. Pembinaan jejaring rujukan dapat dilakukan dengan mengadakan pelatihan kepada fasilitas kesehatan jejaring, berbagi pengalaman dalam pelayanan ibu dan anak serta peningkatanan kompetensi jejaring rujukan secara berkala. Rumah sakit memetakan jejaring rujukan yang ada dan membuat program pembinaan setiap tahun.', 8, 'Telah dilakukan evaluasi program pembinaan evaluasi program pembinaan jejaring rujukan. jejaring rujukan 2. Penurunan Angka Kesakitan Tuberkulosis/TBC', 'Bukti laporan pelaksanaan', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('Prognas.2.1', 'Prognas', 30, 'Program Nasional', 4, 'Prognas 2', 'Rumah sakit melaksanakan program penanggulangan tuberkulosis.', 'Pemerintah mengeluarkan kebijakan penanggulangan tuberkulosis berupa upaya kesehatan yang mengutamakan aspek promotif, preventif, tanpa mengabaikan aspek kuratif dan rehabilitatif yang ditujukan untuk melindungi kesehatan masyarakat, menurunkan angka kesakitan, kecatatan atau kematian, memutuskan penularan mencegah resistensi obat dan mengurangi dampak negatif yang ditimbulkan akibat tuberkulosis. Rumah sakit dalam melaksanakan penanggulangan tuberkulosis melakukan kegiatan yang meliputi: 1) Promosi kesehatan yang diarahkan untuk meningkatkan pengetahuan yang benar dan komprehensif mengenai pencegahan penularan, penobatan, pola hidup bersih dan sehat (PHBS) sehingga terjadi perubahan sikap dan perilaku sasaran yaitu pasien dan keluarga, pengunjung serta staf rumah sakit. 2) Surveilans tuberkulosis, merupakan kegiatan memperoleh data epidemiologi yang diperlukan dalam sistem informasi program penanggulangan tuberkulosis, seperti pencatatan dan pelaporan tuberkulosis sensitif obat, pencatatan dan pelaporan tuberkulosis resistensi obat. 3) Pengendalian faktor risiko tuberkulosis, ditujukan untuk mencegah, mengurangi penularan dan kejadian penyakit tuberkulosis, yang pelaksanaannya sesuai dengan pedoman pengendalian pencegahan infeksi tuberkulosis di rumah sakit pengendalian faktor risiko tuberkulosis, ditujukan untuk mencegah, mengurangi penularan dan kejadian penyakit tuberkulosis, yang pelaksanaannya sesuai dengan pedoman pengendalian pencegahan infeksi tuberkulosis di rumah sakit. 4) Penemuan dan penanganan kasus tuberkulosis. Penemuan kasus tuberkulosis dilakukan melalui pasien yang datang kerumah sakit, setelah pemeriksaan, penegakan diagnosis, penetapan klarifikasi dan tipe pasien tuberkulosis. Sedangkan untuk penanganan kasus dilaksanakan sesuai tata laksana pada pedoman nasional pelayanan kedokteran tuberkulosis dan standar lainnya sesuai dengan peraturan perundang- undangan. 5) Pemberian kekebalan Pemberian kekebalan dilakukan melalui pemberian imunisasi BCG terhadap bayi dalam upaya penurunan risiko tingkat pemahaman tuberkulosis sesuai dengan peraturan perundang-undangan. 6) Pemberian obat pencegahan. Pemberian obat pencegahan selama 6 (enam) bulan yang ditujukan pada anak usia dibawah 5 (lima) tahun yang kontak erat dengan pasien tuberkulosis aktif; orang dengan HIV dan AIDS (ODHA) yang tidak terdiagnosis tuberkulosis; populasi tertentu lainnya sesuai peraturan perundang- undangan. Untuk menjalankan kegiatan tersebut maka rumah sakit dapat membentuk tim/panitia pelaksana program TB Paru Rumah Sakit.', 9, 'Rumah sakit menerapkan regulasi tentang pelaksanaan penanggulangan tuberkulosis penanggulangan tuberkulosis di rumah sakit di rumah sakit.', 'Regulasi tentang pelaksanaan', 'R', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
