INSERT INTO starkes_ep (kd_ep, bab, urutan_bab, nama_bab, kelompok, standar, nama_standar, maksud_tujuan, nomor_ep, deskripsi, kelengkapan_bukti, jenis_bukti, bobot, prioritas, versi_kepmenkes, sumber_seed, status) VALUES ('Prognas.6.1.d', 'Prognas', 30, 'Program Nasional', 4, 'Prognas 6.1', 'Rumah sakit mengembangkan dan menerapkan penggunaan antimikroba secara bijak berdasarkan prinsip penatagunaan antimikroba (PGA).', 'Penggunaan antimikroba secara bijak adalah penggunaan antimikroba secara rasional dengan mempertimbangkan dampak muncul dan menyebarnya mikroba resistan. Penerapan penggunaan antimikroba secara bijak berdasarkan prinsip penatagunaan antimikroba (PGA), atau antimicrobial stewardship (AMS) adalah kegiatan strategis dan sistematis, yang terpadu dan terorganisasi di rumah sakit, bertujuan mengoptimalkan penggunaan antimikroba secara bijak, baik kuantitas maupun kualitasnya, diharapkan dapat menurunkan tekanan selektif terhadap mikroba, sehingga dapat mengendalikan Resistensi antimikroba. Kegiatan ini dimulai dari tahap penegakan diagnosis penyakit infeksi, penggunaan antimikroba berdasarkan indikasi, pemilihan jenis antimikroba yang tepat, termasuk dosis, rute, saat, dan lama pemberiannya. Dilanjutkan dengan pencatatan dan pemantauan keberhasilan dan/atau kegagalan terapi, potensial dan aktual jika terjadi reaksi yang tidak dikehendaki, interaksi antimikroba dengan obat lain, dengan makanan, dengan pemeriksaan laboratorium, dan reaksi alergi. Yang dimaksud obat antimikroba meliputi: antibiotik (antibakteri), antijamur, antivirus, dan antiparasit. Pada penatagunaan antibiotik, dalam melaksanakan pengendaliannya dilakukan dengan cara mengelompokkan antibiotik dalam kategori Access, Watch, Reserve (AWaRe). Kebijakan kategorisasi ini mendukung rencana aksi nasional dan global WHO dalam menekan munculnya bakteri resistan dan mempertahankan kemanfaatan antibiotik dalam jangka panjang. Rumah sakit menyusun dan mengembangkan panduan penggunaan antimikroba untuk pengobatan infeksi (terapi) dan pencegahan infeksi pada tindakan pembedahan (profilaksis), serta panduan praktik klinis penyakit infeksi yang berbasis bukti ilmiah dan peraturan perundangan. Rumah sakit menetapkan mekanisme untuk mengawasi pelaksanaan PGA dan memantau berdasarkan indikator keberhasilan program sesuai dengan ketentuan peraturan perundang-undangan.', 46, 'Rumah sakit telah melaksanakan pemantauan evaluasi indikator dan evaluasi secara penatagunaan antimikroba bersinambung terhadap (PGA) yang dilaporkan kepada indikator penatagunaan direktur. antimikroba (PGA).', 'Bukti pemantauan dan', 'D', 10, 3, '1596/2024', '47104-parser', 'aktif') ON DUPLICATE KEY UPDATE urutan_bab=VALUES(urutan_bab), nama_bab=VALUES(nama_bab), kelompok=VALUES(kelompok), standar=VALUES(standar), nama_standar=VALUES(nama_standar), maksud_tujuan=VALUES(maksud_tujuan), nomor_ep=VALUES(nomor_ep), deskripsi=VALUES(deskripsi), kelengkapan_bukti=VALUES(kelengkapan_bukti), jenis_bukti=VALUES(jenis_bukti), versi_kepmenkes=VALUES(versi_kepmenkes), sumber_seed=VALUES(sumber_seed);
